insert into public.quiz_categories (slug, title)
values ('minecraft', 'MineMind Fan Quiz')
on conflict (slug) do nothing;

-- Per-locale packs from the first content release; kept for answer history.
update public.question_packs
set is_active = false
where locale is not null and slug like 'minecraft-%';

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, null, '8-12', 'easy', 'MineMind easy', 'minecraft-easy', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active, v.kind, v.media, v.option_icons
from public.question_packs pack
cross join (values
  ('badlands-has-terracotta', 'Hills with stripes of colored terracotta are a sign of which biome?', 'Savanna', 'Desert', 'Badlands', 'Plains', 2, 'Badlands hills are made of layers of colored terracotta and red sand.', 1, true, 'choice', null::jsonb, null::text[]),
  ('bamboo-jungle-has-bamboo', 'Pandas spawn most often in which biome?', 'Bamboo Jungle', 'Cherry Grove', 'Taiga', 'Savanna', 0, 'Pandas eat bamboo, so they show up most often in bamboo jungles.', 2, true, 'choice', null::jsonb, null::text[]),
  ('beach-is-sandy-shore', 'Which biome forms the sandy strip between land and ocean?', 'Desert', 'Beach', 'River', 'Stony Shore', 1, 'Beaches are thin sandy borders where land meets the ocean, and turtles spawn there.', 3, true, 'choice', null::jsonb, null::text[]),
  ('cherry-grove-has-pink-trees', 'Which biome is known for trees with pink leaves?', 'Flower Forest', 'Meadow', 'Cherry Grove', 'Birch Forest', 2, 'Cherry groves are full of cherry trees whose pink petals drift to the ground.', 4, true, 'choice', null::jsonb, null::text[]),
  ('desert-has-no-rain', 'In which biome does it never rain?', 'Plains', 'Jungle', 'Forest', 'Desert', 3, 'Deserts are too hot and dry for rain, so storms only darken the sky there.', 5, true, 'choice', null::jsonb, null::text[]),
  ('jungle-has-vines', 'Which biome has giant trees covered in vines and cocoa pods?', 'Dark Forest', 'Taiga', 'Jungle', 'Birch Forest', 2, 'Jungles grow huge trees wrapped in vines, with cocoa pods on their trunks.', 6, true, 'choice', null::jsonb, null::text[]),
  ('mushroom-fields-has-giant-mushrooms', 'Which rare island biome has purple-gray ground and red-spotted cows?', 'Swamp', 'Mushroom Fields', 'Dark Forest', 'Beach', 1, 'Mushroom fields are ocean islands covered in mycelium, home to mooshrooms.', 7, true, 'choice', null::jsonb, null::text[]),
  ('ocean-mostly-water', 'Dolphins swim in which large, deep-water biome?', 'Swamp', 'Ocean', 'River', 'Mangrove Swamp', 1, 'Dolphins spawn in oceans, and swimming next to them gives you a speed boost.', 8, true, 'choice', null::jsonb, null::text[]),
  ('plains-open-grassland', 'Which biome is flat and grassy with only a few scattered trees?', 'Jungle', 'Forest', 'Taiga', 'Plains', 3, 'Plains are wide grasslands with rare oak trees, where horses and villages are common.', 9, true, 'choice', null::jsonb, null::text[]),
  ('river-cuts-through-land', 'Which biome is a long, winding strip of water across the land?', 'River', 'Swamp', 'Ocean', 'Beach', 0, 'Rivers snake between other biomes, and salmon swim in them.', 10, true, 'choice', null::jsonb, null::text[]),
  ('savanna-has-acacia-trees', 'Where would a player find acacia trees most often?', 'Savanna', 'Dark Forest', 'Taiga', 'Birch Forest', 0, 'Savannas are dry grasslands dotted with flat-topped acacia trees.', 11, true, 'choice', null::jsonb, null::text[]),
  ('snowy-plains-has-snow', 'Which biome is flat, frozen land with almost no trees?', 'Snowy Plains', 'Snowy Taiga', 'Snowy Slopes', 'Frozen Ocean', 0, 'Snowy plains are flat fields of snow where water freezes into ice.', 12, true, 'choice', null::jsonb, null::text[]),
  ('swamp-has-lily-pads', 'Which biome has murky green water full of lily pads?', 'Jungle', 'Swamp', 'River', 'Taiga', 1, 'Swamps have murky water, lily pads and oak trees draped in vines.', 13, true, 'choice', null::jsonb, null::text[]),
  ('taiga-has-spruce', 'Which tree is especially common in a taiga?', 'Acacia', 'Mangrove', 'Spruce', 'Cherry', 2, 'Taigas are chilly forests full of spruce trees and sweet berry bushes.', 14, true, 'choice', null::jsonb, null::text[]),
  ('village-has-villagers', 'Which structure has houses, crop fields and a bell?', 'Pillager Outpost', 'Village', 'Igloo', 'Ruined Portal', 1, 'Villages give shelter, food and trades, and villagers gather at the bell.', 15, true, 'choice', null::jsonb, null::text[]),
  ('cobblestone-from-stone', 'What block drops when you mine stone with a normal pickaxe?', 'Smooth Stone', 'Gravel', 'Stone Bricks', 'Cobblestone', 3, 'Stone breaks into cobblestone unless your pickaxe has Silk Touch, which keeps it as stone.', 16, true, 'choice', null::jsonb, null::text[]),
  ('glass-is-see-through', 'Which block can you see through, making it great for windows?', 'Glass', 'Terracotta', 'Cobblestone', 'Wool', 0, 'Glass is transparent, so it lets light in and lets you watch outside while keeping mobs out.', 17, true, 'choice', null::jsonb, null::text[]),
  ('obsidian-from-water-and-lava', 'What block forms when water flows onto a lava source block?', 'Basalt', 'Obsidian', 'Magma Block', 'Clay', 1, 'Water turns a lava source into obsidian, which is how many players get blocks for a Nether portal.', 18, true, 'choice', null::jsonb, null::text[]),
  ('planks-build-starter-house', 'How many planks do you get from crafting one log?', '4', '8', '2', '6', 0, 'One log always gives four planks, just enough for a crafting table.', 19, true, 'choice', null::jsonb, null::text[]),
  ('sand-falls-with-gravity', 'Which block falls down if there is no block under it?', 'Oak Planks', 'Sand', 'Stone Bricks', 'Bookshelf', 1, 'Sand obeys gravity, so it drops as soon as the block below it is gone.', 20, true, 'choice', null::jsonb, null::text[]),
  ('ladder-climbs-wall', 'Which block lets you climb straight up a wall?', 'Ladder', 'Fence', 'Carpet', 'Glass Pane', 0, 'Ladders attach to the side of a block and let you climb up or down vertically.', 21, true, 'choice', null::jsonb, null::text[]),
  ('slab-is-half-block', 'Which building block is exactly half as tall as a full block?', 'Stairs', 'Carpet', 'Slab', 'Trapdoor', 2, 'Slabs are half-height, perfect for smooth floors, roofs and small steps.', 22, true, 'choice', null::jsonb, null::text[]),
  ('trapdoor-covers-hole', 'Which hinged block lies flat and can cover a one-block hole in the floor?', 'Pressure Plate', 'Fence Gate', 'Door', 'Trapdoor', 3, 'A trapdoor flips open and shut over a single block space, making it a perfect floor hatch.', 23, true, 'choice', null::jsonb, null::text[]),
  ('coal-fuels-furnace', 'Which item is the most common fuel for a furnace?', 'Sand', 'Coal', 'Cobblestone', 'String', 1, 'One piece of coal burns long enough to smelt 8 items, so it is the go-to furnace fuel.', 24, true, 'choice', null::jsonb, null::text[]),
  ('crafting-table-basics', 'Which block gives you a 3×3 grid for making tools and items?', 'Chest', 'Crafting Table', 'Furnace', 'Bed', 1, 'Your inventory only has a 2×2 grid, so bigger recipes like tools need a crafting table.', 25, true, 'choice', null::jsonb, null::text[]),
  ('furnace-smelts-raw-iron', 'Which block turns raw iron into iron ingots when you add fuel?', 'Barrel', 'Furnace', 'Composter', 'Anvil', 1, 'A furnace burns fuel to smelt ores, so raw iron comes out as ingots.', 26, true, 'choice', null::jsonb, null::text[]),
  ('planks-from-logs', 'How many iron ingots does it take to craft a block of iron?', '6', '9', '4', '8', 1, 'Nine ingots fill the whole 3×3 grid, and the block can be turned back into nine ingots.', 27, true, 'choice', null::jsonb, null::text[]),
  ('sticks-from-planks', 'Which item made from planks is the handle in most tool recipes?', 'Ladder', 'Button', 'Bowl', 'Stick', 3, 'Two planks stacked make four sticks, and tools, torches and signs all need them.', 28, true, 'choice', null::jsonb, null::text[]),
  ('pickaxe-mines-stone', 'Which tool do you need for mined stone to drop anything?', 'Axe', 'Shovel', 'Pickaxe', 'Hoe', 2, 'Stone mined by hand or with any other tool drops nothing, so a pickaxe is required.', 29, true, 'choice', null::jsonb, null::text[]),
  ('carrots-breed-pigs', 'Which food can you use to breed pigs?', 'Wheat', 'Carrot', 'Kelp', 'Red Mushroom', 1, 'Pigs love root crops: carrots, potatoes and beetroots all make them breed, but wheat does not.', 30, true, 'choice', null::jsonb, null::text[]),
  ('chickens-lay-eggs', 'What does a chicken drop by itself every few minutes?', 'Feather', 'Egg', 'Leather', 'Wheat Seeds', 1, 'Chickens lay an egg every 5–10 minutes; feathers only drop when a chicken is killed.', 31, true, 'choice', null::jsonb, null::text[]),
  ('cow-drops-leather', 'Which animal can drop leather?', 'Cow', 'Pig', 'Sheep', 'Chicken', 0, 'Cows drop leather and raw beef, so a cow farm gives you both food and leather for books and armor.', 32, true, 'choice', null::jsonb, null::text[]),
  ('sheep-give-wool', 'Which animal can you shear to get wool?', 'Goat', 'Cow', 'Pig', 'Sheep', 3, 'Sheared sheep regrow their wool after eating grass, so they give wool again and again.', 33, true, 'choice', null::jsonb, null::text[]),
  ('wheat-grows-from-seeds', 'Breaking grass can drop seeds. Which crop do they grow into?', 'Carrot', 'Cactus', 'Sugar Cane', 'Wheat', 3, 'Grass drops wheat seeds, which is why wheat is usually the very first crop a new player plants.', 34, true, 'choice', null::jsonb, null::text[]),
  ('bone-meal-speeds-growth', 'Which item makes crops grow faster when you use it on them?', 'Paper', 'Bone Meal', 'Gunpowder', 'Sugar', 1, 'Bone meal pushes a crop forward one or more growth stages at once, so you don''t have to wait.', 35, true, 'choice', null::jsonb, null::text[]),
  ('bucket-collects-cow-milk', 'What do you use on a cow to collect milk?', 'Glass Bottle', 'Bowl', 'Bucket', 'Shears', 2, 'Milk is a liquid like water, so it is carried in a bucket; a milk bucket also removes potion effects.', 36, true, 'choice', null::jsonb, null::text[]),
  ('hoe-makes-farmland', 'Which tool turns dirt into farmland?', 'Pickaxe', 'Hoe', 'Shears', 'Shovel', 1, 'Seeds can only be planted on farmland, so tilling dirt with a hoe is the first step of any farm.', 37, true, 'choice', null::jsonb, null::text[]),
  ('creeper-explodes', 'Which hostile mob hisses right before it explodes?', 'Creeper', 'Zombie', 'Skeleton', 'Spider', 0, 'Creepers sneak up silently, hiss for a moment and then blow up, damaging players and blocks.', 38, true, 'choice', null::jsonb, null::text[]),
  ('large-slime-splits', 'Which green bouncing mob splits into smaller copies when defeated?', 'Slime', 'Witch', 'Creeper', 'Enderman', 0, 'A big slime breaks into several smaller slimes, and the medium ones split again.', 39, true, 'choice', null::jsonb, null::text[]),
  ('skeleton-uses-bow', 'Which common hostile mob shoots arrows at you with a bow?', 'Creeper', 'Skeleton', 'Zombie', 'Slime', 1, 'Skeletons attack from range, so a shield or cover helps a lot against them.', 40, true, 'choice', null::jsonb, null::text[]),
  ('spider-climbs-walls', 'Which hostile mob can climb straight up walls?', 'Spider', 'Enderman', 'Creeper', 'Zombie', 0, 'Spiders climb vertical surfaces, so a plain wall won''t keep them out of your base.', 41, true, 'choice', null::jsonb, null::text[]),
  ('zombies-burn-in-day', 'Which of these mobs catches fire in direct sunlight?', 'Spider', 'Zombie', 'Creeper', 'Witch', 1, 'Zombies burn in daylight unless they stand in shade or water or wear a helmet.', 42, true, 'choice', null::jsonb, null::text[]),
  ('button-short-redstone-pulse', 'Which redstone power source turns on for a moment, then switches off by itself?', 'Block of Redstone', 'Redstone Torch', 'Button', 'Lever', 2, 'A button gives a short pulse and turns off, while a lever, torch or redstone block stays powered.', 43, true, 'choice', null::jsonb, null::text[]),
  ('flint-and-steel-lights-portal', 'Which tool do players usually use to light a Nether portal?', 'Flint and Steel', 'Shears', 'Compass', 'Spyglass', 0, 'Flint and steel sets fire inside the obsidian frame, which turns it into a working portal.', 44, true, 'choice', null::jsonb, null::text[]),
  ('nether-portal-needs-obsidian', 'Which block is a Nether portal frame built from?', 'Cobblestone', 'Netherrack', 'Obsidian', 'Blackstone', 2, 'Only obsidian works for the frame; mine it with a diamond pickaxe or make it from water and lava.', 45, true, 'choice', null::jsonb, null::text[]),
  ('redstone-dust-carries-power', 'Which dust is laid on the ground like a wire to carry a signal from a lever to a piston?', 'Sugar', 'Redstone Dust', 'Gunpowder', 'Glowstone Dust', 1, 'Redstone dust forms wires that carry a signal up to 15 blocks before it fades out.', 46, true, 'choice', null::jsonb, null::text[]),
  ('soul-sand-slows-movement', 'Which Nether block slows you down when you walk on it?', 'Netherrack', 'Blackstone', 'Basalt', 'Soul Sand', 3, 'Soul sand is slightly lower than a full block, so you sink in and walk more slowly.', 47, true, 'choice', null::jsonb, null::text[]),
  ('lever-toggles-circuit', 'Which switch stays on or off until you flip it again?', 'Lever', 'Button', 'Pressure Plate', 'Tripwire Hook', 0, 'A lever keeps its position and gives steady power, while buttons and plates switch off by themselves.', 48, true, 'choice', null::jsonb, null::text[]),
  ('bed-sets-respawn', 'Which item lets you sleep and set your respawn point?', 'Boat', 'Chest', 'Bed', 'Banner', 2, 'Sleeping in a bed skips the night and sets your respawn point next to it.', 49, true, 'choice', null::jsonb, null::text[]),
  ('cooked-food-better-hunger', 'Which of these foods restores the most hunger?', 'Melon Slice', 'Cooked Porkchop', 'Raw Porkchop', 'Apple', 1, 'Cooked porkchop restores 8 hunger points, far more than raw meat, an apple or melon.', 50, true, 'choice', null::jsonb, null::text[]),
  ('eating-refills-hunger', 'Which bar fills up when you eat food?', 'Air Bar', 'Armor Bar', 'Experience Bar', 'Hunger Bar', 3, 'Food refills the hunger bar, and a full bar lets you sprint and regenerate health.', 51, true, 'choice', null::jsonb, null::text[]),
  ('shelter-before-first-night', 'What should you build before your first night to stay safe?', 'Nether Portal', 'Shelter', 'Beacon', 'Enchanting Table', 1, 'Hostile mobs spawn in the dark, so a simple closed shelter keeps you safe on night one.', 52, true, 'choice', null::jsonb, null::text[]),
  ('torch-lights-caves', 'What do players place to light up dark caves?', 'Door', 'Sign', 'Torch', 'Chest', 2, 'Torches give off light, so you can see in caves and fewer monsters spawn nearby.', 53, true, 'choice', null::jsonb, null::text[]),
  ('barrel-makes-fisherman', 'Which job block turns a villager into a fisherman?', 'Cauldron', 'Smoker', 'Composter', 'Barrel', 3, 'A villager that claims a barrel becomes a fisherman, who trades fish and fishing rods.', 54, true, 'choice', null::jsonb, null::text[]),
  ('bookshelves-boost-enchanting', 'Which block placed around an enchanting table unlocks stronger enchantments?', 'Barrel', 'Bookshelf', 'Lectern', 'Lantern', 1, 'Each bookshelf near the table raises the enchantment levels it offers, up to level 30.', 55, true, 'choice', null::jsonb, null::text[]),
  ('composter-makes-farmer', 'Which job block turns a villager into a farmer?', 'Barrel', 'Loom', 'Smoker', 'Composter', 3, 'Villagers take the job of the block they claim, and the composter belongs to farmers.', 56, true, 'choice', null::jsonb, null::text[]),
  ('emeralds-for-trading', 'Which gem do villagers use as money when trading?', 'Diamond', 'Nether Quartz', 'Amethyst Shard', 'Emerald', 3, 'Villagers buy and sell almost everything for emeralds, so they work like village money.', 57, true, 'choice', null::jsonb, null::text[]),
  ('lapis-for-enchanting', 'Which item does an enchanting table use up along with your levels?', 'Redstone Dust', 'Lapis Lazuli', 'Amethyst Shard', 'Diamond', 1, 'Each enchantment at the table costs 1 to 3 lapis lazuli, placed in the slot next to the item.', 58, true, 'choice', null::jsonb, null::text[]),
  ('librarian-sells-books', 'Which villager can sell you enchanted books?', 'Librarian', 'Cartographer', 'Farmer', 'Cleric', 0, 'Librarians trade enchanted books for emeralds and books, even rare ones like Mending.', 59, true, 'choice', null::jsonb, null::text[]),
  ('villagers-sleep-in-beds', 'What do villagers sleep in at night?', 'Bed', 'Carpet', 'Barrel', 'Hay Bale', 0, 'Every villager claims a bed as its home and goes to sleep in it when night falls.', 60, true, 'choice', null::jsonb, null::text[]),
  ('anvil-can-rename-items', 'Which helmet enchantment lets you stay underwater longer before running out of air?', 'Protection', 'Respiration', 'Depth Strider', 'Aqua Affinity', 1, 'Respiration adds extra time before you start drowning, and each level adds more.', 61, true, 'choice', null::jsonb, null::text[]),
  ('enchanted-books-applied-with-anvil', 'Which boot enchantment reduces fall damage?', 'Thorns', 'Soul Speed', 'Depth Strider', 'Feather Falling', 3, 'Feather Falling softens hard landings, and at level IV it saves you from many big drops.', 62, true, 'choice', null::jsonb, null::text[]),
  ('lectern-makes-librarian', 'Which job block turns a villager into a librarian?', 'Lectern', 'Composter', 'Cauldron', 'Brewing Stand', 0, 'The lectern is the librarian''s job block, so placing one near an unemployed villager gets you a librarian.', 63, true, 'choice', null::jsonb, null::text[]),
  ('three-enchanting-choices', 'How many enchantment options does an enchanting table show at once?', '6', '1', '4', '3', 3, 'The table always shows three options, and each lower one costs more lapis and levels.', 64, true, 'choice', null::jsonb, null::text[]),
  ('unemployed-villager-claims-job-block', 'What must an unemployed villager claim to start trading?', 'Campfire', 'Job block', 'Bed', 'Bell', 1, 'A villager with no profession can''t trade until it links to a free job block like a lectern.', 65, true, 'choice', null::jsonb, null::text[]),
  ('efficiency-speeds-mining', 'Which enchantment makes a pickaxe dig faster?', 'Unbreaking', 'Fortune', 'Efficiency', 'Sharpness', 2, 'Efficiency raises mining speed, and each higher level makes digging even quicker.', 66, true, 'choice', null::jsonb, null::text[]),
  ('protection-reduces-damage', 'Which armor enchantment lowers damage from almost every source?', 'Depth Strider', 'Respiration', 'Feather Falling', 'Protection', 3, 'Protection cuts most kinds of damage, unlike Fire or Blast Protection, which guard against one danger.', 67, true, 'choice', null::jsonb, null::text[]),
  ('silk-touch-drops-glass', 'Which sword enchantment sets the mobs you hit on fire?', 'Looting', 'Fire Aspect', 'Smite', 'Knockback', 1, 'Fire Aspect burns mobs after each hit, and animals defeated this way drop cooked meat.', 68, true, 'choice', null::jsonb, null::text[]),
  ('hearts-show-player-health', 'Which icons on the screen show your health?', 'Armor Icons', 'Bubbles', 'Hearts', 'Drumsticks', 2, 'Each full heart is 2 health points, and losing them all means you die.', 69, true, 'choice', null::jsonb, null::text[]),
  ('armor-cuts-incoming-damage', 'Which equipment reduces the damage mobs deal to you?', 'Saddle', 'Shears', 'Compass', 'Armor', 3, 'Each armor piece adds armor points, and more points mean less damage from hits.', 70, true, 'choice', null::jsonb, null::text[]),
  ('night-more-hostile-spawns', 'Which item shows whether it is day or night, even deep underground?', 'Clock', 'Compass', 'Recovery Compass', 'Spyglass', 0, 'A clock''s dial shows the sun and moon, so you know when it''s safe to leave your shelter.', 71, true, 'choice', null::jsonb, null::text[]),
  ('door-closes-base-entrance', 'Which block at a shelter entrance keeps mobs out but lets you pass?', 'Flower Pot', 'Door', 'Painting', 'Carpet', 1, 'You can open and close a door yourself, while most mobs cannot get through it.', 72, true, 'choice', null::jsonb, null::text[]),
  ('wool-used-for-bed', 'Which block is a carved pumpkin with a torch inside?', 'Sea Lantern', 'Jack o''Lantern', 'Glowstone', 'Lantern', 1, 'A jack o''lantern glows like a torch, so it lights up your shelter and even shines underwater.', 73, true, 'choice', null::jsonb, null::text[]),
  ('ladder-climbs-vertical-wall', 'Which plant hurts you when you touch it?', 'Dead Bush', 'Bamboo', 'Sugar Cane', 'Cactus', 3, 'A cactus damages anyone who touches it, so keep it away from paths and animal pens.', 74, true, 'choice', null::jsonb, null::text[]),
  ('boat-travels-over-water', 'Which item lets you travel quickly across a river or ocean?', 'Lead', 'Minecart', 'Boat', 'Saddle', 2, 'A boat floats on water and moves much faster than swimming.', 75, true, 'choice', null::jsonb, null::text[]),
  ('torch-brightens-dark-spaces', 'Besides a stick, what do you need to craft a torch?', 'Flint', 'Gunpowder', 'Bone', 'Coal', 3, 'A torch is coal or charcoal placed on top of a stick.', 76, true, 'choice', null::jsonb, null::text[]),
  ('sneaking-prevents-edge-fall', 'Which action stops you from walking off a block edge?', 'Swimming', 'Sneaking', 'Gliding', 'Sprinting', 1, 'While sneaking you stop at the edge of a block, which makes building high up safer.', 77, true, 'choice', null::jsonb, null::text[]),
  ('bucket-picks-up-water-source', 'Which item lets you pick up a water source block?', 'Bucket', 'Bowl', 'Cauldron', 'Flower Pot', 0, 'An empty bucket scoops up a water or lava source block so you can place it elsewhere.', 78, true, 'choice', null::jsonb, null::text[]),
  ('chest-stores-home-items', 'Which block do players usually craft to store lots of items at home?', 'Lantern', 'Chest', 'Bed', 'Furnace', 1, 'A chest holds 27 stacks, and two side by side become a large double chest.', 79, true, 'choice', null::jsonb, null::text[]),
  ('bed-crafted-from-wool-and-planks', 'Which item is crafted from three wool and three planks?', 'Boat', 'Bed', 'Shield', 'Ladder', 1, 'Sleeping in a bed skips the night and sets your respawn point.', 80, true, 'choice', null::jsonb, null::text[]),
  ('furnace-crafted-from-cobblestone', 'Which block is crafted from eight cobblestone placed in a ring?', 'Furnace', 'Anvil', 'Dispenser', 'Barrel', 0, 'Eight cobblestone around an empty center make a furnace for smelting ores and cooking food.', 81, true, 'choice', null::jsonb, null::text[]),
  ('four-planks-make-crafting-table', 'Which block do four planks make in the 2×2 inventory grid?', 'Barrel', 'Crafting Table', 'Bookshelf', 'Chest', 1, 'Four planks in a square make a crafting table, your first step toward bigger recipes.', 82, true, 'choice', null::jsonb, null::text[]),
  ('planks-work-as-furnace-fuel', 'Out of coal? Which of these can also fuel a furnace?', 'Planks', 'Stone', 'Glass', 'Gravel', 0, 'Wooden things burn in a furnace, and one plank smelts one and a half items.', 83, true, 'choice', null::jsonb, null::text[]),
  ('pickaxe-breaks-stone-faster', 'Which tool chops logs the fastest?', 'Shears', 'Axe', 'Shovel', 'Pickaxe', 1, 'Axes are made for wood, so logs and planks break much faster with one.', 84, true, 'choice', null::jsonb, null::text[]),
  ('stone-drops-cobblestone', 'How many diamonds does it take to craft a diamond pickaxe?', '3', '2', '5', '4', 0, 'A pickaxe needs three pieces of its material across the top and two sticks below.', 85, true, 'choice', null::jsonb, null::text[]),
  ('iron-ingots-craft-bucket', 'Which ingot is used to craft a bucket?', 'Iron Ingot', 'Netherite Ingot', 'Gold Ingot', 'Copper Ingot', 0, 'Three iron ingots in a V shape make a bucket for water, lava or milk.', 86, true, 'choice', null::jsonb, null::text[]),
  ('stone-next-tier-after-wood', 'Which tool material comes right after wood in the usual upgrade path?', 'Diamond', 'Netherite', 'Iron', 'Stone', 3, 'Stone tools need only cobblestone and sticks, yet last longer and dig faster than wooden ones.', 87, true, 'choice', null::jsonb, null::text[]),
  ('logs-turn-into-planks', 'Which part of a tree do you put in the crafting grid to get planks?', 'Sapling', 'Log', 'Leaves', 'Stick', 1, 'Logs are chopped from tree trunks, and each one crafts into planks for building.', 88, true, 'choice', null::jsonb, null::text[]),
  ('dirt-under-many-grass-blocks', 'What do you get when you dig up a grass block without Silk Touch?', 'Grass Block', 'Coarse Dirt', 'Dirt', 'Gravel', 2, 'Without Silk Touch the grass layer is lost, and the block drops as plain dirt.', 89, true, 'choice', null::jsonb, null::text[]),
  ('stairs-help-players-climb-builds', 'Which block can you walk up onto without jumping?', 'Glass Pane', 'Stairs', 'Fence', 'Chest', 1, 'Stairs rise in half-block steps, so you can walk up them without pressing jump.', 90, true, 'choice', null::jsonb, null::text[]),
  ('gravel-falls-like-sand', 'Which block sometimes drops flint when you dig it?', 'Clay', 'Dirt', 'Gravel', 'Sand', 2, 'Gravel has a small chance to drop flint, which you need for arrows and flint and steel.', 91, true, 'choice', null::jsonb, null::text[]),
  ('sandstone-crafted-from-sand', 'Which tree has white bark with black marks?', 'Spruce', 'Oak', 'Acacia', 'Birch', 3, 'Birch logs are white with dark spots, which makes birch forests easy to spot from far away.', 92, true, 'choice', null::jsonb, null::text[]),
  ('axe-creates-stripped-log', 'Which tool strips the bark off a log when you use it?', 'Hoe', 'Axe', 'Sword', 'Shovel', 1, 'Using an axe on a log or wood block strips off its bark for a cleaner look.', 93, true, 'choice', null::jsonb, null::text[]),
  ('leaves-decay-without-nearby-log', 'What do decaying tree leaves sometimes drop?', 'String', 'Seeds', 'Sapling', 'Bone Meal', 2, 'Leaves left without logs slowly decay and can drop saplings, so you can replant the tree.', 94, true, 'choice', null::jsonb, null::text[]),
  ('wheat-breeds-cows-and-sheep', 'Which crop can you use to breed cows and sheep?', 'Carrot', 'Potato', 'Beetroot', 'Wheat', 3, 'Cows, sheep and goats all eat wheat, so one wheat field can feed most of your farm animals.', 95, true, 'choice', null::jsonb, null::text[]),
  ('carrot-plants-more-carrots', 'Which crop is planted from the crop itself, with no seeds item?', 'Carrot', 'Wheat', 'Pumpkin', 'Beetroot', 0, 'Carrots, like potatoes, have no seeds: you plant a carrot and harvest several more carrots.', 96, true, 'choice', null::jsonb, null::text[]),
  ('melon-block-grows-from-melon-stem', 'Which crop block drops slices when you break it?', 'Pumpkin', 'Cactus', 'Melon', 'Hay Bale', 2, 'A melon block breaks into 3–7 slices, while a pumpkin drops itself as a whole block.', 97, true, 'choice', null::jsonb, null::text[]),
  ('three-wheat-craft-bread', 'What does raw beef turn into when you cook it in a furnace?', 'Cooked Chicken', 'Steak', 'Cooked Porkchop', 'Cooked Mutton', 1, 'Cooked beef is called steak, and it fills as much hunger as a cooked porkchop.', 98, true, 'choice', null::jsonb, null::text[]),
  ('bowl-carries-mushroom-stew', 'Besides a red and a brown mushroom, what do you need to craft mushroom stew?', 'Bucket', 'Stick', 'Bowl', 'Glass Bottle', 2, 'Stew is served in a bowl, and you get the empty bowl back after eating it.', 99, true, 'choice', null::jsonb, null::text[]),
  ('hay-bale-stores-extra-wheat', 'Which block is crafted from nine wheat?', 'Moss Block', 'Dried Kelp Block', 'Hay Bale', 'White Wool', 2, 'A hay bale packs nine wheat into one block, saving chest space and feeding horses and llamas.', 100, true, 'choice', null::jsonb, null::text[]),
  ('pandas-breed-with-bamboo', 'Which plant do you feed pandas to breed them?', 'Bamboo', 'Sugar Cane', 'Wheat', 'Kelp', 0, 'Pandas live in bamboo jungles and eat bamboo, so it is the food that makes them breed.', 101, true, 'choice', null::jsonb, null::text[]),
  ('cow-makes-moo-sound', 'Which sea creature drops ink sacs?', 'Cod', 'Squid', 'Dolphin', 'Turtle', 1, 'Squids drop ink sacs, which you use to make black dye and a book and quill.', 102, true, 'choice', null::jsonb, null::text[]),
  ('sheep-can-be-sheared', 'Which small flying mob sleeps hanging upside down in dark caves?', 'Parrot', 'Bat', 'Allay', 'Bee', 1, 'Bats hang upside down from cave ceilings and flutter around when a player comes near.', 103, true, 'choice', null::jsonb, null::text[]),
  ('bee-produces-honey', 'Which small mob fills nests and hives with honey?', 'Bat', 'Bee', 'Parrot', 'Chicken', 1, 'Bees collect pollen from flowers and bring it home, slowly filling the nest with honey.', 104, true, 'choice', null::jsonb, null::text[]),
  ('wolf-can-be-tamed-as-pet', 'Which tamed animal can you ride after putting a saddle on it?', 'Parrot', 'Wolf', 'Horse', 'Cat', 2, 'Once a horse is tamed and saddled, you can ride and steer it much faster than walking.', 105, true, 'choice', null::jsonb, null::text[]),
  ('pig-likes-carrots', 'Which animal can you tame by feeding it seeds?', 'Cat', 'Chicken', 'Wolf', 'Parrot', 3, 'Feeding seeds tames a parrot, and after that it can ride on your shoulder.', 106, true, 'choice', null::jsonb, null::text[]),
  ('shield-blocks-many-hits', 'Besides sticks, which item do you need to craft a bow?', 'Leather', 'Feather', 'String', 'Wool', 2, 'Three sticks and three string make a bow, and spiders are the easiest source of string.', 107, true, 'choice', null::jsonb, null::text[]),
  ('sword-is-basic-melee-weapon', 'Which crafted item is made mainly for close-range fighting?', 'Sword', 'Hoe', 'Shovel', 'Bucket', 0, 'A sword is the basic melee weapon and deals more damage than tools like a hoe or shovel.', 108, true, 'choice', null::jsonb, null::text[]),
  ('bow-fires-arrows', 'Which weapon do you pull back to shoot arrows at faraway mobs?', 'Trident', 'Bow', 'Sword', 'Axe', 1, 'A bow lets you attack from a safe distance; the longer you pull it back, the harder it hits.', 109, true, 'choice', null::jsonb, null::text[]),
  ('armor-reduces-attack-damage', 'Which full armor set protects you the least?', 'Diamond Armor', 'Leather Armor', 'Netherite Armor', 'Iron Armor', 1, 'Leather is the weakest armor, while diamond and netherite give the most protection.', 110, true, 'choice', null::jsonb, null::text[]),
  ('torches-help-stop-spawns', 'Which sword deals the most damage?', 'Diamond Sword', 'Stone Sword', 'Netherite Sword', 'Iron Sword', 2, 'Netherite is the strongest material, so its sword hits harder than a diamond one and lasts longer.', 111, true, 'choice', null::jsonb, null::text[]),
  ('ender-pearl-drops-from-enderman', 'Which mob drops pearls that teleport you when thrown?', 'Phantom', 'Enderman', 'Shulker', 'Endermite', 1, 'Endermen drop ender pearls, which you also need later to craft Eyes of Ender.', 112, true, 'choice', null::jsonb, null::text[]),
  ('end-portal-opens-path-to-end', 'Which portal takes you from the Overworld to the dragon''s dimension?', 'Nether Portal', 'End Gateway', 'End Portal', 'Ruined Portal', 2, 'An End portal sits inside a stronghold and starts working once every frame holds an Eye of Ender.', 113, true, 'choice', null::jsonb, null::text[]),
  ('ender-dragon-is-end-boss', 'Which boss waits on the main island after you jump into the stronghold portal?', 'Elder Guardian', 'Warden', 'Ender Dragon', 'Wither', 2, 'The Ender Dragon guards the main island, and defeating it opens the exit portal back home.', 114, true, 'choice', null::jsonb, null::text[]),
  ('stronghold-contains-end-portal', 'End City towers are built from end stone bricks and which other block?', 'Block of Amethyst', 'Purpur Block', 'Crying Obsidian', 'Prismarine', 1, 'Purpur blocks give End cities their purple color, so they are the easiest place to collect them.', 115, true, 'choice', null::jsonb, null::text[]),
  ('end-stone-covers-end-islands', 'Which pale yellow block forms the ground of the dragon''s islands?', 'Smooth Stone', 'Bone Block', 'End Stone', 'Sandstone', 2, 'End stone makes up almost all the land in the End and holds up well against explosions.', 116, true, 'choice', null::jsonb, null::text[]),
  ('redstone-torch-provides-power', 'Which light source also gives constant power to circuits?', 'Torch', 'Redstone Torch', 'Soul Torch', 'Lantern', 1, 'A redstone torch stays on until the block it is attached to gets powered, which turns it off.', 117, true, 'choice', null::jsonb, null::text[]),
  ('pressure-plate-triggers-on-step', 'Which light block glows only while it is powered?', 'Sea Lantern', 'Glowstone', 'Shroomlight', 'Redstone Lamp', 3, 'A redstone lamp shines while it gets a signal and goes dark without one, unlike always-on light blocks.', 118, true, 'choice', null::jsonb, null::text[]),
  ('piston-pushes-block-forward', 'Which ore glows when you touch it or walk on it?', 'Coal Ore', 'Redstone Ore', 'Diamond Ore', 'Lapis Lazuli Ore', 1, 'Redstone ore lights up when touched and drops redstone dust, the wire of every circuit.', 119, true, 'choice', null::jsonb, null::text[]),
  ('strider-walks-on-lava', 'Which rideable mob can walk across Nether lava lakes?', 'Hoglin', 'Strider', 'Horse', 'Pig', 1, 'Striders walk on lava without burning, so with a saddle they carry you safely across.', 120, true, 'choice', null::jsonb, null::text[]),
  ('tf-cooked-meat-fills-less', 'Cooked meat fills less hunger than the same meat eaten raw.', 'True', 'False', null, null, 1, 'False: cooking meat makes it fill much more hunger, so a furnace is always worth it.', 121, true, 'true-false', null::jsonb, null::text[]),
  ('tf-cactus-hurts-on-touch', 'Touching a cactus hurts you.', 'True', 'False', null, null, 0, 'True: a cactus damages players and mobs that touch it, and it even destroys dropped items.', 122, true, 'true-false', null::jsonb, null::text[]),
  ('tf-planks-from-any-log', 'You can craft planks from any kind of log.', 'True', 'False', null, null, 0, 'True: every log, from oak to birch, crafts into four planks of its own wood type.', 123, true, 'true-false', null::jsonb, null::text[]),
  ('tf-torch-on-wall-side', 'Torches can be placed on the side of a wall.', 'True', 'False', null, null, 0, 'True: a torch can stand on top of a block or hang on its side, which is handy in tunnels.', 124, true, 'true-false', null::jsonb, null::text[]),
  ('tf-dirt-falls-like-sand', 'Dirt falls down when there is no block under it.', 'True', 'False', null, null, 1, 'False: dirt stays floating in place; only blocks like sand, gravel and concrete powder fall.', 125, true, 'true-false', null::jsonb, null::text[]),
  ('tf-skeletons-burn-in-sunlight', 'Skeletons catch fire in direct sunlight.', 'True', 'False', null, null, 0, 'True: like zombies, skeletons burn in daylight unless they wear a helmet or stay in water or shade.', 126, true, 'true-false', null::jsonb, null::text[]),
  ('tf-creepers-climb-walls', 'Creepers can climb up walls just like spiders.', 'True', 'False', null, null, 1, 'False: spiders climb walls, but creepers can only walk, so a tall wall keeps them out.', 127, true, 'true-false', null::jsonb, null::text[]),
  ('tf-sheep-regrow-wool', 'A sheared sheep grows its wool back after eating grass.', 'True', 'False', null, null, 0, 'True: a sheared sheep regrows wool only after grazing on grass, so keep grass in its pen.', 128, true, 'true-false', null::jsonb, null::text[]),
  ('tf-pigs-drop-leather', 'Pigs drop leather when defeated.', 'True', 'False', null, null, 1, 'False: pigs drop only porkchops; leather comes from cows, horses, llamas and hoglins.', 129, true, 'true-false', null::jsonb, null::text[]),
  ('tf-iron-golems-protect-villagers', 'Iron golems protect villagers from monsters.', 'True', 'False', null, null, 0, 'True: iron golems patrol villages and attack hostile mobs that come near villagers.', 130, true, 'true-false', null::jsonb, null::text[]),
  ('tf-enchanting-costs-nothing', 'Enchanting at an enchanting table doesn''t use any experience levels.', 'True', 'False', null, null, 1, 'False: every enchantment costs experience levels as well as lapis lazuli.', 131, true, 'true-false', null::jsonb, null::text[]),
  ('tf-cacti-grow-in-deserts', 'Cacti grow naturally in deserts.', 'True', 'False', null, null, 0, 'True: cacti generate in deserts and badlands, often next to dead bushes.', 132, true, 'true-false', null::jsonb, null::text[]),
  ('tf-endermen-roam-the-end', 'Lots of endermen roam the End.', 'True', 'False', null, null, 0, 'True: endermen are the most common mob in the End, so try not to look them in the eyes.', 133, true, 'true-false', null::jsonb, null::text[]),
  ('tf-dragon-lives-in-nether', 'The Ender Dragon lives in the Nether.', 'True', 'False', null, null, 1, 'False: the Ender Dragon lives in the End, reached through the End portal in a stronghold.', 134, true, 'true-false', null::jsonb, null::text[]),
  ('pic-bone-dropped-by-skeleton', 'Which mob drops the item in the picture?', 'Skeleton', 'Slime', 'Creeper', 'Drowned', 0, 'Skeletons drop bones, which you can grind into bone meal or use to tame wolves.', 135, true, 'picture', '{"sprite":"bone","type":"picture"}'::jsonb, null::text[]),
  ('pic-gunpowder-from-creeper', 'Defeating which mob can give you the item shown?', 'Creeper', 'Enderman', 'Zombie', 'Spider', 0, 'Creepers drop gunpowder, the key ingredient for TNT and fireworks.', 136, true, 'picture', '{"sprite":"gunpowder","type":"picture"}'::jsonb, null::text[]),
  ('pic-string-from-spider', 'Which hostile mob leaves this item behind when defeated?', 'Spider', 'Skeleton', 'Creeper', 'Slime', 0, 'Spiders drop string, which you need for bows, fishing rods and leads.', 137, true, 'picture', '{"sprite":"string","type":"picture"}'::jsonb, null::text[]),
  ('pic-feather-from-chicken', 'Which farm animal can drop the item shown?', 'Rabbit', 'Pig', 'Chicken', 'Cow', 2, 'Chickens drop feathers, which you need to craft arrows.', 138, true, 'picture', '{"sprite":"feather","type":"picture"}'::jsonb, null::text[]),
  ('pic-cobblestone-smelts-to-stone', 'Smelting the block in the picture gives you which block?', 'Stone', 'Andesite', 'Smooth Stone', 'Gravel', 0, 'Cobblestone smelts into stone, and smelting that stone again gives smooth stone.', 139, true, 'picture', '{"sprite":"cobblestone","type":"picture"}'::jsonb, null::text[]),
  ('pic-sand-crafts-sandstone', 'Four of the block shown in a 2×2 square craft what?', 'Terracotta', 'Gravel', 'Sandstone', 'Glass', 2, 'Four sand in a square craft sandstone, a sturdy building block that doesn''t fall.', 140, true, 'picture', '{"sprite":"sand","type":"picture"}'::jsonb, null::text[]),
  ('recipe-torch-missing-stick', 'Which item is missing from this torch recipe?', 'Stick', 'Bone', 'Feather', 'Sugar Cane', 0, 'A torch is coal or charcoal on top of a stick, and one craft makes 4 torches.', 141, true, 'recipe', '{"grid":[null,null,null,null,"coal",null,null,null,null],"missingSlot":7,"type":"recipe"}'::jsonb, array['stick', 'bone', 'feather', 'sugar-cane']::text[]),
  ('recipe-wooden-pickaxe-missing-planks', 'What goes in the empty slot to finish this wooden pickaxe?', 'Planks', 'Wool', 'Cobblestone', 'Stick', 0, 'A wooden pickaxe needs three planks across the top and two sticks down the middle.', 142, true, 'recipe', '{"grid":[null,"planks","planks",null,"stick",null,null,"stick",null],"missingSlot":0,"type":"recipe"}'::jsonb, array['planks', 'wool', 'cobblestone', 'stick']::text[]),
  ('recipe-stone-sword-missing-cobblestone', 'Fill the gap: what completes this stone sword?', 'Cobblestone', 'Glass', 'Flint', 'Sand', 0, 'A stone sword is two cobblestone stacked on top of a stick.', 143, true, 'recipe', '{"grid":[null,null,null,null,"cobblestone",null,null,"stick",null],"missingSlot":1,"type":"recipe"}'::jsonb, array['cobblestone', 'glass', 'flint', 'sand']::text[]),
  ('recipe-diamond-sword-missing-stick', 'This diamond sword recipe has a gap. What fills it?', 'Bone', 'Diamond', 'Stick', 'Flint', 2, 'Every sword except netherite is two pieces of its material on top of one stick.', 144, true, 'recipe', '{"grid":[null,"diamond",null,null,"diamond",null,null,null,null],"missingSlot":7,"type":"recipe"}'::jsonb, array['bone', 'diamond', 'stick', 'flint']::text[]),
  ('recipe-furnace-missing-cobblestone', 'Which item is missing from this furnace recipe?', 'Cobblestone', 'Planks', 'Sand', 'Coal', 0, 'A furnace is eight cobblestone in a ring with the middle left empty.', 145, true, 'recipe', '{"grid":["cobblestone","cobblestone","cobblestone","cobblestone",null,null,"cobblestone","cobblestone","cobblestone"],"missingSlot":5,"type":"recipe"}'::jsonb, array['cobblestone', 'planks', 'sand', 'coal']::text[]),
  ('recipe-chest-missing-planks', 'What goes in the empty slot to finish this chest?', 'Cobblestone', 'Glass', 'Iron Ingot', 'Planks', 3, 'A chest is eight planks around an empty middle; two chests side by side make a large chest.', 146, true, 'recipe', '{"grid":["planks","planks","planks","planks",null,"planks","planks",null,"planks"],"missingSlot":7,"type":"recipe"}'::jsonb, array['cobblestone', 'glass', 'iron-ingot', 'planks']::text[]),
  ('recipe-bread-missing-wheat', 'Fill the gap: what completes this bread recipe?', 'Egg', 'Sugar Cane', 'Wheat', 'Sugar', 2, 'Bread is just three wheat in a row, an easy food once your farm is growing.', 147, true, 'recipe', '{"grid":[null,null,null,"wheat",null,"wheat",null,null,null],"missingSlot":4,"type":"recipe"}'::jsonb, array['egg', 'sugar-cane', 'wheat', 'sugar']::text[]),
  ('recipe-bed-missing-planks', 'What belongs in the empty square to craft a bed?', 'Wool', 'Planks', 'Leather', 'Cobblestone', 1, 'A bed is three wool of the same color on top of three planks.', 148, true, 'recipe', '{"grid":[null,null,null,"wool","wool","wool","planks",null,"planks"],"missingSlot":7,"type":"recipe"}'::jsonb, array['wool', 'planks', 'leather', 'cobblestone']::text[]),
  ('birch-forest-white-bark', 'Which forest is made almost only of trees with white bark?', 'Jungle', 'Birch Forest', 'Taiga', 'Dark Forest', 1, 'Birch forests are filled with birch trees, whose white bark is easy to spot.', 149, true, 'choice', null::jsonb, null::text[]),
  ('desert-pyramid-sandstone-terracotta', 'Which sandstone temple with orange and blue terracotta stands in deserts?', 'Village', 'Pillager Outpost', 'Desert Pyramid', 'Jungle Temple', 2, 'Desert pyramids are built from sandstone with orange and blue terracotta, with loot hidden inside.', 150, true, 'choice', null::jsonb, null::text[]),
  ('igloo-built-from-snow', 'Which small dome-shaped house in snowy biomes is built from snow blocks?', 'Desert Well', 'Witch Hut', 'Village', 'Igloo', 3, 'Igloos are built mostly from snow blocks and appear in snowy plains and snowy taigas.', 151, true, 'choice', null::jsonb, null::text[]),
  ('shipwreck-broken-wooden-boat', 'Which broken wooden boat can be found on the ocean floor or on beaches?', 'Buried Treasure', 'Ocean Ruins', 'Shipwreck', 'Ocean Monument', 2, 'Shipwrecks are sunken wooden ships that can hold up to three loot chests.', 152, true, 'choice', null::jsonb, null::text[]),
  ('swamp-hut-home-of-witch', 'Which mob lives in a small hut on stilts in the swamp?', 'Zombie Villager', 'Evoker', 'Witch', 'Villager', 2, 'Swamp huts come with a witch inside, plus a cauldron and a potted mushroom.', 153, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-prismarine', 'Which giant underwater building is made of prismarine and lit by sea lanterns?', 'Shipwreck', 'Trail Ruins', 'Ocean Ruins', 'Ocean Monument', 3, 'Ocean monuments are huge prismarine buildings glowing with sea lanterns, guarded by guardians.', 154, true, 'choice', null::jsonb, null::text[]),
  ('mineshaft-rails-and-cobwebs', 'Which underground structure has wooden supports, old rails and cobwebs?', 'Ancient City', 'Dungeon', 'Mineshaft', 'Stronghold', 2, 'Abandoned mineshafts are long tunnels with wooden supports, broken rails, cobwebs and chest minecarts.', 155, true, 'choice', null::jsonb, null::text[]),
  ('dungeon-cobblestone-spawner-room', 'Which small cobblestone room has a mob spawner and up to two chests?', 'Stronghold', 'Dungeon', 'Igloo', 'Mineshaft', 1, 'Dungeons are small rooms of cobblestone and mossy cobblestone with a spawner and up to two chests.', 156, true, 'choice', null::jsonb, null::text[]),
  ('ruined-portal-broken-obsidian', 'Which structure is a broken obsidian frame, sometimes with crying obsidian?', 'Ancient City', 'Ruined Portal', 'Nether Fortress', 'Desert Well', 1, 'Ruined portals are broken Nether portals made of obsidian, with some crying obsidian mixed in.', 157, true, 'choice', null::jsonb, null::text[]),
  ('end-city-purpur-towers', 'Which tall purple towers stand on the outer islands of the End?', 'End City', 'Nether Fortress', 'Bastion Remnant', 'Ancient City', 0, 'End cities are towers of purpur blocks and End stone bricks on the outer End islands.', 158, true, 'choice', null::jsonb, null::text[]),
  ('amethyst-geode-purple-crystals', 'Which round underground structure is lined with purple crystals?', 'Mineshaft', 'Ancient City', 'Dungeon', 'Amethyst Geode', 3, 'Amethyst geodes are hollow balls of smooth basalt and calcite lined with amethyst inside.', 159, true, 'choice', null::jsonb, null::text[]),
  ('desert-well-holds-water', 'Which tiny sandstone structure in the desert holds a pool of water?', 'Desert Well', 'Desert Pyramid', 'Ruined Portal', 'Igloo', 0, 'Desert wells are small sandstone structures with a water source in the middle.', 160, true, 'choice', null::jsonb, null::text[]),
  ('bastion-blackstone-piglins', 'Which huge Nether structure made of blackstone is full of piglins?', 'End City', 'Bastion Remnant', 'Ruined Portal', 'Nether Fortress', 1, 'Bastion remnants are big blackstone castles in the Nether guarded by piglins and piglin brutes.', 161, true, 'choice', null::jsonb, null::text[]),
  ('ancient-city-shriekers-lanterns', 'Which giant structure far underground is full of sculk shriekers and soul lanterns?', 'Ancient City', 'Trial Chambers', 'Mineshaft', 'Stronghold', 0, 'Ancient cities hide in the deep dark, full of sculk, soul lanterns and candles.', 162, true, 'choice', null::jsonb, null::text[]),
  ('brush-uncovers-suspicious-sand', 'Which tool do you use to dig items out of suspicious sand?', 'Brush', 'Hoe', 'Shears', 'Shovel', 0, 'A brush slowly uncovers items hidden in suspicious sand and gravel.', 163, true, 'choice', null::jsonb, null::text[]),
  ('shipwreck-map-leads-to-treasure', 'A shipwreck''s map chest holds a map whose red X marks what?', 'Buried Treasure', 'Ancient City', 'Ocean Monument', 'Stronghold', 0, 'Shipwreck map chests always hold a map leading to buried treasure, marked with a red X.', 164, true, 'choice', null::jsonb, null::text[]),
  ('ruined-portal-leads-to-nether', 'If you repair and light a ruined portal in the Overworld, where can it take you?', 'The nearest village', 'The Nether', 'The End', 'The Deep Dark', 1, 'Ruined portals are broken Nether portals: fill the gaps with obsidian, light it and step through.', 165, true, 'choice', null::jsonb, null::text[]),
  ('amethyst-cluster-gives-shards', 'Mining a fully grown amethyst cluster with a pickaxe drops what?', 'Amethyst Shards', 'Amethyst Blocks', 'Diamonds', 'Emeralds', 0, 'Grown amethyst clusters drop amethyst shards, used to craft spyglasses and tinted glass.', 166, true, 'choice', null::jsonb, null::text[]),
  ('sculk-shrieker-calls-warden', 'Which block in ancient cities can call the Warden if you make too much noise?', 'Sculk Shrieker', 'Sculk Vein', 'Sculk Catalyst', 'Sculk Sensor', 0, 'Sculk shriekers shriek when they sense you, and after a few warnings the Warden comes out.', 167, true, 'choice', null::jsonb, null::text[]),
  ('mineshaft-chests-in-minecarts', 'In a mineshaft, the loot chests always sit inside what?', 'Item Frames', 'Shulker Boxes', 'Barrels', 'Minecarts', 3, 'Every mineshaft chest is a minecart with a chest, resting on the old rails.', 168, true, 'choice', null::jsonb, null::text[]),
  ('dungeon-chests-have-name-tags', 'Which item for naming your pets is a common find in dungeon chests?', 'Lead', 'Map', 'Name Tag', 'Book', 2, 'Dungeon chests often hold name tags, which let you give a mob its own name.', 169, true, 'choice', null::jsonb, null::text[]),
  ('bastion-treasure-gold-blocks', 'Which shiny blocks are piled up in a bastion''s treasure room?', 'Blocks of Iron', 'Blocks of Emerald', 'Blocks of Gold', 'Blocks of Diamond', 2, 'Bastion treasure rooms are packed with gold blocks, guarded by piglins and lava.', 170, true, 'choice', null::jsonb, null::text[]),
  ('trial-key-unlocks-vault', 'Which item unlocks a vault in trial chambers?', 'Breeze Rod', 'Wind Charge', 'Trial Key', 'Echo Shard', 2, 'Beating a trial spawner can drop trial keys, and using one on a vault pops out loot.', 171, true, 'choice', null::jsonb, null::text[]),
  ('trial-spawner-waves-and-rewards', 'Which block in trial chambers sends out mobs, then gives rewards when you win?', 'Trial Spawner', 'Monster Spawner', 'Crafter', 'Vault', 0, 'Trial spawners send mobs to fight you, then drop rewards like trial keys once you win.', 172, true, 'choice', null::jsonb, null::text[]),
  ('village-best-place-to-trade', 'Which structure is the best place to trade emeralds with lots of villagers?', 'Woodland Mansion', 'Desert Pyramid', 'Village', 'Stronghold', 2, 'Villages are full of villagers with different jobs who trade items for emeralds.', 173, true, 'choice', null::jsonb, null::text[]),
  ('buried-treasure-dig-with-shovel', 'Buried treasure usually hides under sand. Which tool digs it up fastest?', 'Pickaxe', 'Shears', 'Axe', 'Shovel', 3, 'Buried treasure chests are usually under sand or gravel, so a shovel digs them out fastest.', 174, true, 'choice', null::jsonb, null::text[]),
  ('dungeon-chests-music-discs', 'Which item that plays in a jukebox is often found in dungeon chests?', 'Goat Horn', 'Map', 'Book', 'Music Disc', 3, 'Dungeon chests often hold music discs like 13 and cat, which play songs in a jukebox.', 175, true, 'choice', null::jsonb, null::text[]),
  ('jungle-temple-lever-puzzle-chest', 'What does solving the lever puzzle in a jungle temple reveal?', 'A hidden chest', 'A Nether portal', 'A mob spawner', 'A secret village', 0, 'Flipping the three levers in the right order opens the floor and reveals a hidden loot chest.', 176, true, 'choice', null::jsonb, null::text[]),
  ('breaking-spawner-gives-xp', 'Mining a monster spawner with a pickaxe gives you what?', 'A spawn egg', 'Only experience', 'The spawner block', 'Iron ingots', 1, 'A broken spawner drops only some experience, never the spawner block itself.', 177, true, 'choice', null::jsonb, null::text[]),
  ('jungle-temple-mossy-cobblestone', 'Which structure deep in the jungle is built from mossy cobblestone?', 'Trail Ruins', 'Desert Pyramid', 'Jungle Temple', 'Igloo', 2, 'Jungle temples are made of mossy cobblestone and hide traps and treasure.', 178, true, 'choice', null::jsonb, null::text[]),
  ('snow-block-breaks-into-snowballs', 'Dig a snow block with a shovel. What drops?', 'Clay Ball', 'Snowball', 'Ice', 'Packed Ice', 1, 'A snow block breaks into four snowballs when you dig it with a shovel.', 179, true, 'choice', null::jsonb, null::text[]),
  ('netherrack-makes-up-nether-ground', 'Which reddish block makes up most of the Nether''s ground?', 'Red Sand', 'Soul Sand', 'Netherrack', 'Magma Block', 2, 'Netherrack makes up most of the Nether''s terrain, so you see it almost everywhere there.', 180, true, 'choice', null::jsonb, null::text[]),
  ('coal-ore-drops-furnace-fuel', 'Which ore has black spots and drops fuel for your furnace?', 'Iron Ore', 'Diamond Ore', 'Redstone Ore', 'Coal Ore', 3, 'Coal ore drops coal, one of the most common furnace fuels and a torch ingredient.', 181, true, 'choice', null::jsonb, null::text[]),
  ('lapis-ore-drops-enchanting-stones', 'Which ore drops the blue stones an enchanting table uses up?', 'Diamond Ore', 'Emerald Ore', 'Redstone Ore', 'Lapis Lazuli Ore', 3, 'Lapis lazuli ore drops several pieces of lapis lazuli, which you spend each time you enchant.', 182, true, 'choice', null::jsonb, null::text[]),
  ('redstone-ore-drops-red-dust', 'Which ore drops red dust used to build circuits?', 'Iron Ore', 'Redstone Ore', 'Copper Ore', 'Nether Quartz Ore', 1, 'Redstone ore drops redstone dust, which carries power through circuits like a wire.', 183, true, 'choice', null::jsonb, null::text[]),
  ('sand-covers-deserts-and-beaches', 'Which block covers the ground in deserts and on beaches?', 'Clay', 'Snow Block', 'Gravel', 'Sand', 3, 'Sand covers deserts and beaches, and it falls down if nothing is underneath it.', 184, true, 'choice', null::jsonb, null::text[]),
  ('bedrock-unbreakable-in-survival', 'Which block can''t be broken in Survival, no matter which tool you use?', 'Obsidian', 'Ancient Debris', 'Bedrock', 'Deepslate', 2, 'Bedrock forms the bottom of the world and can''t be broken in Survival mode.', 185, true, 'choice', null::jsonb, null::text[]),
  ('ice-is-slippery', 'Which block makes you slide around when you walk on it?', 'Snow Block', 'Glass', 'Ice', 'Stone', 2, 'Ice is slippery, so you keep sliding for a moment after you stop walking.', 186, true, 'choice', null::jsonb, null::text[]),
  ('wooden-planks-burn-away', 'Which of these blocks can burn away in a fire?', 'Glass', 'Oak Planks', 'Bricks', 'Cobblestone', 1, 'Wooden blocks like planks catch fire and burn away, so keep fire and lava away from wooden houses.', 187, true, 'choice', null::jsonb, null::text[]),
  ('anvil-falls-like-sand', 'Which heavy workstation falls down if the block under it is removed?', 'Furnace', 'Crafting Table', 'Anvil', 'Enchanting Table', 2, 'Anvils fall like sand, and a falling anvil can hurt anyone standing below it.', 188, true, 'choice', null::jsonb, null::text[]),
  ('tnt-explodes-after-lighting', 'Which block explodes a few seconds after you light it?', 'Block of Redstone', 'Netherrack', 'TNT', 'Magma Block', 2, 'Once lit by fire or redstone, TNT flashes and then explodes, breaking most blocks nearby.', 189, true, 'choice', null::jsonb, null::text[]),
  ('grass-spreads-onto-dirt', 'Bare dirt next to which block slowly turns green?', 'Coarse Dirt', 'Gravel', 'Grass Block', 'Sand', 2, 'Grass blocks with enough light slowly spread onto nearby dirt, turning it into grass.', 190, true, 'choice', null::jsonb, null::text[]),
  ('vines-can-be-climbed', 'Which plant hanging on walls can you climb like a ladder?', 'Sugar Cane', 'Bamboo', 'Leaves', 'Vines', 3, 'Vines can be climbed: stand next to them and hold jump to go up.', 191, true, 'choice', null::jsonb, null::text[]),
  ('glowstone-lights-up-dark', 'Which Nether block glows and lights up dark places?', 'Basalt', 'Glowstone', 'Netherrack', 'Soul Sand', 1, 'Glowstone gives off light level 15, the brightest light in the game.', 192, true, 'choice', null::jsonb, null::text[]),
  ('lily-pad-floats-on-water', 'Which plant can you place on top of water and stand on?', 'Sugar Cane', 'Kelp', 'Lily Pad', 'Seagrass', 2, 'Lily pads float on water and work like a tiny platform you can walk across.', 193, true, 'choice', null::jsonb, null::text[]),
  ('sign-holds-written-message', 'You want to leave a written message on a wall. Which block do you place?', 'Item Frame', 'Sign', 'Painting', 'Banner', 1, 'A sign lets you type a few lines of text, perfect for labels and directions.', 194, true, 'choice', null::jsonb, null::text[]),
  ('painting-shows-random-picture', 'Which wall decoration shows a random picture when you hang it?', 'Sign', 'Banner', 'Painting', 'Lantern', 2, 'A painting picks a random picture that fits the free wall space around it.', 195, true, 'choice', null::jsonb, null::text[]),
  ('item-frame-displays-item', 'What can you hang on a wall to show off one item?', 'Banner', 'Bookshelf', 'Painting', 'Item Frame', 3, 'An item frame displays any item you put in it, and you can click it to rotate the item.', 196, true, 'choice', null::jsonb, null::text[]),
  ('carpet-crafted-from-wool', 'Which thin floor covering is crafted from wool?', 'Pressure Plate', 'Trapdoor', 'Slab', 'Carpet', 3, 'Carpet is a thin, soft layer made from wool, great for colorful floors.', 197, true, 'choice', null::jsonb, null::text[]),
  ('flower-pot-holds-one-plant', 'Which small decoration holds one flower, sapling or cactus?', 'Cauldron', 'Flower Pot', 'Barrel', 'Composter', 1, 'A flower pot shows off one small plant, like a flower, a sapling, a mushroom or a cactus.', 198, true, 'choice', null::jsonb, null::text[]),
  ('glass-pane-thin-window', 'Which thin window block is much slimmer than a full glass block?', 'Fence', 'Trapdoor', 'Tinted Glass', 'Glass Pane', 3, 'Glass panes are thin see-through windows that connect to the blocks beside them.', 199, true, 'choice', null::jsonb, null::text[]),
  ('banner-takes-patterns', 'Which tall cloth decoration can you cover in patterns and colors?', 'Carpet', 'Banner', 'Painting', 'Sign', 1, 'Banners are made from wool, and you can add patterns to them with dyes in a loom.', 200, true, 'choice', null::jsonb, null::text[]),
  ('armor-stand-shows-armor', 'Where can you put a whole armor set to show it off?', 'Armor Stand', 'Item Frame', 'Chest', 'Barrel', 0, 'An armor stand holds armor, mob heads and even elytra, like a mannequin.', 201, true, 'choice', null::jsonb, null::text[]),
  ('bell-rings-in-village', 'Which village block rings when you hit it?', 'Bell', 'Lectern', 'Composter', 'Barrel', 0, 'Ringing a bell sends nearby villagers running to their beds, which is handy during a raid.', 202, true, 'choice', null::jsonb, null::text[]),
  ('two-chests-make-large-chest', 'How many chests placed side by side make one large chest?', '8', '3', '2', '4', 2, 'Two chests next to each other join into one large chest with double the space.', 203, true, 'choice', null::jsonb, null::text[]),
  ('emerald-ore-green-gems', 'Which ore drops the green gems villagers use for trading?', 'Lapis Lazuli Ore', 'Copper Ore', 'Diamond Ore', 'Emerald Ore', 3, 'Emerald ore drops emeralds, the green gems that villagers accept as money.', 204, true, 'choice', null::jsonb, null::text[]),
  ('poppy-makes-red-dye', 'Which of these flowers gives you red dye?', 'Dandelion', 'Poppy', 'Cornflower', 'Allium', 1, 'A poppy crafts into red dye; dandelions give yellow and cornflowers give blue.', 205, true, 'choice', null::jsonb, null::text[]),
  ('sapling-breaks-instantly', 'Which of these blocks breaks instantly, even with your bare hand?', 'Cobblestone', 'Sapling', 'Dirt', 'Oak Log', 1, 'Saplings break the moment you hit them, while logs, stone and dirt take a few hits.', 206, true, 'choice', null::jsonb, null::text[]),
  ('water-knocks-off-torch', 'What happens to a torch when flowing water reaches it?', 'It explodes', 'It pops off as an item', 'It turns into a soul torch', 'It keeps burning underwater', 1, 'Water washes torches away, so they pop off and drop as items you can pick up.', 207, true, 'choice', null::jsonb, null::text[]),
  ('inventory-crafting-grid-two-by-two', 'How big is the crafting grid in your own inventory, without a crafting table?', '2×2', '4×4', '3×3', '1×1', 0, 'Your inventory has a small 2×2 crafting grid; a crafting table gives you the bigger 3×3 grid.', 208, true, 'choice', null::jsonb, null::text[]),
  ('two-planks-craft-four-sticks', 'Stack two planks on top of each other. How many sticks do you get?', '2', '4', '8', '3', 1, 'Two planks placed one above the other craft 4 sticks, enough handles for two pickaxes.', 209, true, 'choice', null::jsonb, null::text[]),
  ('one-coal-crafts-four-torches', 'One coal on top of one stick crafts how many torches?', '4', '1', '2', '6', 0, 'A piece of coal or charcoal over a stick makes 4 torches at once.', 210, true, 'choice', null::jsonb, null::text[]),
  ('three-planks-craft-bowls', 'Three planks placed in a V shape make which item?', 'Bowl', 'Chest', 'Ladder', 'Boat', 0, 'Three planks in a V shape craft 4 bowls, used for stews and soups.', 211, true, 'choice', null::jsonb, null::text[]),
  ('seven-sticks-craft-ladders', 'Which climbable block is crafted from nothing but sticks?', 'Scaffolding', 'Fence', 'Ladder', 'Trapdoor', 2, 'Seven sticks in an H shape craft ladders that you can climb up walls.', 212, true, 'choice', null::jsonb, null::text[]),
  ('campfire-from-sticks-logs-coal', 'Sticks, logs and a piece of coal craft which block?', 'Campfire', 'Torch', 'Smoker', 'Furnace', 0, 'A campfire is crafted from sticks, logs and coal or charcoal, and you can cook food on it.', 213, true, 'choice', null::jsonb, null::text[]),
  ('glass-crafts-glass-bottles', 'Which potion container is crafted from three glass blocks?', 'Glass Pane', 'Glass Bottle', 'Bowl', 'Bucket', 1, 'Three glass blocks in a V shape make 3 glass bottles, which you fill with water to brew potions.', 214, true, 'choice', null::jsonb, null::text[]),
  ('wool-and-stick-craft-banner', 'Six wool and one stick craft which item?', 'Bed', 'Banner', 'Painting', 'Carpet', 1, 'Six wool over a stick craft a banner, and the wool color becomes the banner''s base color.', 215, true, 'choice', null::jsonb, null::text[]),
  ('furnace-fuel-bottom-slot', 'In a furnace window, which slot is for the fuel?', 'Output slot', 'Bottom slot', 'Any empty slot', 'Top slot', 1, 'The item to smelt goes in the top slot, fuel goes in the bottom slot, and the result appears on the right.', 216, true, 'choice', null::jsonb, null::text[]),
  ('shovel-digs-dirt-sand-gravel', 'Which tool digs dirt, sand and gravel the fastest?', 'Pickaxe', 'Sword', 'Axe', 'Shovel', 3, 'Shovels are made for soft blocks like dirt, sand, gravel and snow.', 217, true, 'choice', null::jsonb, null::text[]),
  ('wooden-pickaxe-burns-as-fuel', 'Which of these pickaxes can burn as furnace fuel?', 'Wooden Pickaxe', 'Iron Pickaxe', 'Stone Pickaxe', 'Golden Pickaxe', 0, 'Wooden tools burn in a furnace, and each one smelts one item before it is used up.', 218, true, 'choice', null::jsonb, null::text[]),
  ('shears-collect-leaves', 'Which tool lets you pick up leaves as blocks?', 'Shears', 'Sword', 'Hoe', 'Axe', 0, 'Shears collect leaves, vines and cobwebs as items instead of breaking them into nothing.', 219, true, 'choice', null::jsonb, null::text[]),
  ('raw-gold-smelts-gold-ingot', 'Smelting raw gold gives you which item?', 'Iron Ingot', 'Gold Ingot', 'Copper Ingot', 'Gold Nugget', 1, 'Raw gold from gold ore smelts into a gold ingot, used for clocks and golden apples.', 220, true, 'choice', null::jsonb, null::text[]),
  ('netherite-pickaxe-lasts-longest', 'Which pickaxe lasts the longest before it breaks?', 'Golden Pickaxe', 'Netherite Pickaxe', 'Iron Pickaxe', 'Diamond Pickaxe', 1, 'Netherite tools have the most durability of all, a bit more than diamond, while gold breaks the fastest.', 221, true, 'choice', null::jsonb, null::text[]),
  ('lava-bucket-works-as-fuel', 'Which bucket can you use as furnace fuel?', 'Bucket of Cod', 'Water Bucket', 'Lava Bucket', 'Milk Bucket', 2, 'A lava bucket is a great furnace fuel, and you get the empty bucket back after it burns.', 222, true, 'choice', null::jsonb, null::text[]),
  ('cobblestone-is-not-fuel', 'Which of these items will NOT burn as furnace fuel?', 'Cobblestone', 'Planks', 'Coal', 'Stick', 0, 'Stone blocks like cobblestone never burn, while coal, planks and sticks all work as fuel.', 223, true, 'choice', null::jsonb, null::text[]),
  ('lit-furnace-gives-off-light', 'Which block lights up the room while it is smelting something?', 'Furnace', 'Chest', 'Barrel', 'Crafting Table', 0, 'A working furnace glows with fire inside and gives off light, then goes dark when it stops.', 224, true, 'choice', null::jsonb, null::text[]),
  ('iron-ore-drops-raw-iron', 'Mine iron ore with a stone pickaxe. What drops?', 'Iron Ingot', 'Iron Nugget', 'Cobblestone', 'Raw Iron', 3, 'Iron ore drops raw iron, which you smelt in a furnace to get iron ingots.', 225, true, 'choice', null::jsonb, null::text[]),
  ('cobblestone-crafts-stone-pickaxe', 'Three cobblestone and two sticks make which pickaxe?', 'Iron Pickaxe', 'Diamond Pickaxe', 'Stone Pickaxe', 'Wooden Pickaxe', 2, 'Cobblestone tools are the stone tier, the first upgrade after wood.', 226, true, 'choice', null::jsonb, null::text[]),
  ('pickaxe-recipe-two-sticks', 'How many sticks go into any pickaxe recipe?', '2', '4', '1', '3', 0, 'Every craftable pickaxe uses 2 sticks for the handle and 3 pieces of its material on top.', 227, true, 'choice', null::jsonb, null::text[]),
  ('iron-sword-two-ingots', 'How many iron ingots does an iron sword need?', '4', '3', '1', '2', 3, 'A sword is two pieces of material stacked on one stick, so an iron sword costs 2 ingots.', 228, true, 'choice', null::jsonb, null::text[]),
  ('diamond-between-iron-and-netherite', 'Which tool material is stronger than iron but weaker than netherite?', 'Diamond', 'Wood', 'Stone', 'Gold', 0, 'The usual upgrade path goes wood, stone, iron, diamond, then netherite.', 229, true, 'choice', null::jsonb, null::text[]),
  ('nine-coal-craft-coal-block', 'Nine pieces of coal in the crafting grid make which block?', 'Obsidian', 'Block of Coal', 'Blackstone', 'Coal Ore', 1, 'Nine coal craft a block of coal, a compact way to store fuel.', 230, true, 'choice', null::jsonb, null::text[]),
  ('wooden-pickaxe-mines-coal-ore', 'Which of these ores can a wooden pickaxe mine and still get a drop?', 'Iron Ore', 'Diamond Ore', 'Gold Ore', 'Coal Ore', 3, 'A wooden pickaxe can mine coal ore, but iron ore needs stone or better, and gold and diamond need iron.', 231, true, 'choice', null::jsonb, null::text[]),
  ('emeralds-make-no-pickaxe', 'Which of these can NOT be turned into a pickaxe?', 'Cobblestone', 'Emerald', 'Diamond', 'Gold Ingot', 1, 'Pickaxes are crafted from materials like wood, stone, iron, gold and diamond, while emeralds are for trading.', 232, true, 'choice', null::jsonb, null::text[]),
  ('crafting-table-before-any-pickaxe', 'Which block must you place before you can craft any pickaxe?', 'Crafting Table', 'Anvil', 'Furnace', 'Smithing Table', 0, 'Pickaxes need the 3×3 grid, so you have to place a crafting table first.', 233, true, 'choice', null::jsonb, null::text[]),
  ('cactus-planted-on-sand', 'On which block can you plant a cactus?', 'Sand', 'Dirt', 'Farmland', 'Grass Block', 0, 'A cactus can only be placed on sand, red sand or on top of another cactus.', 234, true, 'choice', null::jsonb, null::text[]),
  ('melon-seeds-grow-melons', 'What do you plant to grow a melon?', 'Pumpkin Seeds', 'Melon Seeds', 'Beetroot Seeds', 'Wheat Seeds', 1, 'Melon seeds grow into a stem, and the stem grows melons on a free block next to it.', 235, true, 'choice', null::jsonb, null::text[]),
  ('pumpkin-grows-beside-stem', 'Which crop grows from a stem and pops up on the block next to it?', 'Potato', 'Wheat', 'Pumpkin', 'Carrot', 2, 'A pumpkin stem grows a pumpkin on a free dirt, grass or farmland block beside it.', 236, true, 'choice', null::jsonb, null::text[]),
  ('wheat-needs-farmland', 'Which of these plants needs farmland to grow?', 'Sugar Cane', 'Bamboo', 'Wheat', 'Cactus', 2, 'Wheat is planted on farmland, while sugar cane, cactus and bamboo grow on ordinary blocks.', 237, true, 'choice', null::jsonb, null::text[]),
  ('jumping-on-farmland-tramples', 'What can happen to farmland if you jump on it?', 'It turns into dirt', 'It turns into sand', 'It turns into mud', 'It turns into a path', 0, 'Jumping or falling on farmland can trample it back into dirt, and any crop on it pops off.', 238, true, 'choice', null::jsonb, null::text[]),
  ('bone-meal-grass-flowers', 'What appears when you use bone meal on a grass block?', 'Mushrooms', 'Sugar cane', 'Saplings', 'Grass and flowers', 3, 'Bone meal on a grass block makes grass and flowers sprout all around it.', 239, true, 'choice', null::jsonb, null::text[]),
  ('torches-keep-crops-growing', 'What can you place by your farm so crops keep growing at night?', 'Lever', 'Glass', 'Torch', 'Ladder', 2, 'Crops need light to grow, so torches next to a farm keep them growing even in the dark.', 240, true, 'choice', null::jsonb, null::text[]),
  ('sapling-grows-tree', 'To grow a new tree, what do you plant?', 'Stick', 'Wheat Seeds', 'Sapling', 'Apple', 2, 'Plant a sapling on dirt or grass, give it light and space, and it grows into a tree.', 241, true, 'choice', null::jsonb, null::text[]),
  ('beetroot-drops-own-seeds', 'Which red crop drops its own seeds when you harvest it?', 'Sweet Berries', 'Beetroot', 'Potato', 'Carrot', 1, 'Ripe beetroots drop beetroots plus beetroot seeds, so you can plant them again.', 242, true, 'choice', null::jsonb, null::text[]),
  ('two-adults-make-a-baby', 'How many adult animals do you need to breed a baby?', '3', '2', '1', '4', 1, 'Feed two adult animals of the same kind their favorite food and a baby appears.', 243, true, 'choice', null::jsonb, null::text[]),
  ('goat-gives-milk', 'Besides cows, which animal can you milk with a bucket?', 'Sheep', 'Chicken', 'Goat', 'Pig', 2, 'Goats can be milked with a bucket just like cows.', 244, true, 'choice', null::jsonb, null::text[]),
  ('sheep-drops-mutton', 'Which animal drops raw mutton?', 'Rabbit', 'Sheep', 'Cow', 'Pig', 1, 'Sheep drop raw mutton and wool; cook the mutton in a furnace for a better meal.', 245, true, 'choice', null::jsonb, null::text[]),
  ('sugar-cane-crafts-sugar', 'Which plant do you craft into sugar?', 'Cactus', 'Bamboo', 'Beetroot', 'Sugar Cane', 3, 'One sugar cane crafts into sugar, which you need for cakes and pumpkin pie.', 246, true, 'choice', null::jsonb, null::text[]),
  ('bowl-on-mooshroom-stew', 'Using a bowl on a mooshroom gives you what?', 'Beetroot Soup', 'Mushroom Stew', 'Rabbit Stew', 'Milk Bucket', 1, 'Milking a mooshroom with a bowl gives mushroom stew, while a bucket gives milk.', 247, true, 'choice', null::jsonb, null::text[]),
  ('pig-drops-raw-porkchop', 'Which farm animal drops raw porkchop?', 'Chicken', 'Sheep', 'Cow', 'Pig', 3, 'Pigs drop raw porkchop, which turns into a tasty cooked porkchop in a furnace.', 248, true, 'choice', null::jsonb, null::text[]),
  ('carrot-eaten-straight-from-farm', 'Which of these can you eat right after harvesting it?', 'Cocoa Beans', 'Pumpkin', 'Carrot', 'Wheat', 2, 'Carrots can be eaten straight from the farm, while wheat, cocoa beans and pumpkins need crafting first.', 249, true, 'choice', null::jsonb, null::text[]),
  ('cow-drops-raw-beef', 'Besides leather, what food can a cow drop?', 'Raw Chicken', 'Raw Beef', 'Raw Mutton', 'Raw Porkchop', 1, 'Cows drop raw beef and leather, and cooking raw beef gives you steak.', 250, true, 'choice', null::jsonb, null::text[]),
  ('raw-cod-cooks-to-cooked-cod', 'A raw cod cooked in a furnace becomes what?', 'Cooked Cod', 'Dried Kelp', 'Tropical Fish', 'Cooked Salmon', 0, 'Cooking raw cod in a furnace, smoker or campfire gives cooked cod, which fills more hunger.', 251, true, 'choice', null::jsonb, null::text[]),
  ('fishing-rod-catches-fish', 'Which tool do you use to catch fish from the water?', 'Fishing Rod', 'Lead', 'Bow', 'Shears', 0, 'Cast a fishing rod into water and reel it in when the bobber dips to catch a fish.', 252, true, 'choice', null::jsonb, null::text[]),
  ('cake-placed-and-shared', 'Which food do you place as a block and eat slice by slice?', 'Bread', 'Cake', 'Cookie', 'Pumpkin Pie', 1, 'A cake is placed like a block, so everyone nearby can eat a slice from it.', 253, true, 'choice', null::jsonb, null::text[]),
  ('breeding-shows-hearts', 'What appears above two animals when they are ready to breed?', 'Green sparkles', 'Smoke clouds', 'Music notes', 'Red hearts', 3, 'Animals in love mode show red hearts, then come together and make a baby.', 254, true, 'choice', null::jsonb, null::text[]),
  ('chickens-breed-pumpkin-seeds', 'Besides wheat seeds, which seeds can you feed chickens to breed them?', 'Nether Wart', 'Sweet Berries', 'Pumpkin Seeds', 'Cocoa Beans', 2, 'Chickens love all kinds of seeds, including pumpkin seeds.', 255, true, 'choice', null::jsonb, null::text[]),
  ('two-cows-one-calf', 'When two cows breed, how many calves are born?', '3', '1', '4', '2', 1, 'Two cows in love make just one calf each time you breed them.', 256, true, 'choice', null::jsonb, null::text[]),
  ('harvested-wheat-drops-seeds', 'Besides wheat, what can breaking a fully grown wheat crop also give you?', 'Wheat Seeds', 'Bone Meal', 'Bread', 'Hay Bale', 0, 'Ripe wheat drops wheat and can drop seeds too, so you can replant your field.', 257, true, 'choice', null::jsonb, null::text[]),
  ('rabbit-drops-raw-rabbit', 'Which raw meat can you get from a hopping bunny?', 'Raw Beef', 'Raw Rabbit', 'Raw Chicken', 'Raw Mutton', 1, 'Rabbits can drop raw rabbit, which you can cook and even use in rabbit stew.', 258, true, 'choice', null::jsonb, null::text[]),
  ('parrot-never-eats-cookies', 'Which food must you never give a parrot?', 'Beetroot Seeds', 'Wheat Seeds', 'Cookie', 'Melon Seeds', 2, 'Parrots love seeds, but a cookie poisons them, so never feed one to your parrot.', 259, true, 'choice', null::jsonb, null::text[]),
  ('bucket-on-mooshroom-milk', 'Using an empty bucket on a mooshroom gives you what?', 'Water Bucket', 'Mushroom Stew', 'Honey Bottle', 'Milk Bucket', 3, 'A mooshroom can be milked just like a cow, so a bucket gives you milk.', 260, true, 'choice', null::jsonb, null::text[]),
  ('rabbit-drops-lucky-foot', 'Which small hopping animal can drop a lucky foot?', 'Chicken', 'Cat', 'Rabbit', 'Fox', 2, 'Rabbits drop rabbit hide and sometimes a rabbit''s foot, which is used to brew a Potion of Leaping.', 261, true, 'choice', null::jsonb, null::text[]),
  ('glow-squid-dark-water', 'Which sea creature glows softly in dark underground water?', 'Squid', 'Axolotl', 'Dolphin', 'Glow Squid', 3, 'Glow squids live in dark underground water and drop glow ink sacs that make sign text shine.', 262, true, 'choice', null::jsonb, null::text[]),
  ('donkey-carries-chest', 'Which rideable animal can carry a chest full of your items?', 'Cow', 'Pig', 'Donkey', 'Horse', 2, 'Put a chest on a tamed donkey and it becomes a walking storage box; horses can''t carry chests.', 263, true, 'choice', null::jsonb, null::text[]),
  ('frog-grows-from-tadpole', 'Which mob starts its life as a tiny tadpole?', 'Squid', 'Turtle', 'Axolotl', 'Frog', 3, 'Frogs lay frogspawn in water, tadpoles hatch from it and later grow into frogs.', 264, true, 'choice', null::jsonb, null::text[]),
  ('cat-tamed-with-raw-fish', 'Which pet can you tame by feeding it raw cod or salmon?', 'Wolf', 'Cat', 'Parrot', 'Horse', 1, 'Stray cats in villages can be tamed with raw cod or raw salmon; each fish has a chance to work.', 265, true, 'choice', null::jsonb, null::text[]),
  ('enderman-angry-when-looked-at', 'Which tall mob gets angry if you look right at its face?', 'Spider', 'Zombified Piglin', 'Wolf', 'Enderman', 3, 'Endermen are neutral until you look at their head; then they scream, teleport and attack.', 266, true, 'choice', null::jsonb, null::text[]),
  ('parrot-rides-on-shoulder', 'Which tamed bird can sit on your shoulder?', 'Parrot', 'Chicken', 'Allay', 'Bat', 0, 'A tamed parrot hops onto your shoulder when you walk into it and rides there as you explore.', 267, true, 'choice', null::jsonb, null::text[]),
  ('skeleton-drops-bones-arrows', 'Defeating which mob gives you bones and arrows?', 'Skeleton', 'Creeper', 'Spider', 'Zombie', 0, 'Skeletons drop bones and arrows; bones make bone meal and can tame wolves.', 268, true, 'choice', null::jsonb, null::text[]),
  ('magma-cube-lava-slime', 'Which bouncing Nether mob looks like a slime made of lava?', 'Strider', 'Blaze', 'Ghast', 'Magma Cube', 3, 'Magma cubes hop around the Nether, split into smaller cubes when defeated and drop magma cream.', 269, true, 'choice', null::jsonb, null::text[]),
  ('slime-drops-for-sticky-piston', 'Which bouncy mob drops the balls you need for a sticky piston?', 'Slime', 'Magma Cube', 'Creeper', 'Witch', 0, 'Small slimes drop slimeballs, and a slimeball plus a piston crafts a sticky piston.', 270, true, 'choice', null::jsonb, null::text[]),
  ('blaze-fiery-floating-rods', 'Which fiery Nether mob floats inside spinning rods and shoots small fireballs?', 'Ghast', 'Strider', 'Blaze', 'Magma Cube', 2, 'Blazes live in Nether fortresses and shoot volleys of three small fireballs at players.', 271, true, 'choice', null::jsonb, null::text[]),
  ('hoglin-attacks-on-sight', 'Which big tusked beast charges at players in crimson forests?', 'Hoglin', 'Ravager', 'Piglin', 'Strider', 0, 'Hoglins roam crimson forests in herds and attack any player who comes close.', 272, true, 'choice', null::jsonb, null::text[]),
  ('drowned-underwater-zombie', 'Which zombie-like mob lives underwater in oceans and rivers?', 'Drowned', 'Husk', 'Guardian', 'Stray', 0, 'Drowned are underwater zombies; some carry tridents or fishing rods and attack swimmers.', 273, true, 'choice', null::jsonb, null::text[]),
  ('witch-purple-robe-hat', 'Which hostile mob wears a purple robe and a pointy hat?', 'Vindicator', 'Evoker', 'Witch', 'Pillager', 2, 'Witches wear purple robes and pointy hats, throw harmful splash potions and drink helpful ones.', 274, true, 'choice', null::jsonb, null::text[]),
  ('helmet-goes-on-head', 'Which armor piece goes on your head?', 'Helmet', 'Boots', 'Chestplate', 'Leggings', 0, 'A full armor set has a helmet for your head, plus a chestplate, leggings and boots.', 275, true, 'choice', null::jsonb, null::text[]),
  ('snow-golem-throws-snowballs', 'Which friendly mob made of snow throws snowballs at monsters?', 'Snow Golem', 'Iron Golem', 'Allay', 'Stray', 0, 'Build a snow golem from two snow blocks and a carved pumpkin, and it will pelt hostile mobs with snowballs.', 276, true, 'choice', null::jsonb, null::text[]),
  ('crossbow-also-shoots-arrows', 'Besides a bow, which weapon shoots arrows?', 'Trident', 'Fishing Rod', 'Shield', 'Crossbow', 3, 'A crossbow is loaded with an arrow first and then fired, and it can also launch fireworks.', 277, true, 'choice', null::jsonb, null::text[]),
  ('stone-sword-from-cobblestone', 'Which sword do you craft with cobblestone and a stick?', 'Wooden Sword', 'Stone Sword', 'Iron Sword', 'Golden Sword', 1, 'Two cobblestone and a stick make a stone sword, a cheap upgrade from a wooden one.', 278, true, 'choice', null::jsonb, null::text[]),
  ('bow-needs-arrows', 'What must be in your inventory before a bow can shoot?', 'Snowball', 'Arrow', 'Egg', 'Flint', 1, 'Bows fire arrows from your inventory, and the longer you pull the string, the farther they fly.', 279, true, 'choice', null::jsonb, null::text[]),
  ('armor-set-four-pieces', 'How many pieces make a full set of armor?', '6', '3', '5', '4', 3, 'Armor has four slots for head, chest, legs and feet, and wearing all four protects you best.', 280, true, 'choice', null::jsonb, null::text[]),
  ('leather-armor-can-be-dyed', 'Which armor can you dye in any color you like?', 'Leather Armor', 'Iron Armor', 'Diamond Armor', 'Golden Armor', 0, 'Only leather armor can be dyed, so you can make your outfit any color.', 281, true, 'choice', null::jsonb, null::text[]),
  ('diamond-armor-gem', 'Which gem can you craft into shiny blue armor?', 'Nether Quartz', 'Diamond', 'Amethyst Shard', 'Emerald', 1, 'Diamonds craft strong light-blue armor, which you can later upgrade to netherite.', 282, true, 'choice', null::jsonb, null::text[]),
  ('boots-need-fewest-ingots', 'Which armor piece takes the fewest ingots to craft?', 'Boots', 'Helmet', 'Chestplate', 'Leggings', 0, 'Boots need only 4 ingots, while a helmet needs 5, leggings 7 and a chestplate 8.', 283, true, 'choice', null::jsonb, null::text[]),
  ('cave-spider-poison-bite', 'Which small spider can poison you with its bite?', 'Silverfish', 'Spider', 'Cave Spider', 'Endermite', 2, 'Cave spiders are smaller than normal spiders and their bite can poison you.', 284, true, 'choice', null::jsonb, null::text[]),
  ('tropical-fish-warm-oceans', 'Which colorful fish lives around coral reefs in warm oceans?', 'Tropical Fish', 'Salmon', 'Cod', 'Squid', 0, 'Tropical fish come in many colors and patterns and swim near coral in warm water.', 285, true, 'choice', null::jsonb, null::text[]),
  ('dye-changes-sheep-color', 'Using dye on which animal changes the color of its coat?', 'Llama', 'Goat', 'Cow', 'Sheep', 3, 'Use dye on a sheep and its wool changes color, so shearing gives colored wool.', 286, true, 'choice', null::jsonb, null::text[]),
  ('pufferfish-puffs-up', 'Which fish puffs up and stings you when you swim too close?', 'Salmon', 'Tropical Fish', 'Cod', 'Pufferfish', 3, 'A pufferfish inflates when you get near, and touching it poisons you.', 287, true, 'choice', null::jsonb, null::text[]),
  ('glowstone-clumps-nether-ceiling', 'Which glowing block hangs in clumps from the Nether''s ceiling?', 'Jack o''Lantern', 'Sea Lantern', 'Redstone Lamp', 'Glowstone', 3, 'Glowstone grows in bright clumps under the Nether ceiling and breaks into glowstone dust.', 288, true, 'choice', null::jsonb, null::text[]),
  ('water-evaporates-in-nether', 'What happens when you pour a water bucket in the Nether?', 'It freezes into ice', 'It evaporates', 'It flows like normal', 'It turns into lava', 1, 'The Nether is too hot for water: poured water vanishes in a puff of steam.', 289, true, 'choice', null::jsonb, null::text[]),
  ('fortress-built-of-nether-bricks', 'What are Nether fortresses mostly built from?', 'Blackstone', 'Nether Bricks', 'Stone Bricks', 'Red Nether Bricks', 1, 'Fortresses are huge dark bridges and halls of nether bricks standing over lava seas.', 290, true, 'choice', null::jsonb, null::text[]),
  ('magma-cube-splits-apart', 'Which hopping Nether mob breaks into smaller cubes when you beat it?', 'Hoglin', 'Blaze', 'Ghast', 'Magma Cube', 3, 'A big magma cube splits into smaller ones, just like a slime does in the Overworld.', 291, true, 'choice', null::jsonb, null::text[]),
  ('crimson-forest-red-fungi', 'Which Nether biome is full of red fungi and red mushroom-like trees?', 'Crimson Forest', 'Nether Wastes', 'Warped Forest', 'Basalt Deltas', 0, 'The crimson forest has huge red fungi on red ground, and hoglins and piglins live there.', 292, true, 'choice', null::jsonb, null::text[]),
  ('nether-gold-ore-drops-nuggets', 'What drops when you mine Nether gold ore with a pickaxe?', 'Gold Nugget', 'Block of Gold', 'Gold Ingot', 'Raw Gold', 0, 'Nether gold ore drops 2 to 6 gold nuggets instead of raw gold.', 293, true, 'choice', null::jsonb, null::text[]),
  ('nether-portal-glows-purple', 'What color is the swirling inside of a lit Nether portal?', 'Purple', 'Green', 'Black', 'Blue', 0, 'A lit Nether portal fills with a swirling purple glow and makes a whooshing sound.', 294, true, 'choice', null::jsonb, null::text[]),
  ('wither-skeleton-in-fortresses', 'Which tall black skeleton lives in Nether fortresses?', 'Stray', 'Bogged', 'Piglin Brute', 'Wither Skeleton', 3, 'Wither skeletons spawn in fortresses, carry stone swords and can give you the Wither effect.', 295, true, 'choice', null::jsonb, null::text[]),
  ('void-below-end-islands', 'What lies below the floating islands of the End?', 'Lava', 'The Void', 'Bedrock', 'Water', 1, 'Under the End islands there is only the void, so watch your step near the edges.', 296, true, 'choice', null::jsonb, null::text[]),
  ('end-pillars-made-of-obsidian', 'Which block are the tall pillars on the End''s main island made of?', 'End Stone', 'Purpur Block', 'Bedrock', 'Obsidian', 3, 'Tall obsidian pillars ring the main island, and end crystals sit on top of them.', 297, true, 'choice', null::jsonb, null::text[]),
  ('elytra-let-you-glide', 'Which wing-like item lets you glide through the air?', 'Saddle', 'Feather', 'Phantom Membrane', 'Elytra', 3, 'Elytra are rare wings found on End ships that let you glide through the air.', 298, true, 'choice', null::jsonb, null::text[]),
  ('exit-portal-takes-you-home', 'After you beat the Ender Dragon, how do you get back home?', 'Throw an Eye of Ender', 'Sleep in a bed', 'Ring a bell', 'Jump in the exit portal', 3, 'Beating the dragon opens the exit portal in the middle of the island, which sends you to your spawn point.', 299, true, 'choice', null::jsonb, null::text[]),
  ('enderman-carries-blocks', 'Which tall mob can teleport and carry a block in its arms?', 'Creeper', 'Skeleton', 'Witch', 'Enderman', 3, 'Endermen teleport around and sometimes pick up blocks like grass or sand and carry them off.', 300, true, 'choice', null::jsonb, null::text[]),
  ('chorus-plants-on-outer-islands', 'Which purple plant grows on the End''s outer islands?', 'Kelp', 'Weeping Vines', 'Cactus', 'Chorus Plant', 3, 'Chorus plants grow on end stone in the outer End and drop chorus fruit.', 301, true, 'choice', null::jsonb, null::text[]),
  ('ender-dragon-drops-experience', 'What does the Ender Dragon drop loads of when you defeat it?', 'Ender Pearls', 'Diamonds', 'Experience', 'Gold Ingots', 2, 'The first dragon you beat drops 12,000 experience points, enough for many levels at once.', 302, true, 'choice', null::jsonb, null::text[]),
  ('elytra-worn-in-chest-slot', 'In which armor slot do you wear elytra?', 'Feet', 'Head', 'Chest', 'Legs', 2, 'Elytra go in the chest slot, so you can wear wings or a chestplate, but not both.', 303, true, 'choice', null::jsonb, null::text[]),
  ('end-cities-on-outer-islands', 'Where in the End do End cities appear?', 'On the dragon''s island', 'Under the Nether roof', 'On the outer islands', 'Inside strongholds', 2, 'End cities are found on the outer islands, far from the dragon, often with shulkers inside.', 304, true, 'choice', null::jsonb, null::text[]),
  ('iron-door-needs-redstone', 'Which door won''t open by hand and needs redstone instead?', 'Iron Door', 'Jungle Door', 'Oak Door', 'Spruce Door', 0, 'Iron doors only open with a button, lever, pressure plate or another redstone signal.', 305, true, 'choice', null::jsonb, null::text[]),
  ('dispenser-shoots-arrows', 'Which block shoots arrows when it gets a redstone signal?', 'Hopper', 'Dispenser', 'Observer', 'Dropper', 1, 'A dispenser fires arrows, while a dropper just tosses them out as items.', 306, true, 'choice', null::jsonb, null::text[]),
  ('redstone-signal-lights-tnt', 'What happens when TNT gets a redstone signal?', 'It lights and explodes', 'It glows red', 'It turns into sand', 'Nothing happens', 0, 'A redstone signal lights TNT, and it explodes a few seconds later.', 307, true, 'choice', null::jsonb, null::text[]),
  ('nine-dust-make-redstone-block', 'How many pieces of redstone dust craft one block of redstone?', '4', '9', '6', '8', 1, 'Nine redstone dust make a block of redstone, a block that is always powered.', 308, true, 'choice', null::jsonb, null::text[]),
  ('powered-dust-glows-brighter', 'What does redstone dust do when it carries a signal?', 'It plays a sound', 'It turns blue', 'It glows brighter red', 'It turns invisible', 2, 'Powered redstone dust glows bright red, and unpowered dust looks dark red.', 309, true, 'choice', null::jsonb, null::text[]),
  ('lever-made-with-cobblestone', 'Which block do you put under a stick to craft a lever?', 'Stone', 'Glass', 'Cobblestone', 'Oak Planks', 2, 'A lever is just a stick placed on top of a piece of cobblestone.', 310, true, 'choice', null::jsonb, null::text[]),
  ('bell-rings-from-redstone', 'Which village block rings out when it gets a redstone signal?', 'Campfire', 'Lantern', 'Barrel', 'Bell', 3, 'A bell rings each time it gets powered, which makes a handy doorbell or alarm.', 311, true, 'choice', null::jsonb, null::text[]),
  ('warped-forest-teal-fungi', 'Which Nether forest has teal-blue trees and glowing teal fungi?', 'Crimson Forest', 'Nether Wastes', 'Warped Forest', 'Soul Sand Valley', 2, 'The warped forest glows with teal fungi and is one of the calmer places in the Nether.', 312, true, 'choice', null::jsonb, null::text[]),
  ('nether-lava-oceans', 'What fills the huge oceans of the Nether?', 'Lava', 'Ice', 'Soul Sand', 'Water', 0, 'The Nether has seas of lava instead of water, so cross them carefully.', 313, true, 'choice', null::jsonb, null::text[]),
  ('shulker-hides-in-shell', 'Which End mob hides inside a purple box-like shell?', 'Endermite', 'Shulker', 'Enderman', 'Phantom', 1, 'Shulkers hide in their purple shells in End cities and peek out to shoot at you.', 314, true, 'choice', null::jsonb, null::text[]),
  ('block-of-redstone-always-on', 'Which block always gives off a redstone signal without any switch?', 'Observer', 'Note Block', 'Block of Redstone', 'Redstone Lamp', 2, 'A block of redstone is always on, powering anything next to it.', 315, true, 'choice', null::jsonb, null::text[]),
  ('nether-bedrock-roof-and-floor', 'Which unbreakable block forms the very top and bottom of the Nether?', 'Obsidian', 'Basalt', 'Bedrock', 'Netherrack', 2, 'The Nether has thick bedrock layers above and below, so you can''t dig your way out.', 316, true, 'choice', null::jsonb, null::text[]),
  ('full-hunger-heals-health', 'What slowly refills on its own when your hunger bar is almost full?', 'Health', 'Experience', 'Armor', 'Tool durability', 0, 'With 9 or more drumsticks of hunger, your health slowly comes back by itself.', 317, true, 'choice', null::jsonb, null::text[]),
  ('empty-hunger-bar-starving', 'What happens when your hunger bar runs completely empty?', 'You start losing health', 'You run faster', 'You lose your XP', 'You drop your items', 0, 'An empty hunger bar means starving, so you slowly lose health until you eat something.', 318, true, 'choice', null::jsonb, null::text[]),
  ('apple-from-oak-leaves', 'Which fruit can drop when oak leaves are broken or decay?', 'Glow Berries', 'Melon Slice', 'Sweet Berries', 'Apple', 3, 'Oak and dark oak leaves have a small chance to drop an apple when they break or decay.', 319, true, 'choice', null::jsonb, null::text[]),
  ('ten-hearts-full-health', 'How many hearts does a full health bar have?', '8', '5', '10', '20', 2, 'You have 20 health points, shown as 10 hearts, and each heart is worth two points.', 320, true, 'choice', null::jsonb, null::text[]),
  ('sprinting-uses-hunger', 'Which of these makes your hunger bar drop faster?', 'Riding in a boat', 'Sneaking', 'Sprinting', 'Standing still', 2, 'Sprinting uses up food energy, so long runs empty your hunger bar quicker than walking.', 321, true, 'choice', null::jsonb, null::text[]),
  ('dried-kelp-from-kelp', 'Which quick snack do you get by smelting kelp?', 'Seagrass', 'Sea Pickle', 'Dried Kelp', 'Cooked Cod', 2, 'Kelp cooked in a furnace, smoker or campfire turns into dried kelp, a small but handy food.', 322, true, 'choice', null::jsonb, null::text[]),
  ('hunger-bar-drumstick-icons', 'What do the icons in your hunger bar look like?', 'Drumsticks', 'Bubbles', 'Hearts', 'Apples', 0, 'The hunger bar shows 10 drumsticks, and each full drumstick is worth 2 hunger points.', 323, true, 'choice', null::jsonb, null::text[]),
  ('glow-berries-edible', 'Which glowing berries from cave vines can you eat?', 'Glow Berries', 'Sweet Berries', 'Cocoa Beans', 'Chorus Fruit', 0, 'Glow berries grow on cave vines in lush caves; you can eat them or plant them.', 324, true, 'choice', null::jsonb, null::text[]),
  ('lantern-hangs-from-chain', 'Which light block can hang from a chain or a ceiling?', 'Lantern', 'Campfire', 'Candle', 'Torch', 0, 'Lanterns can sit on a block or hang below one, and they join neatly to chains.', 325, true, 'choice', null::jsonb, null::text[]),
  ('sun-rises-in-east', 'In which direction does the sun rise in Minecraft?', 'North', 'West', 'East', 'South', 2, 'The sun rises in the east and sets in the west, so it can help you find your way.', 326, true, 'choice', null::jsonb, null::text[]),
  ('sunset-comes-before-night', 'Which part of the day comes right before night?', 'Sunrise', 'Sunset', 'Morning', 'Noon', 1, 'Sunset darkens the sky and warns you that night and its monsters are coming soon.', 327, true, 'choice', null::jsonb, null::text[]),
  ('peaceful-no-hostile-mobs', 'On which difficulty do hostile mobs like zombies stop spawning?', 'Peaceful', 'Normal', 'Hard', 'Easy', 0, 'On Peaceful, zombies, skeletons and creepers don''t spawn, and your hunger bar never drops.', 328, true, 'choice', null::jsonb, null::text[]),
  ('punch-tree-for-first-wood', 'With no tools at all, how do you get your first wood?', 'Fish in a river', 'Dig into sand', 'Punch a tree', 'Mine some stone', 2, 'Logs can be broken with your bare hands, so punching a tree is the usual way to get your first wood.', 329, true, 'choice', null::jsonb, null::text[]),
  ('spider-calm-in-bright-light', 'Which mob stays calm in bright light but attacks in the dark?', 'Spider', 'Creeper', 'Zombie', 'Skeleton', 0, 'Spiders won''t attack in bright light unless you hit them, but in the dark they hunt you.', 330, true, 'choice', null::jsonb, null::text[]),
  ('villager-opens-wooden-doors', 'Which mob opens wooden doors to walk in and out of houses?', 'Skeleton', 'Creeper', 'Villager', 'Spider', 2, 'Villagers open wooden doors on their own, but they can''t open iron doors or trapdoors.', 331, true, 'choice', null::jsonb, null::text[]),
  ('moon-changes-each-night', 'What in the night sky looks a little different every night?', 'Moon', 'Sun', 'Stars', 'Clouds', 0, 'The moon has 8 phases and shows a new one each night, from full moon to new moon.', 332, true, 'choice', null::jsonb, null::text[]),
  ('tamed-wolf-fights-mobs', 'Which tamed animal will fight zombies and skeletons beside you?', 'Parrot', 'Cat', 'Wolf', 'Horse', 2, 'A tamed wolf attacks mobs that hurt you or that you hit, making it a loyal night guard.', 333, true, 'choice', null::jsonb, null::text[]),
  ('lava-sets-you-on-fire', 'Which glowing orange liquid sets you on fire if you step in?', 'Lava', 'Powder Snow', 'Honey Block', 'Water', 0, 'Lava burns anything that touches it, so always watch your step in caves and the Nether.', 334, true, 'choice', null::jsonb, null::text[]),
  ('cobweb-slows-movement', 'Which sticky block in mineshafts slows you to a crawl?', 'Cobweb', 'Carpet', 'Wool', 'Moss Block', 0, 'Cobwebs make you move very slowly; cut them with shears or a sword to get through fast.', 335, true, 'choice', null::jsonb, null::text[]),
  ('sprinting-fastest-on-foot', 'Which way of moving on foot is the fastest?', 'Crawling', 'Walking', 'Sprinting', 'Sneaking', 2, 'Sprinting is about 30% faster than walking, but it uses up your hunger.', 336, true, 'choice', null::jsonb, null::text[]),
  ('map-shows-explored-land', 'Which item shows a top-down picture of land you have explored?', 'Map', 'Book', 'Compass', 'Painting', 0, 'A map draws the land around you from above as you explore, so you can find your way home.', 337, true, 'choice', null::jsonb, null::text[]),
  ('lead-walks-animals', 'Which item lets you walk animals around like on a rope?', 'Saddle', 'Fishing Rod', 'String', 'Lead', 3, 'A lead ties to an animal so it follows you wherever you walk.', 338, true, 'choice', null::jsonb, null::text[]),
  ('gravel-falls-on-your-head', 'Which block can fall on your head and hurt you while you dig?', 'Stone', 'Dirt', 'Cobblestone', 'Gravel', 3, 'Gravel falls when nothing holds it up, and if it lands on your head you can suffocate inside it.', 339, true, 'choice', null::jsonb, null::text[]),
  ('jump-one-block-high', 'How many blocks high can you jump without any help?', '2', '3', '1', '4', 2, 'A normal jump lifts you just over 1 block, so taller walls need stairs or a ladder.', 340, true, 'choice', null::jsonb, null::text[]),
  ('items-burn-in-lava', 'What happens to most items that fall into lava?', 'They fly back to you', 'They turn into stone', 'They float on top', 'They burn up', 3, 'Lava burns up most dropped items, so never drop your loot next to it.', 341, true, 'choice', null::jsonb, null::text[]),
  ('rain-puts-out-fire', 'What puts out fires and burning mobs that are out in the open?', 'Nighttime', 'Rain', 'Sunset', 'Clear weather', 1, 'Rain puts out fire blocks and burning mobs that stand under the open sky.', 342, true, 'choice', null::jsonb, null::text[]),
  ('armor-bar-appears', 'Which bar appears on your screen when you put on armor?', 'Air Bar', 'Armor Bar', 'Hunger Bar', 'Experience Bar', 1, 'Putting on armor shows the armor bar, which tells you how well you are protected.', 343, true, 'choice', null::jsonb, null::text[]),
  ('items-drop-on-death', 'What happens to the items in your inventory when you die?', 'They stay in your inventory', 'They vanish forever', 'They drop where you died', 'They go to your bed', 2, 'When you die, your items drop where you died, so hurry back and pick them up.', 344, true, 'choice', null::jsonb, null::text[]),
  ('xp-orbs-fill-xp-bar', 'Glowing green orbs from mobs and ores fill which bar?', 'Health Bar', 'Experience Bar', 'Hunger Bar', 'Armor Bar', 1, 'Picking up those orbs fills your experience bar, which you later spend on enchanting.', 345, true, 'choice', null::jsonb, null::text[]),
  ('hostile-mobs-spawn-at-night', 'When do zombies and skeletons start showing up on the surface?', 'At sunrise', 'At noon', 'At night', 'In the morning', 2, 'Hostile mobs spawn in the dark, so the surface fills with them once night falls.', 346, true, 'choice', null::jsonb, null::text[]),
  ('farmer-sells-bread', 'Which villager sells you bread for emeralds?', 'Farmer', 'Fisherman', 'Shepherd', 'Butcher', 0, 'Farmers sell bread right from their first trading level.', 347, true, 'choice', null::jsonb, null::text[]),
  ('shepherd-sells-shears', 'Which villager trades shears and colorful wool?', 'Shepherd', 'Toolsmith', 'Leatherworker', 'Mason', 0, 'Shepherds sell shears as novices and wool of any color later on.', 348, true, 'choice', null::jsonb, null::text[]),
  ('fisherman-sells-cooked-cod', 'Who in the village sells cooked cod for emeralds?', 'Farmer', 'Cleric', 'Fisherman', 'Butcher', 2, 'Fishermen sell cooked cod and even buckets of cod.', 349, true, 'choice', null::jsonb, null::text[]),
  ('leatherworker-sells-leather-armor', 'Which villager sells leather tunics and pants?', 'Armorer', 'Leatherworker', 'Butcher', 'Shepherd', 1, 'Leatherworkers sell leather armor dyed in random colors.', 350, true, 'choice', null::jsonb, null::text[]),
  ('farmer-villager-harvests-crops', 'Which villager harvests and replants crops in village fields?', 'Nitwit', 'Farmer', 'Shepherd', 'Mason', 1, 'Farmer villagers pick fully grown wheat, carrots, potatoes and beetroots, then plant them again.', 351, true, 'choice', null::jsonb, null::text[]),
  ('lectern-holds-shared-book', 'Which job block can hold a book that players read together?', 'Barrel', 'Cartography Table', 'Cauldron', 'Lectern', 3, 'A lectern holds one book that several players can read at the same time.', 352, true, 'choice', null::jsonb, null::text[]),
  ('barrel-stores-like-chest', 'Which job block stores 27 stacks of items, just like a chest?', 'Barrel', 'Lectern', 'Loom', 'Composter', 0, 'A barrel has 27 slots, exactly as many as a single chest.', 353, true, 'choice', null::jsonb, null::text[]),
  ('cauldron-holds-liquids', 'Which job block can hold water, lava or powder snow?', 'Cauldron', 'Barrel', 'Composter', 'Smoker', 0, 'A cauldron can be filled with water, lava or powder snow.', 354, true, 'choice', null::jsonb, null::text[]),
  ('librarian-sells-bookshelves', 'Which villager can sell you a whole bookshelf?', 'Cleric', 'Mason', 'Librarian', 'Cartographer', 2, 'Novice librarians can trade a bookshelf for emeralds.', 355, true, 'choice', null::jsonb, null::text[]),
  ('armorer-sells-iron-armor', 'Which villager sells iron helmets and chestplates?', 'Armorer', 'Leatherworker', 'Toolsmith', 'Weaponsmith', 0, 'Novice armorers sell iron armor pieces for emeralds.', 356, true, 'choice', null::jsonb, null::text[]),
  ('fletcher-sells-bows', 'Which villager would you visit to buy a bow?', 'Fletcher', 'Armorer', 'Weaponsmith', 'Toolsmith', 0, 'Fletchers sell bows, crossbows, arrows and flint.', 357, true, 'choice', null::jsonb, null::text[]),
  ('wandering-trader-brings-llamas', 'Which animals follow a wandering trader on leads?', 'Camels', 'Llamas', 'Donkeys', 'Horses', 1, 'A wandering trader arrives with two trader llamas tied to it on leads.', 358, true, 'choice', null::jsonb, null::text[]),
  ('farmer-buys-wheat', 'Which crop can you sell to a farmer for emeralds?', 'Sugar Cane', 'Wheat', 'Cocoa Beans', 'Cactus', 1, 'Novice farmers buy wheat, potatoes, carrots or beetroots for emeralds.', 359, true, 'choice', null::jsonb, null::text[]),
  ('bread-makes-villagers-willing', 'Which food helps villagers get ready to have babies?', 'Bread', 'Apple', 'Melon Slice', 'Cookie', 0, 'Villagers become willing to breed after getting enough bread, carrots, potatoes or beetroots.', 360, true, 'choice', null::jsonb, null::text[]),
