  ('raid-win-gives-hero-effect', 'Which effect do you earn by defeating a raid?', 'Luck', 'Hero of the Village', 'Bad Omen', 'Regeneration', 1, 'Winning a raid gives you the Hero of the Village effect.', 362, true, 'choice', null::jsonb, null::text[]),
  ('master-is-top-villager-level', 'What is the highest level a trading villager can reach?', 'Apprentice', 'Expert', 'Journeyman', 'Master', 3, 'Villager levels go Novice, Apprentice, Journeyman, Expert and finally Master.', 363, true, 'choice', null::jsonb, null::text[]),
