  ('silk-touch-drops-block-itself', 'Which pickaxe enchantment makes ores drop as the ore block itself?', 'Efficiency', 'Mending', 'Silk Touch', 'Fortune', 2, 'Silk Touch lets you pick up the ore block whole instead of the raw item.', 375, true, 'choice', null::jsonb, null::text[]),
  ('infinity-saves-arrows', 'Which bow enchantment lets you shoot forever with just one arrow?', 'Punch', 'Unbreaking', 'Infinity', 'Power', 2, 'Infinity means your bow never uses up normal arrows, as long as you carry one.', 376, true, 'choice', null::jsonb, null::text[])
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
where pack.slug = 'minecraft-easy'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  kind = excluded.kind,
  media = excluded.media,
  option_icons = excluded.option_icons;

