  ('silk-touch-drops-block-itself', 'en', 'Which pickaxe enchantment makes ores drop as the ore block itself?', 'Efficiency', 'Mending', 'Silk Touch', 'Fortune', 'Silk Touch lets you pick up the ore block whole instead of the raw item.'),
  ('silk-touch-drops-block-itself', 'ru', 'Какое зачарование кирки заставляет руду выпадать целым блоком?', 'Эффективность', 'Починка', 'Шёлковое касание', 'Удача', 'Шёлковое касание позволяет забрать блок руды целиком, а не сырьё из него.'),
  ('infinity-saves-arrows', 'uk', 'Яке зачарування лука дає змогу стріляти без кінця лише з однією стрілою?', 'Удар', 'Незламність', 'Нескінченність', 'Сила', 'Нескінченність означає, що лук не витрачає звичайні стріли, якщо в тебе є хоч одна.'),
  ('infinity-saves-arrows', 'en', 'Which bow enchantment lets you shoot forever with just one arrow?', 'Punch', 'Unbreaking', 'Infinity', 'Power', 'Infinity means your bow never uses up normal arrows, as long as you carry one.'),
  ('infinity-saves-arrows', 'ru', 'Какое зачарование лука позволяет стрелять без конца всего одной стрелой?', 'Откидывание', 'Прочность', 'Бесконечность', 'Сила', 'Бесконечность значит, что лук не тратит обычные стрелы, если у тебя есть хоть одна.')
) as v(content_id, locale, prompt, option_a, option_b, option_c, option_d, explanation)
  on v.content_id = question.content_id
on conflict (question_id, locale) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  explanation = excluded.explanation;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, null, '8-12', 'medium', 'MineMind medium', 'minecraft-medium', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active, v.kind, v.media, v.option_icons
from public.question_packs pack
cross join (values
  ('desert-temple-desert', 'What is hidden under the pressure plate in a desert pyramid''s secret room?', 'TNT', 'Magma Block', 'Dispenser', 'Lava', 0, 'Stepping on the stone pressure plate sets off 9 TNT hidden under the floor.', 1, true, 'choice', null::jsonb, null::text[]),
  ('dripstone-caves-have-pointed-dripstone', 'Which biome is full of pointy stone spikes hanging from cave ceilings?', 'Deep Dark', 'Basalt Deltas', 'Dripstone Caves', 'Lush Caves', 2, 'Dripstone caves are packed with pointed dripstone, which hurts if you fall onto it.', 2, true, 'choice', null::jsonb, null::text[]),
  ('igloo-in-snowy-biomes', 'Which structure can hide a basement with a villager and a zombie villager?', 'Igloo', 'Witch Hut', 'Pillager Outpost', 'Desert Pyramid', 0, 'About half of igloos have a trapdoor to a secret basement where you can cure a zombie villager.', 3, true, 'choice', null::jsonb, null::text[]),
  ('jungle-temple-jungle', 'Which structure protects its loot with tripwires and arrow dispensers?', 'Jungle Temple', 'Woodland Mansion', 'Desert Pyramid', 'Pillager Outpost', 0, 'Jungle temples hide tripwires that fire arrows from dispensers, plus a lever puzzle.', 4, true, 'choice', null::jsonb, null::text[]),
  ('lush-caves-have-glow-berries', 'Axolotls naturally spawn in which biome?', 'Dripstone Caves', 'Swamp', 'Deep Dark', 'Lush Caves', 3, 'Axolotls spawn in the water pools of lush caves, among moss and glow berries.', 5, true, 'choice', null::jsonb, null::text[]),
  ('mangrove-swamp-has-mud', 'Which biome has ground covered in mud blocks?', 'Jungle', 'Mangrove Swamp', 'River', 'Swamp', 1, 'Mangrove swamps have muddy ground, trees with tall roots, and frogs.', 6, true, 'choice', null::jsonb, null::text[]),
  ('mineshaft-underground', 'Which mob comes out of the spawners in abandoned mineshafts?', 'Zombie', 'Cave Spider', 'Spider', 'Silverfish', 1, 'Mineshaft spawners sit in cobweb-filled tunnels and create poisonous cave spiders.', 7, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-guardians', 'Which underwater structure is home to guardians and elder guardians?', 'Ocean Ruins', 'Shipwreck', 'Ocean Monument', 'Stronghold', 2, 'Ocean monuments are prismarine buildings guarded by guardians and three elder guardians.', 8, true, 'choice', null::jsonb, null::text[]),
  ('pillager-outpost-has-pillagers', 'Which structure is a tall dark-oak watchtower guarded by crossbow mobs?', 'Jungle Temple', 'Ocean Monument', 'Woodland Mansion', 'Pillager Outpost', 3, 'Pillager outposts are towers full of pillagers, sometimes with a caged iron golem nearby.', 9, true, 'choice', null::jsonb, null::text[]),
  ('shipwrecks-near-ocean', 'Which structure can have a map chest, a supply chest and a treasure chest?', 'Ocean Ruins', 'Shipwreck', 'Ocean Monument', 'Igloo', 1, 'Shipwrecks have up to three chests, and the map often leads to buried treasure.', 10, true, 'choice', null::jsonb, null::text[]),
  ('strongholds-underground', 'Which item do you throw into the air to find a stronghold?', 'Ender Pearl', 'Snowball', 'Compass', 'Eye of Ender', 3, 'A thrown eye of ender flies toward the nearest stronghold, then drops or breaks.', 11, true, 'choice', null::jsonb, null::text[]),
  ('warm-ocean-has-coral', 'Colorful coral reefs grow in which biome?', 'Cold Ocean', 'Warm Ocean', 'Frozen Ocean', 'Deep Ocean', 1, 'Warm oceans have sandy floors with bright coral reefs and tropical fish.', 12, true, 'choice', null::jsonb, null::text[]),
  ('witch-hut-swamp', 'In which biome do witch huts generate?', 'Swamp', 'Dark Forest', 'Taiga', 'Jungle', 0, 'Witch huts stand on stilts in swamps, with a witch and a black cat inside.', 13, true, 'choice', null::jsonb, null::text[]),
  ('deep-dark-has-sculk', 'Sculk blocks are the clearest sign of which biome?', 'Warped Forest', 'Lush Caves', 'Deep Dark', 'Dripstone Caves', 2, 'The deep dark is covered in sculk, and noisy players there risk summoning a warden.', 14, true, 'choice', null::jsonb, null::text[]),
  ('nether-fortress-has-blazes', 'Where do players go to find blazes and their spawners?', 'Ruined Portal', 'Nether Fortress', 'End City', 'Bastion Remnant', 1, 'Blazes spawn only in nether fortresses, so that is where players farm blaze rods.', 15, true, 'choice', null::jsonb, null::text[]),
  ('concrete-powder-hardens-in-water', 'Which falling block hardens into a solid block when it touches water?', 'Concrete Powder', 'Sand', 'Gravel', 'Red Sand', 0, 'Concrete powder turns into concrete on contact with water, while sand and gravel stay the same.', 16, true, 'choice', null::jsonb, null::text[]),
  ('fence-stops-animal-escape', 'Animals can''t jump over which block, even though it looks one block tall?', 'Glass Pane', 'Carpet', 'Slab', 'Fence', 3, 'A fence is 1.5 blocks tall for collisions, too high for mobs to jump, so it''s ideal for pens.', 17, true, 'choice', null::jsonb, null::text[]),
  ('piston-pushes-blocks', 'Which redstone block can push other blocks forward?', 'Piston', 'Dropper', 'Comparator', 'Observer', 0, 'A powered piston extends its head and shoves up to 12 blocks in front of it.', 18, true, 'choice', null::jsonb, null::text[]),
  ('slime-block-bounces-fall', 'Landing on which block bounces you back into the air?', 'Honey Block', 'Hay Bale', 'Wool', 'Slime Block', 3, 'Slime blocks cancel fall damage and bounce you up unless you are sneaking.', 19, true, 'choice', null::jsonb, null::text[]),
  ('charcoal-works-for-torches', 'Which item goes on top of a stick to craft a torch?', 'Charcoal', 'Flint', 'Gunpowder', 'Glowstone Dust', 0, 'Torches take coal or charcoal, so smelted logs light your base even before you find coal.', 20, true, 'choice', null::jsonb, null::text[]),
  ('chest-needs-eight-planks', 'How many planks does it take to craft a chest?', '9', '6', '7', '8', 3, 'The planks fill every slot of the 3×3 grid except the center.', 21, true, 'choice', null::jsonb, null::text[]),
  ('sand-smelts-into-glass', 'What do you get when you smelt sand in a furnace?', 'Glass', 'Nether Quartz', 'Gravel', 'Clay', 0, 'Heat melts sand into glass, the go-to block for windows.', 22, true, 'choice', null::jsonb, null::text[]),
  ('stonecutter-shapes-stone-builds', 'Which workstation turns one block into stairs, slabs or walls without a crafting table?', 'Grindstone', 'Stonecutter', 'Loom', 'Smithing Table', 1, 'You pick the shape you want and it uses one block at a time, so no full recipe is needed.', 23, true, 'choice', null::jsonb, null::text[]),
  ('bee-pollinates-crops', 'Which mob makes crops grow faster after visiting flowers?', 'Rabbit', 'Allay', 'Parrot', 'Bee', 3, 'A bee carrying pollen helps crops it flies over grow a stage, so a hive near a farm speeds it up.', 24, true, 'choice', null::jsonb, null::text[]),
  ('water-keeps-farmland-hydrated', 'Which block keeps nearby farmland moist?', 'Lava', 'Snow Block', 'Ice', 'Water', 3, 'Water within 4 blocks keeps farmland moist and dark, and crops on moist farmland grow faster.', 25, true, 'choice', null::jsonb, null::text[]),
  ('dry-farmland-becomes-dirt', 'What does farmland turn into if it stays dry with nothing planted on it?', 'Gravel', 'Dirt', 'Mud', 'Sand', 1, 'Without water or crops farmland slowly dries out and turns back into dirt; jumping on it does the same.', 26, true, 'choice', null::jsonb, null::text[]),
  ('kelp-grows-underwater', 'Which plant keeps growing taller while fully underwater?', 'Sugar Cane', 'Kelp', 'Bamboo', 'Cactus', 1, 'Kelp grows upward through water blocks, which makes it great for an automatic underwater farm.', 27, true, 'choice', null::jsonb, null::text[]),
  ('bone-tames-wolf', 'Which item do you feed a wild wolf to tame it?', 'Leather', 'Feather', 'String', 'Bone', 3, 'Each bone has a chance to tame the wolf, and then it gets a collar and follows you.', 28, true, 'choice', null::jsonb, null::text[]),
  ('enderman-hurt-by-water', 'Which mob takes damage from water and rain?', 'Spider', 'Witch', 'Zombie', 'Enderman', 3, 'Water hurts endermen, so standing in water or under a roof of water helps you escape them.', 29, true, 'choice', null::jsonb, null::text[]),
  ('iron-golem-defends-village', 'Which big mob spawns in villages and fights off zombies?', 'Wandering Trader', 'Snow Golem', 'Iron Golem', 'Pillager', 2, 'Iron golems guard villagers and attack hostile mobs that come into the village.', 30, true, 'choice', null::jsonb, null::text[]),
  ('witch-throws-potions', 'Which hostile mob attacks by throwing splash potions?', 'Blaze', 'Skeleton', 'Drowned', 'Witch', 3, 'Witches throw harmful splash potions and drink potions themselves to heal.', 31, true, 'choice', null::jsonb, null::text[]),
  ('zombie-villager-cured', 'Which mob can you cure with Weakness and a golden apple?', 'Husk', 'Zombie Villager', 'Zombie', 'Drowned', 1, 'A zombie villager hit with Weakness and fed a golden apple turns back into a villager.', 32, true, 'choice', null::jsonb, null::text[]),
  ('pillager-fires-crossbow', 'Which weapon does a pillager attack with?', 'Trident', 'Crossbow', 'Axe', 'Bow', 1, 'Pillagers are ranged illagers that shoot arrows from crossbows.', 33, true, 'choice', null::jsonb, null::text[]),
  ('blaze-drops-rods', 'Which mob drops the rods used to craft a brewing stand?', 'Magma Cube', 'Blaze', 'Ghast', 'Wither Skeleton', 1, 'Blazes live in Nether fortresses and drop the rods needed for brewing stands and blaze powder.', 34, true, 'choice', null::jsonb, null::text[]),
  ('blaze-powder-for-eye-of-ender', 'What do you combine with an ender pearl to craft an Eye of Ender?', 'Redstone Dust', 'Glowstone Dust', 'Blaze Powder', 'Gunpowder', 2, 'One blaze powder plus one ender pearl makes an Eye of Ender, so you need both the Nether and endermen.', 35, true, 'choice', null::jsonb, null::text[]),
  ('ghast-shoots-fireballs', 'Which large flying Nether mob shoots fireballs?', 'Strider', 'Hoglin', 'Ghast', 'Piglin', 2, 'Ghasts float over open Nether areas and shoot fireballs that you can hit back at them.', 36, true, 'choice', null::jsonb, null::text[]),
  ('repeater-refreshes-signal', 'Which component boosts a weak redstone signal back to full strength?', 'Redstone Lamp', 'Redstone Comparator', 'Observer', 'Redstone Repeater', 3, 'A repeater always outputs a full-strength signal of 15, so long redstone lines keep working.', 37, true, 'choice', null::jsonb, null::text[]),
  ('eye-of-ender-finds-stronghold', 'Which item do you throw into an End gateway to reach the outer islands?', 'Snowball', 'Egg', 'Eye of Ender', 'Ender Pearl', 3, 'An End gateway floats in the air, so you throw an ender pearl into it to teleport to the outer islands.', 38, true, 'choice', null::jsonb, null::text[]),
  ('compass-points-to-world-spawn', 'In the Overworld, where does a regular compass point?', 'Nether Portal', 'Your bed', 'Nearest village', 'World spawn', 3, 'A normal compass always points to the world spawn, not to your bed or base.', 39, true, 'choice', null::jsonb, null::text[]),
  ('shield-blocks-attacks', 'Which item can you raise to block arrows and hits?', 'Iron Helmet', 'Shield', 'Turtle Shell', 'Iron Chestplate', 1, 'Armor only lowers damage, but a raised shield fully blocks most hits from the front.', 40, true, 'choice', null::jsonb, null::text[]),
  ('sleep-skips-thunderstorm', 'Besides at night, when can you sleep in a bed?', 'During a thunderstorm', 'At noon', 'During snowfall', 'At sunrise', 0, 'Thunderstorms are dark enough for monsters to spawn, so beds work then even in daytime.', 41, true, 'choice', null::jsonb, null::text[]),
  ('water-bucket-softens-falls', 'Which item cancels fall damage if you place it just before landing?', 'Lava Bucket', 'Fishing Rod', 'Milk Bucket', 'Water Bucket', 3, 'Landing in water cancels fall damage, so placing water just before impact saves you.', 42, true, 'choice', null::jsonb, null::text[]),
  ('phantom-comes-after-no-sleep', 'Which flying mob attacks players who skip sleep for several nights?', 'Bat', 'Bee', 'Phantom', 'Parrot', 2, 'Phantoms spawn in the night sky above players who have not slept for a while.', 43, true, 'choice', null::jsonb, null::text[]),
  ('armorer-uses-blast-furnace', 'Which job block turns a villager into an armorer?', 'Blast Furnace', 'Smoker', 'Smithing Table', 'Grindstone', 0, 'Armorers work at blast furnaces and sell armor for emeralds.', 44, true, 'choice', null::jsonb, null::text[]),
  ('cartographer-uses-cartography-table', 'Which villager job block is crafted from paper and planks?', 'Lectern', 'Fletching Table', 'Loom', 'Cartography Table', 3, 'Two paper over four planks make a cartography table, the cartographer''s job block.', 45, true, 'choice', null::jsonb, null::text[]),
  ('cauldron-makes-leatherworker', 'Which job block turns a villager into a leatherworker?', 'Composter', 'Barrel', 'Cauldron', 'Loom', 2, 'Leatherworkers work at cauldrons and trade leather and leather armor.', 46, true, 'choice', null::jsonb, null::text[]),
  ('fletcher-uses-fletching-table', 'A villager who sells arrows works at which job block?', 'Smithing Table', 'Blast Furnace', 'Grindstone', 'Fletching Table', 3, 'Fletchers work at fletching tables, buy sticks and sell arrows, bows and crossbows.', 47, true, 'choice', null::jsonb, null::text[]),
  ('loom-makes-shepherd', 'A villager that claims a loom gets which job?', 'Leatherworker', 'Mason', 'Shepherd', 'Butcher', 2, 'Shepherds work at looms and trade wool, dyes, beds and banners.', 48, true, 'choice', null::jsonb, null::text[]),
  ('nitwit-has-no-profession', 'Which villager can never get a job?', 'Mason', 'Cleric', 'Farmer', 'Nitwit', 3, 'Nitwits wear green coats and stay jobless forever, even next to a free job block.', 49, true, 'choice', null::jsonb, null::text[]),
  ('smoker-makes-butcher', 'Which job block turns a villager into a butcher?', 'Barrel', 'Smoker', 'Composter', 'Blast Furnace', 1, 'Butchers work at smokers, buy raw meat and sell cooked meat.', 50, true, 'choice', null::jsonb, null::text[]),
  ('stonecutter-makes-mason', 'A villager who sells bricks and terracotta works at which job block?', 'Stonecutter', 'Composter', 'Smithing Table', 'Cauldron', 0, 'Masons work at stonecutters, buy clay and sell bricks, terracotta and polished stone.', 51, true, 'choice', null::jsonb, null::text[]),
  ('anvil-combines-enchantments', 'Which block can repair an iron pickaxe using iron ingots?', 'Crafting Table', 'Grindstone', 'Anvil', 'Smithing Table', 2, 'Only an anvil repairs gear with its raw material, like iron ingots for iron tools.', 52, true, 'choice', null::jsonb, null::text[]),
  ('brewing-stand-makes-cleric', 'Which job block turns a villager into a cleric?', 'Grindstone', 'Lectern', 'Cauldron', 'Brewing Stand', 3, 'Clerics work at brewing stands and sell redstone, lapis, glowstone and ender pearls.', 53, true, 'choice', null::jsonb, null::text[]),
  ('cartographer-sells-ocean-map', 'Which villager sells explorer maps to ocean monuments?', 'Fisherman', 'Mason', 'Librarian', 'Cartographer', 3, 'Cartographers trade Ocean Explorer Maps, which mark the nearest ocean monument.', 54, true, 'choice', null::jsonb, null::text[]),
  ('curing-zombie-villager-lowers-prices', 'After you cure a zombie villager, what happens to its prices?', 'They rise', 'All trades lock', 'They drop', 'Nothing changes', 2, 'A cured villager is grateful and gives big discounts to the player who cured it.', 55, true, 'choice', null::jsonb, null::text[]),
  ('smithing-table-makes-toolsmith', 'A villager who sells pickaxes and shovels works at which job block?', 'Blast Furnace', 'Stonecutter', 'Grindstone', 'Smithing Table', 3, 'Toolsmiths work at smithing tables and sell tools like pickaxes, shovels and hoes.', 56, true, 'choice', null::jsonb, null::text[]),
  ('villager-needs-bed-to-breed', 'What must be free in a village for villagers to have babies?', 'Beds', 'Lanterns', 'Campfires', 'Bells', 0, 'Villagers only breed when there''s an unclaimed bed for the baby, plus enough food.', 57, true, 'choice', null::jsonb, null::text[]),
  ('villagers-restock-at-workstation', 'What must a villager reach to restock its trades?', 'Chest', 'Bell', 'Hay Bale', 'Job block', 3, 'Villagers refill sold-out trades only while working at their own job block.', 58, true, 'choice', null::jsonb, null::text[]),
  ('bread-easy-hunger-refill', 'Which food can you craft from just three wheat?', 'Cake', 'Pumpkin Pie', 'Cookie', 'Bread', 3, 'Three wheat in a row make bread; cookies need cocoa, cake and pie need eggs and sugar.', 59, true, 'choice', null::jsonb, null::text[]),
  ('milk-clears-most-effects', 'Which drink removes all your status effects at once?', 'Milk Bucket', 'Water Bottle', 'Potion of Healing', 'Honey Bottle', 0, 'Milk clears every effect, good and bad, while honey only removes Poison.', 60, true, 'choice', null::jsonb, null::text[]),
  ('rotten-flesh-emergency-food', 'Which zombie drop is edible but often gives you Hunger?', 'Potato', 'Rotten Flesh', 'Carrot', 'Iron Ingot', 1, 'Rotten flesh has an 80% chance to cause Hunger, so eat it only in an emergency.', 61, true, 'choice', null::jsonb, null::text[]),
  ('air-bubbles-show-drowning', 'Underwater, which icons run out before you start to drown?', 'Armor Icons', 'XP Bar', 'Drumsticks', 'Air Bubbles', 3, 'Bubbles show your air; when they are gone you lose health every second.', 62, true, 'choice', null::jsonb, null::text[]),
  ('spider-eye-causes-poison', 'Which food always poisons you when eaten?', 'Sweet Berries', 'Spider Eye', 'Rotten Flesh', 'Raw Chicken', 1, 'A spider eye always gives Poison, while rotten flesh and raw chicken only risk Hunger.', 63, true, 'choice', null::jsonb, null::text[]),
  ('torches-help-stop-indoor-spawns', 'What stops hostile mobs from spawning inside your house?', 'Torches', 'Flower Pots', 'Paintings', 'Item Frames', 0, 'Hostile mobs need total darkness to spawn, and torches remove it.', 64, true, 'choice', null::jsonb, null::text[]),
  ('sleep-turns-world-to-morning', 'What can stop you from sleeping in a bed at night?', 'Monsters nearby', 'Wearing armor', 'Full inventory', 'Low hunger', 0, 'You cannot rest while hostile mobs are within about 8 blocks of the bed.', 65, true, 'choice', null::jsonb, null::text[]),
  ('roof-completes-first-shelter', 'How many real-time minutes does one full day-and-night cycle last?', '60', '30', '20', '10', 2, 'A full day lasts 20 minutes, and about 7 of them are night, when hostile mobs roam.', 66, true, 'choice', null::jsonb, null::text[]),
  ('water-puts-out-fire', 'What quickly puts out the flames when you are on fire?', 'Sand', 'Wool', 'Water', 'Gravel', 2, 'Stepping into water instantly puts out the fire, so keep a water bucket near lava.', 67, true, 'choice', null::jsonb, null::text[]),
  ('minecart-rides-on-rails', 'Which vehicle is made to ride along rails?', 'Elytra', 'Boat', 'Minecart', 'Lead', 2, 'Minecarts roll on rails and can carry players, mobs or items.', 68, true, 'choice', null::jsonb, null::text[]),
  ('wooden-sword-basic-weapon', 'Which item is crafted from two planks and one stick?', 'Wooden Sword', 'Wooden Axe', 'Wooden Pickaxe', 'Wooden Shovel', 0, 'Two planks on a stick make a sword, while a pickaxe or axe needs three planks and two sticks.', 69, true, 'choice', null::jsonb, null::text[]),
  ('log-smelts-into-charcoal', 'What do you get by smelting a log in a furnace?', 'Stick', 'Coal', 'Planks', 'Charcoal', 3, 'A smelted log becomes charcoal, which burns just as long as regular coal.', 70, true, 'choice', null::jsonb, null::text[]),
  ('cobblestone-smelts-into-stone', 'What do you get by smelting a cactus in a furnace?', 'Slimeball', 'Lime Dye', 'Green Dye', 'Dried Kelp', 2, 'Smelting cactus is how you get green dye, and mixing it with white dye makes lime dye.', 71, true, 'choice', null::jsonb, null::text[]),
  ('dried-kelp-block-is-fuel', 'Which of these blocks can be burned as furnace fuel?', 'Dried Kelp Block', 'Honey Block', 'Slime Block', 'Hay Bale', 0, 'A dried kelp block smelts 20 items, so a kelp farm gives you endless fuel.', 72, true, 'choice', null::jsonb, null::text[]),
  ('anvil-renames-and-repairs', 'Which workstation lets you rename items and combine enchantments?', 'Smithing Table', 'Anvil', 'Cartography Table', 'Loom', 1, 'An anvil spends experience levels to rename, repair or merge enchanted items.', 73, true, 'choice', null::jsonb, null::text[]),
  ('loom-adds-banner-patterns-crafting', 'Which workstation is used to add patterns to banners?', 'Grindstone', 'Smoker', 'Loom', 'Blast Furnace', 2, 'A loom combines a banner and dye to add designs layer by layer.', 74, true, 'choice', null::jsonb, null::text[]),
  ('grindstone-clears-enchantments', 'Which block do you craft by surrounding a furnace with four logs?', 'Campfire', 'Barrel', 'Smoker', 'Blast Furnace', 2, 'Four logs around a furnace make a smoker, which is also the butcher''s job block.', 75, true, 'choice', null::jsonb, null::text[]),
  ('stone-pickaxe-mines-iron-ore', 'What is the weakest pickaxe that can mine iron ore?', 'Golden Pickaxe', 'Iron Pickaxe', 'Stone Pickaxe', 'Wooden Pickaxe', 2, 'Wooden and golden pickaxes break iron ore without dropping anything, so stone is the minimum.', 76, true, 'choice', null::jsonb, null::text[]),
  ('shears-need-iron-ingots', 'Which item is crafted from just two iron ingots?', 'Cauldron', 'Bucket', 'Minecart', 'Shears', 3, 'Two iron ingots placed diagonally make shears, while a bucket needs three.', 77, true, 'choice', null::jsonb, null::text[]),
  ('paper-from-sugar-cane', 'What is sugar cane crafted into for books and maps?', 'Clay', 'Paper', 'String', 'Leather', 1, 'Three sugar cane in a row make three paper for books, maps and firework rockets.', 78, true, 'choice', null::jsonb, null::text[]),
  ('flint-and-steel-lights-portals', 'Which furnace fuel smelts the most items?', 'Dried Kelp Block', 'Lava Bucket', 'Block of Coal', 'Blaze Rod', 1, 'A lava bucket smelts 100 items, more than a block of coal (80), so lava makes a great fuel.', 79, true, 'choice', null::jsonb, null::text[]),
  ('clay-can-be-smelted-into-bricks', 'Which item do you smelt in a furnace to get a brick?', 'Sand', 'Cobblestone', 'Raw Iron', 'Clay Ball', 3, 'A clay ball bakes into a brick, while sand makes glass and cobblestone makes stone.', 80, true, 'choice', null::jsonb, null::text[]),
  ('flowing-lava-and-water-make-cobblestone', 'What block forms when flowing lava spreads sideways into water?', 'Cobblestone', 'Netherrack', 'Obsidian', 'Sandstone', 0, 'Flowing lava meeting water makes cobblestone, the trick behind every cobblestone generator.', 81, true, 'choice', null::jsonb, null::text[]),
  ('ice-can-melt-into-water', 'Which block melts into water if you place a torch right next to it?', 'Blue Ice', 'Ice', 'Packed Ice', 'Glass', 1, 'Regular ice melts in bright block light, but packed ice and blue ice never melt.', 82, true, 'choice', null::jsonb, null::text[]),
  ('stone-bricks-crafted-from-stone', 'What do you get by crafting four stone blocks in a 2×2 square?', 'Cobblestone', 'Smooth Stone', 'Stone Bricks', 'Polished Andesite', 2, 'Four stone make four stone bricks; cobblestone won''t work until it is smelted into stone.', 83, true, 'choice', null::jsonb, null::text[]),
  ('terracotta-smelts-from-clay-block', 'What does a clay block turn into when smelted in a furnace?', 'Terracotta', 'Sandstone', 'Bricks', 'Concrete', 0, 'A whole clay block bakes into terracotta, while single clay balls bake into bricks.', 84, true, 'choice', null::jsonb, null::text[]),
  ('pressure-plate-sends-signal-when-stepped-on', 'Which flat block sends a redstone signal when a player or mob steps on it?', 'Pressure Plate', 'Carpet', 'Trapdoor', 'Daylight Detector', 0, 'Pressure plates power redstone while something stands on them, great for automatic doors.', 85, true, 'choice', null::jsonb, null::text[]),
  ('glass-drops-nothing-without-silk-touch', 'Which block drops nothing when broken, unless you use Silk Touch?', 'Glass', 'Oak Planks', 'Wool', 'Dirt', 0, 'Glass shatters and disappears when broken; only Silk Touch lets you pick it back up.', 86, true, 'choice', null::jsonb, null::text[]),
  ('unsupported-scaffolding-breaks', 'Standing on scaffolding, what do you do to move down through it?', 'Jump', 'Look down', 'Sneak', 'Sprint', 2, 'Sneaking lets you sink down through scaffolding, while jumping climbs you up.', 87, true, 'choice', null::jsonb, null::text[]),
  ('glowstone-drops-dust-when-broken', 'Which Nether block breaks into dust unless you use Silk Touch?', 'Glowstone', 'Netherrack', 'Magma Block', 'Shroomlight', 0, 'Glowstone drops 2–4 glowstone dust, and you need four dust to craft the block back.', 88, true, 'choice', null::jsonb, null::text[]),
  ('nether-quartz-ore-drops-quartz', 'Which Nether ore shows white crystals inside netherrack?', 'Nether Quartz Ore', 'Nether Gold Ore', 'Ancient Debris', 'Iron Ore', 0, 'Nether quartz ore drops quartz, used for quartz blocks, comparators and observers.', 89, true, 'choice', null::jsonb, null::text[]),
  ('fence-connects-into-lines', 'Which block can you tie a lead to?', 'Fence', 'Ladder', 'Glass Pane', 'Chest', 0, 'Using a lead on a fence ties the animal to a knot on the post, keeping it in place.', 90, true, 'choice', null::jsonb, null::text[]),
  ('potatoes-grow-from-potatoes', 'Which crop sometimes drops a poisonous version of itself when harvested?', 'Beetroot', 'Carrot', 'Sweet Berries', 'Potato', 3, 'Fully grown potatoes have a small chance to also drop a poisonous potato, which is risky to eat.', 91, true, 'choice', null::jsonb, null::text[]),
  ('sugar-cane-needs-water-nearby', 'Which plant can only be planted on a block right next to water?', 'Bamboo', 'Sugar Cane', 'Cactus', 'Sweet Berries', 1, 'Sugar cane needs water touching the block it stands on, which is why it grows along rivers.', 92, true, 'choice', null::jsonb, null::text[]),
  ('egg-is-needed-for-cake', 'Besides milk, sugar and wheat, what goes into a cake recipe?', 'Leather', 'Feather', 'Egg', 'Honey Bottle', 2, 'A cake uses 3 milk buckets, 2 sugar, 3 wheat and 1 egg, so you need chickens as well as cows.', 93, true, 'choice', null::jsonb, null::text[]),
  ('sugar-completes-pumpkin-pie', 'Pumpkin pie is crafted from a pumpkin, an egg and what else?', 'Sugar', 'Cocoa Beans', 'Wheat', 'Milk Bucket', 0, 'Pumpkin pie is shapeless: just a pumpkin, an egg and sugar from sugar cane, with no milk or wheat.', 94, true, 'choice', null::jsonb, null::text[]),
  ('seeds-breed-chickens', 'Which item do you use to breed chickens?', 'Apple', 'Wheat', 'Bread', 'Wheat Seeds', 3, 'Chickens eat seeds, not grown wheat; any seeds work, including pumpkin, melon and beetroot seeds.', 95, true, 'choice', null::jsonb, null::text[]),
  ('golden-carrot-breeds-rabbits', 'Which flower can you use to breed rabbits?', 'Poppy', 'Dandelion', 'Cornflower', 'Oxeye Daisy', 1, 'Rabbits breed with carrots, golden carrots or dandelions, the yellow flower they also eat in the wild.', 96, true, 'choice', null::jsonb, null::text[]),
  ('golden-apple-breeds-horses', 'Which food makes two tamed horses ready to breed?', 'Golden Apple', 'Sugar', 'Apple', 'Wheat', 0, 'Horses breed only with golden apples or golden carrots; plain apples, sugar and wheat just heal them.', 97, true, 'choice', null::jsonb, null::text[]),
  ('cocoa-beans-grow-on-jungle-logs', 'On which log can cocoa beans be planted?', 'Birch Log', 'Oak Log', 'Jungle Log', 'Mangrove Log', 2, 'Cocoa pods grow on the side of jungle logs, the same trees they hang from in jungles.', 98, true, 'choice', null::jsonb, null::text[]),
  ('glass-bottle-collects-honey', 'Which item collects honey from a full beehive?', 'Cauldron', 'Glass Bottle', 'Bucket', 'Bowl', 1, 'Honey is collected into an empty glass bottle, giving a honey bottle that also cures poison.', 99, true, 'choice', null::jsonb, null::text[]),
  ('shears-collect-honeycomb', 'Which tool harvests honeycomb from a full beehive?', 'Shears', 'Shovel', 'Axe', 'Hoe', 0, 'Shears snip 3 honeycombs off a full hive or nest, which you can use to wax copper or craft candles.', 100, true, 'choice', null::jsonb, null::text[]),
  ('cocoa-beans-craft-cookies', 'Which ingredient goes between two wheat to craft cookies?', 'Cocoa Beans', 'Sugar', 'Beetroot', 'Egg', 0, 'Two wheat with cocoa beans in the middle make 8 cookies, so cocoa farms are worth planting.', 101, true, 'choice', null::jsonb, null::text[]),
  ('goat-can-ram-players', 'Which mountain mob can suddenly ram you and knock you off a cliff?', 'Rabbit', 'Sheep', 'Goat', 'Llama', 2, 'Goats live in mountains and sometimes charge at players, which can push you off a ledge.', 102, true, 'choice', null::jsonb, null::text[]),
  ('llama-spits-when-angry', 'Which animal spits at mobs and players that attack it?', 'Horse', 'Panda', 'Goat', 'Llama', 3, 'Llamas defend themselves by spitting, and they also spit at wolves on sight.', 103, true, 'choice', null::jsonb, null::text[]),
  ('bee-dies-after-stinging', 'Which mob dies soon after it stings someone?', 'Endermite', 'Phantom', 'Bee', 'Cave Spider', 2, 'A bee loses its stinger when it stings, and it dies about a minute later.', 104, true, 'choice', null::jsonb, null::text[]),
  ('polar-bear-protects-cub', 'Which snowy-biome animal turns hostile if you go near its cub?', 'Polar Bear', 'Fox', 'Goat', 'Rabbit', 0, 'Adult polar bears are neutral, but they attack players who come close to their cubs.', 105, true, 'choice', null::jsonb, null::text[]),
  ('drowned-can-throw-trident', 'Which underwater undead mob can throw a trident at you?', 'Skeleton', 'Drowned', 'Zombie', 'Husk', 1, 'Some drowned spawn holding a trident and throw it, and they are the only mob that can drop one.', 106, true, 'choice', null::jsonb, null::text[]),
  ('ghast-launches-fireballs', 'Which snowy-biome mob shoots arrows that give you Slowness?', 'Skeleton', 'Stray', 'Husk', 'Pillager', 1, 'Strays are icy skeletons from snowy biomes, and their tipped arrows slow you down.', 107, true, 'choice', null::jsonb, null::text[]),
  ('arrows-needed-for-bow', 'Which item forms the tip of an arrow in its crafting recipe?', 'Gravel', 'Bone', 'Flint', 'Iron Nugget', 2, 'Arrows are crafted from flint, a stick and a feather; flint drops from broken gravel.', 108, true, 'choice', null::jsonb, null::text[]),
  ('golden-apple-gives-extra-hearts', 'Which item is crafted from six planks and one iron ingot?', 'Crossbow', 'Barrel', 'Shield', 'Bucket', 2, 'Six planks with an iron ingot at the top make a shield, which blocks most attacks from the front.', 109, true, 'choice', null::jsonb, null::text[]),
  ('potion-of-healing-restores-health', 'Which potion gives back lost hearts instantly?', 'Potion of Fire Resistance', 'Potion of Healing', 'Potion of Swiftness', 'Potion of Night Vision', 1, 'Healing works at once, unlike Regeneration, which restores hearts slowly over time.', 110, true, 'choice', null::jsonb, null::text[]),
  ('warped-fungus-stick-steers-strider', 'What do you put on a stick to steer a strider you are riding?', 'Crimson Fungus', 'Nether Wart', 'Carrot', 'Warped Fungus', 3, 'A warped fungus on a stick steers a saddled strider, just like a carrot on a stick steers a pig.', 111, true, 'choice', null::jsonb, null::text[]),
  ('end-crystal-heals-dragon', 'Which object on top of the obsidian pillars heals the dragon?', 'Beacon', 'End Crystal', 'Sea Lantern', 'Respawn Anchor', 1, 'End crystals beam healing to the dragon, so players destroy them first, often with arrows.', 112, true, 'choice', null::jsonb, null::text[]),
  ('dragon-egg-appears-after-fight', 'Which trophy block appears on the exit portal after the first boss fight in the End?', 'Conduit', 'Dragon Egg', 'Lodestone', 'Beacon', 1, 'The egg appears after the first win and teleports away if you hit it, so players knock it down with a piston.', 113, true, 'choice', null::jsonb, null::text[]),
  ('shulker-causes-levitation', 'Which End City mob shoots projectiles that make you float up into the air?', 'Blaze', 'Shulker', 'Endermite', 'Enderman', 1, 'A shulker''s homing bullet gives you Levitation, lifting you up until the effect wears off.', 114, true, 'choice', null::jsonb, null::text[]),
  ('fire-resistance-helps-in-lava', 'Which potion effect lets you swim in lava without taking damage?', 'Water Breathing', 'Night Vision', 'Fire Resistance', 'Slow Falling', 2, 'Fire Resistance blocks all fire and lava damage, which makes Nether trips much safer.', 115, true, 'choice', null::jsonb, null::text[]),
  ('lodestone-guides-special-compass', 'Which block can you link a compass to so it points correctly in the Nether?', 'Lightning Rod', 'Lodestone', 'Respawn Anchor', 'Beacon', 1, 'A compass used on a lodestone points to that block, even in the Nether where normal compasses spin.', 116, true, 'choice', null::jsonb, null::text[]),
  ('respawn-anchor-sets-spawn-in-nether', 'What do you get by smelting ancient debris?', 'Netherite Ingot', 'Gold Ingot', 'Iron Nugget', 'Netherite Scrap', 3, 'Ancient debris smelts into netherite scrap; four scraps and four gold ingots craft one netherite ingot.', 117, true, 'choice', null::jsonb, null::text[]),
  ('sticky-piston-pulls-block-back', 'Which block pushes another block out and pulls it back when the power turns off?', 'Sticky Piston', 'Piston', 'Observer', 'Dispenser', 0, 'A sticky piston has a slimeball on its head, so it grabs the pushed block and pulls it back.', 118, true, 'choice', null::jsonb, null::text[]),
  ('note-block-plays-musical-tone', 'Which block plays a tuned musical sound each time it gets a redstone signal?', 'Barrel', 'Redstone Lamp', 'Note Block', 'Jukebox', 2, 'Using a note block changes its pitch, and the block underneath decides which instrument it plays.', 119, true, 'choice', null::jsonb, null::text[]),
  ('elytra-found-in-end-ship', 'Which storage block keeps its items inside when you break it?', 'Chest', 'Trapped Chest', 'Barrel', 'Shulker Box', 3, 'A shulker box drops as an item with everything still inside, which makes it perfect for moving loot.', 120, true, 'choice', null::jsonb, null::text[]),
  ('tf-still-burning-after-lava', 'After you climb out of lava, you keep burning for a few seconds.', 'True', 'False', null, null, 0, 'True: you stay on fire for a while after leaving lava, so jump into water to put it out.', 121, true, 'true-false', null::jsonb, null::text[]),
  ('tf-sweet-berry-bush-safe', 'Walking through a grown sweet berry bush is completely safe.', 'True', 'False', null, null, 1, 'False: a grown sweet berry bush slows you down and hurts you while you move through it.', 122, true, 'true-false', null::jsonb, null::text[]),
  ('tf-wooden-tools-outlast-stone', 'Wooden tools last longer than stone tools.', 'True', 'False', null, null, 1, 'False: stone tools last more than twice as long as wooden ones, so upgrade early.', 123, true, 'true-false', null::jsonb, null::text[]),
  ('tf-smelting-gives-experience', 'Taking smelted items out of a furnace gives you experience.', 'True', 'False', null, null, 0, 'True: a furnace saves up experience while it smelts and gives it to you when you take the items.', 124, true, 'true-false', null::jsonb, null::text[]),
  ('tf-water-flows-farther-than-lava', 'In the Overworld, water flows farther than lava.', 'True', 'False', null, null, 0, 'True: in the Overworld water spreads 7 blocks from its source, but lava only 3.', 125, true, 'true-false', null::jsonb, null::text[]),
  ('tf-netherrack-fire-goes-out', 'Fire on top of netherrack goes out after a few seconds.', 'True', 'False', null, null, 1, 'False: fire lit on top of netherrack burns forever, and even rain can''t put it out.', 126, true, 'true-false', null::jsonb, null::text[]),
  ('tf-zombie-turns-into-drowned', 'A zombie that stays underwater long enough turns into a drowned.', 'True', 'False', null, null, 0, 'True: after 30 seconds with its head underwater, a zombie starts shaking and becomes a drowned.', 127, true, 'true-false', null::jsonb, null::text[]),
  ('tf-big-slimes-vanish', 'Big slimes disappear for good when you defeat them.', 'True', 'False', null, null, 1, 'False: a big slime splits into several smaller slimes, and only the tiniest ones drop slimeballs.', 128, true, 'true-false', null::jsonb, null::text[]),
  ('tf-feeding-babies-grow-faster', 'Feeding a baby animal its breeding food helps it grow up faster.', 'True', 'False', null, null, 0, 'True: each feeding takes a little time off the 20 minutes a baby animal needs to grow up.', 129, true, 'true-false', null::jsonb, null::text[]),
  ('tf-rabbits-bred-with-wheat', 'Rabbits can be bred with wheat.', 'True', 'False', null, null, 1, 'False: rabbits are bred with carrots, golden carrots or dandelions, not wheat.', 130, true, 'true-false', null::jsonb, null::text[]),
  ('tf-nitwits-never-get-jobs', 'Nitwit villagers in green robes can never get a job.', 'True', 'False', null, null, 0, 'True: nitwits can''t take a job or trade with you, but they can still have babies.', 131, true, 'true-false', null::jsonb, null::text[]),
  ('tf-baby-villagers-trade', 'Baby villagers can trade with you.', 'True', 'False', null, null, 1, 'False: baby villagers can''t trade; you have to wait until they grow up and take a job.', 132, true, 'true-false', null::jsonb, null::text[]),
  ('tf-villages-in-snowy-plains', 'Villages can generate in snowy plains.', 'True', 'False', null, null, 0, 'True: snowy plains have their own villages with spruce houses and villagers in warm clothes.', 133, true, 'true-false', null::jsonb, null::text[]),
  ('tf-pandas-in-birch-forests', 'Pandas spawn naturally in birch forests.', 'True', 'False', null, null, 1, 'False: pandas live in jungles and are most common in bamboo jungles.', 134, true, 'true-false', null::jsonb, null::text[]),
  ('tf-nether-one-block-eight', 'Walking 1 block in the Nether moves you 8 blocks in the Overworld.', 'True', 'False', null, null, 0, 'True: that is why players use Nether portals as shortcuts for long trips.', 135, true, 'true-false', null::jsonb, null::text[]),
  ('tf-lever-turns-itself-off', 'A lever turns off by itself a moment after you flip it.', 'True', 'False', null, null, 1, 'False: a lever stays on until you flip it back; buttons are the ones that switch off by themselves.', 136, true, 'true-false', null::jsonb, null::text[]),
  ('pic-iron-builds-golem', 'Players can build which mob from blocks of the item shown?', 'Wither', 'Villager', 'Iron Golem', 'Snow Golem', 2, 'Four blocks of iron in a T shape topped with a carved pumpkin build an iron golem.', 137, true, 'picture', '{"sprite":"iron-ingot","type":"picture"}'::jsonb, null::text[]),
  ('pic-thrown-egg-hatches-chick', 'Throw the item in the picture. What can sometimes hatch?', 'Baby Chicken', 'Baby Turtle', 'Silverfish', 'Bat', 0, 'A thrown egg has a 1 in 8 chance to hatch a baby chicken, and very rarely four.', 138, true, 'picture', '{"sprite":"egg","type":"picture"}'::jsonb, null::text[]),
  ('pic-gold-makes-golden-apple', 'Surround an apple with eight of the item shown. What do you get?', 'Glistering Melon Slice', 'Cake', 'Golden Apple', 'Golden Carrot', 2, 'Eight gold ingots around an apple craft a golden apple, a strong healing food.', 139, true, 'picture', '{"sprite":"gold-ingot","type":"picture"}'::jsonb, null::text[]),
  ('pic-slimeball-sticky-piston', 'Add the item shown to a piston. Which block do you get?', 'Sticky Piston', 'Hopper', 'Dispenser', 'Observer', 0, 'A slimeball on top of a piston crafts a sticky piston, which can pull blocks back.', 140, true, 'picture', '{"sprite":"slimeball","type":"picture"}'::jsonb, null::text[]),
  ('pic-redstone-torch-recipe', 'Put the item shown on top of a stick. What do you craft?', 'Torch', 'Lever', 'Redstone Repeater', 'Redstone Torch', 3, 'Redstone dust above a stick makes a redstone torch, a power source that stays on.', 141, true, 'picture', '{"sprite":"redstone","type":"picture"}'::jsonb, null::text[]),
  ('pic-diamond-ore-needs-iron', 'What is the weakest pickaxe that mines the ore of the item shown?', 'Iron Pickaxe', 'Golden Pickaxe', 'Stone Pickaxe', 'Diamond Pickaxe', 0, 'Diamond ore needs an iron pickaxe or better; weaker pickaxes break it with no drop.', 142, true, 'picture', '{"sprite":"diamond","type":"picture"}'::jsonb, null::text[]),
  ('pic-shears-break-wool-fastest', 'Which tool breaks the block in the picture the fastest?', 'Axe', 'Pickaxe', 'Shears', 'Sword', 2, 'Shears break wool much faster than any other tool, and the block still drops.', 143, true, 'picture', '{"sprite":"wool","type":"picture"}'::jsonb, null::text[]),
  ('pic-emerald-wandering-trader', 'Which of these mobs will trade with you for the item shown?', 'Pillager', 'Piglin', 'Wandering Trader', 'Witch', 2, 'Wandering traders, like villagers, sell their goods for emeralds; piglins want gold instead.', 144, true, 'picture', '{"sprite":"emerald","type":"picture"}'::jsonb, null::text[]),
  ('pic-fletcher-buys-flint', 'Which villager will pay you emeralds for the item shown?', 'Fletcher', 'Butcher', 'Farmer', 'Librarian', 0, 'Apprentice fletchers buy flint for emeralds, since they use it to make arrows.', 145, true, 'picture', '{"sprite":"flint","type":"picture"}'::jsonb, null::text[]),
  ('recipe-iron-pickaxe-missing-ingot', 'Which ingredient completes this iron pickaxe recipe?', 'Flint', 'Gold Ingot', 'Coal', 'Iron Ingot', 3, 'An iron pickaxe takes three iron ingots on top and two sticks, and all three ingots must match.', 146, true, 'recipe', '{"grid":["iron-ingot","iron-ingot",null,null,"stick",null,null,"stick",null],"missingSlot":2,"type":"recipe"}'::jsonb, array['flint', 'gold-ingot', 'coal', 'iron-ingot']::text[]),
  ('recipe-bow-missing-stick', 'Which ingredient completes this bow recipe?', 'Stick', 'Feather', 'Iron Ingot', 'Sugar Cane', 0, 'A bow is three sticks bent in a curve with three string along one side.', 147, true, 'recipe', '{"grid":[null,null,"string","stick",null,"string",null,"stick","string"],"missingSlot":1,"type":"recipe"}'::jsonb, array['stick', 'feather', 'iron-ingot', 'sugar-cane']::text[]),
  ('recipe-cake-missing-sugar', 'One ingredient is missing from this cake. Which one?', 'Gunpowder', 'Wheat', 'Egg', 'Sugar', 3, 'A cake needs three milk buckets, two sugar, one egg and three wheat.', 148, true, 'recipe', '{"grid":["milk-bucket","milk-bucket","milk-bucket","sugar","egg",null,"wheat","wheat","wheat"],"missingSlot":5,"type":"recipe"}'::jsonb, array['gunpowder', 'wheat', 'egg', 'sugar']::text[]),
  ('recipe-book-missing-leather', 'Which item is missing from this book recipe?', 'Feather', 'Leather', 'Wool', 'String', 1, 'A book is three paper and one leather, placed anywhere in the grid.', 149, true, 'recipe', '{"grid":["paper","paper",null,"paper",null,null,null,null,null],"missingSlot":4,"type":"recipe"}'::jsonb, array['feather', 'leather', 'wool', 'string']::text[]),
  ('recipe-bookshelf-missing-book', 'What belongs in the empty square to craft a bookshelf?', 'Paper', 'Leather', 'Book', 'Wool', 2, 'A bookshelf is six planks with three books across the middle row.', 150, true, 'recipe', '{"grid":["planks","planks","planks","book",null,"book","planks","planks","planks"],"missingSlot":4,"type":"recipe"}'::jsonb, array['paper', 'leather', 'book', 'wool']::text[]),
  ('recipe-tnt-missing-gunpowder', 'One ingredient is missing from this TNT recipe. Which?', 'Redstone Dust', 'Gunpowder', 'Sugar', 'Coal', 1, 'TNT is five gunpowder and four sand placed in a checkerboard pattern.', 151, true, 'recipe', '{"grid":["gunpowder","sand","gunpowder","sand",null,"sand","gunpowder","sand","gunpowder"],"missingSlot":4,"type":"recipe"}'::jsonb, array['redstone', 'gunpowder', 'sugar', 'coal']::text[]),
  ('recipe-arrow-missing-feather', 'What goes in the empty slot to finish these arrows?', 'Paper', 'Feather', 'String', 'Leather', 1, 'Flint on top, a stick in the middle and a feather at the bottom craft 4 arrows.', 152, true, 'recipe', '{"grid":[null,"flint",null,null,"stick",null,null,null,null],"missingSlot":7,"type":"recipe"}'::jsonb, array['paper', 'feather', 'string', 'leather']::text[]),
  ('recipe-bucket-missing-ingot', 'Which ingredient completes this bucket recipe?', 'Cobblestone', 'Glass', 'Iron Ingot', 'Gold Ingot', 2, 'A bucket is three iron ingots in a V shape.', 153, true, 'recipe', '{"grid":[null,null,null,"iron-ingot",null,"iron-ingot",null,null,null],"missingSlot":7,"type":"recipe"}'::jsonb, array['cobblestone', 'glass', 'iron-ingot', 'gold-ingot']::text[]),
  ('ice-spikes-packed-ice-towers', 'Which snowy biome has tall pointed towers made of packed ice?', 'Snowy Taiga', 'Frozen River', 'Snowy Plains', 'Ice Spikes', 3, 'The ice spikes biome is a snowy plain dotted with tall spikes made of packed ice.', 154, true, 'choice', null::jsonb, null::text[]),
  ('meadow-flowers-few-trees', 'Which grassy mountain biome is full of flowers but has almost no trees?', 'Stony Peaks', 'Grove', 'Meadow', 'Cherry Grove', 2, 'Meadows are flowery mountain fields, and their rare lone trees usually carry bee nests.', 155, true, 'choice', null::jsonb, null::text[]),
  ('crimson-forest-hoglins-spawn', 'Outside of bastions, hoglins spawn naturally only in which Nether biome?', 'Soul Sand Valley', 'Crimson Forest', 'Warped Forest', 'Basalt Deltas', 1, 'Crimson forests are the only biome where hoglins spawn on their own, along with piglins.', 156, true, 'choice', null::jsonb, null::text[]),
  ('sunflower-plains-face-east', 'Tall yellow flowers that always face east grow wild in which biome?', 'Sunflower Plains', 'Meadow', 'Savanna', 'Flower Forest', 0, 'Sunflowers generate only in sunflower plains, and their flower heads always point east.', 157, true, 'choice', null::jsonb, null::text[]),
  ('dark-forest-huge-mushrooms', 'Huge red and brown mushrooms grow between thick trees in which biome?', 'Jungle', 'Dark Forest', 'Taiga', 'Birch Forest', 1, 'Dark forests mix thick dark oak trees with huge mushrooms, so they stay dim even by day.', 158, true, 'choice', null::jsonb, null::text[]),
  ('azalea-tree-marks-lush-caves', 'An azalea tree on the surface often means which cave biome is below?', 'Lush Caves', 'Deep Dark', 'Dripstone Caves', 'Mushroom Fields', 0, 'Azalea trees grow above lush caves, a sign of moss and glow berries down below.', 159, true, 'choice', null::jsonb, null::text[]),
  ('parrots-spawn-in-jungles', 'Wild parrots spawn naturally in which biome?', 'Jungle', 'Swamp', 'Savanna', 'Cherry Grove', 0, 'Parrots spawn in jungles, including bamboo jungles, and come in five colors.', 160, true, 'choice', null::jsonb, null::text[]),
  ('husks-spawn-in-deserts', 'Husks, zombies that don''t burn in sunlight, spawn in which biome?', 'Savanna', 'Jungle', 'Snowy Plains', 'Desert', 3, 'In deserts, most zombies spawn as husks, which don''t burn in sunlight.', 161, true, 'choice', null::jsonb, null::text[]),
  ('blue-orchids-only-in-swamps', 'Blue orchid flowers grow naturally only in which biome?', 'Meadow', 'Flower Forest', 'Jungle', 'Swamp', 3, 'Blue orchids generate only in swamps, and they can be crafted into light blue dye.', 162, true, 'choice', null::jsonb, null::text[]),
  ('trail-ruins-buried-terracotta', 'Which half-buried ruins with terracotta and suspicious gravel appear in taigas and jungles?', 'Trail Ruins', 'Ruined Portal', 'Ocean Ruins', 'Desert Pyramid', 0, 'Trail ruins are mostly buried in gravel and dirt, with a terracotta tower and gravel to brush.', 163, true, 'choice', null::jsonb, null::text[]),
  ('desert-pyramid-four-chests', 'How many chests are hidden in a desert pyramid''s secret room?', '4', '6', '2', '1', 0, 'The secret room holds four chests, guarded by a pressure plate wired to nine TNT.', 164, true, 'choice', null::jsonb, null::text[]),
  ('stronghold-portal-room-silverfish', 'Which mob comes from the spawner in a stronghold''s portal room?', 'Cave Spider', 'Endermite', 'Silverfish', 'Zombie', 2, 'A silverfish spawner sits right next to the End portal, so light it up or break it fast.', 165, true, 'choice', null::jsonb, null::text[]),
  ('fossils-in-deserts-and-swamps', 'Big bone-block fossils are buried under deserts and which other biome?', 'Savanna', 'Swamp', 'Jungle', 'Taiga', 1, 'Fossils generate only under deserts, swamps and mangrove swamps.', 166, true, 'choice', null::jsonb, null::text[]),
  ('outpost-caged-iron-golem', 'Which big mob can be found locked in a cage next to a pillager outpost?', 'Ravager', 'Iron Golem', 'Wolf', 'Polar Bear', 1, 'Pillager outposts often keep an iron golem in a cage, and sometimes allays too.', 167, true, 'choice', null::jsonb, null::text[]),
  ('fortress-nether-wart-gardens', 'Which potion ingredient grows naturally in Nether fortress stair rooms?', 'Nether Wart', 'Sugar Cane', 'Crimson Fungus', 'Glow Berries', 0, 'Some fortress stair rooms have little gardens of nether wart on soul sand, the base of most potions.', 168, true, 'choice', null::jsonb, null::text[]),
  ('wither-skulls-from-fortresses', 'Wither skeleton skulls come from mobs that spawn in which structure?', 'Ancient City', 'Bastion Remnant', 'End City', 'Nether Fortress', 3, 'Wither skeletons spawn in Nether fortresses, and sometimes drop the skulls needed for the Wither.', 169, true, 'choice', null::jsonb, null::text[]),
  ('igloo-basement-golden-apple', 'Which food is always in the chest of an igloo basement?', 'Bread', 'Cookie', 'Golden Carrot', 'Golden Apple', 3, 'Igloo basement chests always have a golden apple, handy for curing the zombie villager kept there.', 170, true, 'choice', null::jsonb, null::text[]),
  ('sherds-craft-decorated-pots', 'Pottery sherds dug up with a brush are used to craft what?', 'Decorated Pot', 'Painting', 'Flower Pot', 'Banner', 0, 'Four sherds or bricks craft a decorated pot that shows the sherds'' pictures on its sides.', 171, true, 'choice', null::jsonb, null::text[]),
  ('echo-shards-recovery-compass', 'Echo shards from ancient cities are used to craft which item?', 'Recovery Compass', 'Lodestone', 'Clock', 'Spyglass', 0, 'Eight echo shards around a compass make a recovery compass, which points to where you last died.', 172, true, 'choice', null::jsonb, null::text[]),
  ('netherite-template-in-bastions', 'Where do players find the template needed to upgrade diamond gear to netherite?', 'Bastion Remnant', 'Ancient City', 'End City', 'Ruined Portal', 0, 'The netherite upgrade template comes from bastion remnants and is guaranteed in the treasure room.', 173, true, 'choice', null::jsonb, null::text[]),
  ('elder-guardian-drops-wet-sponge', 'Which block does an elder guardian drop when a player defeats it?', 'Wet Sponge', 'Magma Block', 'Ice', 'Sea Lantern', 0, 'Elder guardians drop a wet sponge, and monuments can also hide rooms full of sponges.', 174, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-gold-blocks', 'What valuable blocks are hidden in the center of an ocean monument?', 'Blocks of Gold', 'Blocks of Netherite', 'Blocks of Diamond', 'Blocks of Emerald', 0, 'Eight gold blocks are hidden inside dark prismarine in the monument''s treasure room.', 175, true, 'choice', null::jsonb, null::text[]),
  ('bastion-chest-angers-piglins', 'What happens if piglins see you open a chest in a bastion?', 'Nothing happens', 'They run away', 'They attack you', 'They start trading', 2, 'Piglins guard their loot: opening a chest in front of them makes them angry, even if you wear gold.', 176, true, 'choice', null::jsonb, null::text[]),
  ('pillager-captain-ominous-bottle', 'What does a pillager captain drop when defeated outside a raid?', 'Echo Shard', 'Trial Key', 'Ominous Bottle', 'Totem of Undying', 2, 'Pillager captains drop an ominous bottle; drinking it gives Bad Omen, which can start a raid.', 177, true, 'choice', null::jsonb, null::text[]),
  ('vault-opens-once-per-player', 'How many times can one player unlock the same vault?', '1', '3', '2', '5', 0, 'Each player can unlock a vault only once, but every friend can open it with their own key.', 178, true, 'choice', null::jsonb, null::text[]),
  ('evokers-drop-totems', 'Which life-saving item do evokers in woodland mansions drop?', 'Heart of the Sea', 'Golden Apple', 'Elytra', 'Totem of Undying', 3, 'Every evoker drops a totem of undying, and woodland mansions are where evokers live.', 179, true, 'choice', null::jsonb, null::text[]),
  ('outpost-chests-have-crossbows', 'Which ranged weapon can be found in pillager outpost chests?', 'Bow', 'Fire Charge', 'Trident', 'Crossbow', 3, 'Outpost chests often hold a crossbow, the same weapon the pillagers use.', 180, true, 'choice', null::jsonb, null::text[]),
  ('foxes-spawn-in-taiga', 'In which biome do foxes naturally spawn?', 'Desert', 'Taiga', 'Plains', 'Jungle', 1, 'Foxes live in spruce-filled taiga biomes, where they sleep during the day.', 181, true, 'choice', null::jsonb, null::text[]),
  ('stronghold-library-books', 'Which structure can hide a library full of bookshelves?', 'Desert Pyramid', 'Stronghold', 'Jungle Temple', 'Igloo', 1, 'Strongholds may have libraries with tall bookshelves and chests with enchanted books.', 182, true, 'choice', null::jsonb, null::text[]),
  ('ocean-ruins-drowned', 'Which crumbling underwater structure is often guarded by drowned?', 'Ocean Ruins', 'Ocean Monument', 'Trail Ruins', 'Shipwreck', 0, 'Ocean ruins are broken stone buildings on the sea floor where drowned often lurk.', 183, true, 'choice', null::jsonb, null::text[]),
  ('clay-block-drops-four-balls', 'How many clay balls drop when you break a clay block?', '6', '9', '4', '2', 2, 'Breaking a clay block without Silk Touch gives you 4 clay balls to smelt into bricks.', 184, true, 'choice', null::jsonb, null::text[]),
  ('copper-ore-drops-raw-copper', 'Which item drops when you mine copper ore with a stone pickaxe?', 'Raw Gold', 'Iron Nugget', 'Raw Copper', 'Copper Ingot', 2, 'Copper ore drops several pieces of raw copper, which you smelt into copper ingots.', 185, true, 'choice', null::jsonb, null::text[]),
  ('water-bottle-turns-dirt-into-mud', 'Pouring a water bottle on dirt turns it into which block?', 'Soul Soil', 'Mud', 'Coarse Dirt', 'Clay', 1, 'Using a water bottle on dirt makes mud and gives you back the empty bottle.', 186, true, 'choice', null::jsonb, null::text[]),
  ('packed-mud-needs-wheat', 'Which crop do you craft together with mud to get packed mud?', 'Sugar Cane', 'Kelp', 'Bamboo', 'Wheat', 3, 'Mud plus wheat crafts packed mud, which can then be turned into mud bricks.', 187, true, 'choice', null::jsonb, null::text[]),
  ('vines-make-mossy-cobblestone', 'Which of these plants, crafted with cobblestone, makes mossy cobblestone?', 'Vines', 'Leaves', 'Seagrass', 'Kelp', 0, 'Cobblestone plus vines (or a moss block) crafts mossy cobblestone.', 188, true, 'choice', null::jsonb, null::text[]),
  ('coarse-dirt-needs-gravel', 'Coarse dirt is crafted from dirt and which other block?', 'Sand', 'Gravel', 'Clay', 'Cobblestone', 1, 'Two dirt and two gravel craft four coarse dirt, a dirt block that grass can''t spread onto.', 189, true, 'choice', null::jsonb, null::text[]),
  ('diorite-salt-and-pepper-stone', 'Which stone looks white with black specks, like salt and pepper?', 'Andesite', 'Tuff', 'Diorite', 'Granite', 2, 'Diorite is a pale stone with a salt-and-pepper look that you often find in big patches underground.', 190, true, 'choice', null::jsonb, null::text[]),
  ('two-sources-make-infinite-water', 'What is the fewest water sources you need to make an infinite water pool?', '3', '4', '1', '2', 3, 'Two water sources next to a gap make a new source there, so you can refill buckets forever.', 191, true, 'choice', null::jsonb, null::text[]),
  ('sword-cuts-cobweb-into-string', 'Breaking a cobweb with a sword drops which item?', 'Slimeball', 'Feather', 'Paper', 'String', 3, 'A sword cuts a cobweb into one string, while shears let you collect the cobweb itself.', 192, true, 'choice', null::jsonb, null::text[]),
  ('netherrack-fire-burns-forever', 'Fire lit on top of which block never goes out by itself?', 'Wool', 'Netherrack', 'Hay Bale', 'Oak Planks', 1, 'Netherrack keeps a fire burning forever, which makes it great for fireplaces.', 193, true, 'choice', null::jsonb, null::text[]),
  ('soul-sand-makes-blue-fire', 'Fire turns blue when it burns on top of which block?', 'Basalt', 'Netherrack', 'Soul Sand', 'Magma Block', 2, 'Lighting soul sand or soul soil makes blue soul fire instead of the usual orange fire.', 194, true, 'choice', null::jsonb, null::text[]),
  ('shovel-makes-dirt-path', 'Using a shovel on a grass block turns it into which block?', 'Dirt', 'Coarse Dirt', 'Farmland', 'Dirt Path', 3, 'A shovel flattens grass into a dirt path, a block slightly lower than a full block.', 195, true, 'choice', null::jsonb, null::text[]),
  ('bookshelf-drops-three-books', 'How many books drop when you break a bookshelf without Silk Touch?', '3', '1', '9', '6', 0, 'A bookshelf drops 3 books, exactly enough to craft it again with six planks.', 196, true, 'choice', null::jsonb, null::text[]),
  ('broken-ice-leaves-water', 'Break ice without Silk Touch while a block is under it. What appears in its place?', 'Packed Ice', 'Water', 'Snow Block', 'Snowball', 1, 'Ice turns into a water source block when broken over another block, unless you use Silk Touch.', 197, true, 'choice', null::jsonb, null::text[]),
  ('banner-needs-six-wool', 'How many wool blocks does it take to craft a banner?', '8', '6', '4', '3', 1, 'A banner takes six wool of one color plus a stick.', 198, true, 'choice', null::jsonb, null::text[]),
  ('barrel-opens-under-a-block', 'Which storage block still opens with a solid block right on top of it?', 'Shulker Box', 'Barrel', 'Trapped Chest', 'Chest', 1, 'Unlike a chest, a barrel opens even with a block above it, and it holds as much as a chest.', 199, true, 'choice', null::jsonb, null::text[]),
  ('single-chest-has-27-slots', 'How many item slots does a single chest have?', '27', '18', '36', '9', 0, 'A single chest has 27 slots in three rows of nine, and a large chest has twice as many.', 200, true, 'choice', null::jsonb, null::text[]),
  ('two-wool-make-three-carpets', 'How many carpets do you get from crafting two wool?', '3', '2', '4', '1', 0, 'Two wool of the same color side by side craft three carpets.', 201, true, 'choice', null::jsonb, null::text[]),
  ('seven-sticks-make-three-ladders', 'How many ladders does one craft with seven sticks make?', '7', '1', '3', '4', 2, 'Seven sticks laid out in an H shape craft 3 ladders.', 202, true, 'choice', null::jsonb, null::text[]),
  ('six-blocks-make-four-stairs', 'Six planks in a staircase shape craft how many stairs?', '3', '6', '4', '2', 2, 'Six blocks laid out like steps give 4 stairs of the same material.', 203, true, 'choice', null::jsonb, null::text[]),
  ('item-frame-needs-leather', 'Which item goes in the middle of eight sticks to craft an item frame?', 'String', 'Leather', 'Paper', 'Wool', 1, 'An item frame is crafted from one leather surrounded by eight sticks.', 204, true, 'choice', null::jsonb, null::text[]),
  ('painting-needs-wool', 'Eight sticks around which block craft a painting?', 'Oak Planks', 'Leather', 'Wool', 'Paper', 2, 'A painting is crafted from eight sticks around wool of any color.', 205, true, 'choice', null::jsonb, null::text[]),
  ('sea-lantern-from-prismarine', 'Which bright block is crafted from prismarine shards and crystals?', 'Glowstone', 'Redstone Lamp', 'Sea Lantern', 'Prismarine', 2, 'Four prismarine shards and five crystals craft a sea lantern, which gives light level 15.', 206, true, 'choice', null::jsonb, null::text[]),
  ('concrete-powder-needs-dye', 'Besides sand and gravel, what goes into concrete powder?', 'Flint', 'Dye', 'Clay Ball', 'String', 1, 'Four sand, four gravel and one dye craft eight concrete powder in that dye''s color.', 207, true, 'choice', null::jsonb, null::text[]),
  ('sign-has-two-writable-sides', 'On how many sides of a sign can you write text?', '2', '3', '4', '1', 0, 'Signs have a front and a back, and you can write different text on each side.', 208, true, 'choice', null::jsonb, null::text[]),
  ('sandstone-under-desert-sand', 'Which block usually lies under the sand in a desert?', 'Terracotta', 'Gravel', 'Clay', 'Sandstone', 3, 'Desert sand is only a few blocks deep, with sandstone underneath holding it up.', 209, true, 'choice', null::jsonb, null::text[]),
  ('bone-meal-spreads-moss', 'Using bone meal on which block spreads it onto nearby stone and dirt?', 'Moss Block', 'Mycelium', 'Podzol', 'Grass Block', 0, 'Bone meal on a moss block turns nearby stone and dirt into moss and grows plants.', 210, true, 'choice', null::jsonb, null::text[]),
  ('cactus-destroys-items', 'Which plant destroys any dropped items that touch it?', 'Sweet Berry Bush', 'Cactus', 'Sugar Cane', 'Bamboo', 1, 'A cactus destroys items that bump into it, so keep it away from your item farms.', 211, true, 'choice', null::jsonb, null::text[]),
  ('iron-bars-see-through-metal', 'Which see-through metal block do you craft from six iron ingots?', 'Iron Trapdoor', 'Glass Pane', 'Iron Bars', 'Chain', 2, 'Six iron ingots in two rows make 16 iron bars, great for windows and cages.', 212, true, 'choice', null::jsonb, null::text[]),
  ('lantern-torch-in-iron-nuggets', 'What goes in the middle of eight iron nuggets to make a lantern?', 'Coal', 'Torch', 'Redstone Torch', 'Glowstone Dust', 1, 'A torch surrounded by eight iron nuggets crafts a lantern, a light you can hang up or set on a block.', 213, true, 'choice', null::jsonb, null::text[]),
  ('jukebox-needs-a-diamond', 'Which gem sits in the center of a jukebox recipe, surrounded by planks?', 'Diamond', 'Amethyst Shard', 'Emerald', 'Lapis Lazuli', 0, 'A jukebox is eight planks around one diamond, so playing music discs costs a rare gem.', 214, true, 'choice', null::jsonb, null::text[]),
  ('note-block-redstone-center', 'Eight planks around which item craft a note block?', 'Gunpowder', 'Iron Nugget', 'Redstone Dust', 'Glowstone Dust', 2, 'A note block is eight planks around one redstone dust, and it plays a sound when powered or hit.', 215, true, 'choice', null::jsonb, null::text[]),
  ('four-string-craft-wool', 'How many pieces of string turn into one block of wool?', '4', '2', '9', '3', 0, 'Four string in a 2×2 square craft one white wool, handy when there are no sheep nearby.', 216, true, 'choice', null::jsonb, null::text[]),
  ('three-blocks-craft-six-slabs', 'Three blocks in a row craft how many slabs?', '9', '6', '3', '4', 1, 'A row of three blocks crafts 6 slabs, each half the height of a full block.', 217, true, 'choice', null::jsonb, null::text[]),
  ('one-craft-makes-four-arrows', 'Flint, a stick and a feather together craft how many arrows?', '2', '1', '8', '4', 3, 'Flint on top, a stick in the middle and a feather below craft 4 arrows at once.', 218, true, 'choice', null::jsonb, null::text[]),
  ('lectern-needs-bookshelf', 'A lectern is crafted from wooden slabs and which block?', 'Barrel', 'Crafting Table', 'Bookshelf', 'Chest', 2, 'Wooden slabs and a bookshelf craft a lectern, which holds a book open for everyone to read.', 219, true, 'choice', null::jsonb, null::text[]),
  ('barrel-planks-and-slabs', 'Which storage block is crafted from six planks and two wooden slabs?', 'Chest', 'Barrel', 'Composter', 'Lectern', 1, 'Six planks and two wooden slabs craft a barrel, which has 27 slots just like a chest.', 220, true, 'choice', null::jsonb, null::text[]),
  ('golden-pickaxe-breaks-first', 'Which pickaxe wears out and breaks the quickest?', 'Iron Pickaxe', 'Stone Pickaxe', 'Golden Pickaxe', 'Wooden Pickaxe', 2, 'Golden tools have the lowest durability of all, even lower than wooden ones.', 221, true, 'choice', null::jsonb, null::text[]),
  ('campfire-cooks-four-items', 'How many pieces of food can a campfire cook at the same time?', '1', '8', '2', '4', 3, 'A campfire has room for 4 food items at once and cooks them without any fuel.', 222, true, 'choice', null::jsonb, null::text[]),
  ('hoe-breaks-hay-and-sponges', 'Which tool breaks hay bales and sponges the fastest?', 'Shovel', 'Hoe', 'Axe', 'Pickaxe', 1, 'Hoes are the right tool for soft plant-like blocks such as hay bales, sponges, leaves and moss.', 223, true, 'choice', null::jsonb, null::text[]),
  ('smelting-iron-sword-gives-nugget', 'What comes out when you smelt a worn-out iron sword?', 'Raw Iron', 'Iron Ingot', 'Iron Nugget', 'Stick', 2, 'Smelting iron tools, weapons or armor gives back one iron nugget, a small way to recycle old gear.', 224, true, 'choice', null::jsonb, null::text[]),
  ('axe-scrapes-copper-blocks', 'Which tool scrapes wax and green rust off copper blocks?', 'Hoe', 'Shovel', 'Shears', 'Axe', 3, 'Using an axe on copper scrapes off wax or one stage of oxidation, making it shinier again.', 225, true, 'choice', null::jsonb, null::text[]),
  ('nine-iron-nuggets-one-ingot', 'How many iron nuggets do you need for one iron ingot?', '4', '3', '8', '9', 3, 'Nine iron nuggets craft one iron ingot, and one ingot can be split back into nine nuggets.', 226, true, 'choice', null::jsonb, null::text[]),
  ('three-copper-craft-lightning-rod', 'Three copper ingots stacked in a column craft which item?', 'Shears', 'Spyglass', 'Bucket', 'Lightning Rod', 3, 'Three copper ingots in a line make a lightning rod, which draws lightning away from your house.', 227, true, 'choice', null::jsonb, null::text[]),
  ('spyglass-amethyst-and-copper', 'An amethyst shard on top of two copper ingots crafts what?', 'Lightning Rod', 'Spyglass', 'Clock', 'Compass', 1, 'The spyglass uses an amethyst shard as its lens and copper for the tube, letting you zoom in on faraway things.', 228, true, 'choice', null::jsonb, null::text[]),
  ('flint-and-steel-needs-iron-ingot', 'Besides flint, what do you need to craft flint and steel?', 'Iron Ingot', 'Stick', 'Copper Ingot', 'Coal', 0, 'One iron ingot and one flint craft flint and steel, used to light fires and Nether portals.', 229, true, 'choice', null::jsonb, null::text[]),
  ('shovel-needs-one-material', 'Which tool needs just one ingot, gem or block of its material?', 'Hoe', 'Pickaxe', 'Shovel', 'Axe', 2, 'A shovel is one piece of material on two sticks, the least material of any tool.', 230, true, 'choice', null::jsonb, null::text[]),
  ('iron-chestplate-eight-ingots', 'How many iron ingots does an iron chestplate cost?', '7', '5', '6', '8', 3, 'The chestplate is the most expensive armor piece, taking 8 iron ingots.', 231, true, 'choice', null::jsonb, null::text[]),
  ('hoe-two-material-two-sticks', 'Two pieces of material and two sticks craft which tool?', 'Axe', 'Hoe', 'Shovel', 'Sword', 1, 'A hoe takes 2 material and 2 sticks, while a sword uses 2 material and only 1 stick.', 232, true, 'choice', null::jsonb, null::text[]),
  ('gold-ore-needs-iron-pickaxe', 'Which of these ores needs at least an iron pickaxe?', 'Coal Ore', 'Iron Ore', 'Gold Ore', 'Copper Ore', 2, 'Gold ore drops nothing unless you use an iron, diamond or netherite pickaxe.', 233, true, 'choice', null::jsonb, null::text[]),
  ('brush-needs-copper-ingot', 'A brush is crafted from a feather, a stick and which ingot?', 'Iron Ingot', 'Gold Ingot', 'Netherite Ingot', 'Copper Ingot', 3, 'The brush, added in 1.20 for archaeology, is a feather, a copper ingot and a stick in a column.', 234, true, 'choice', null::jsonb, null::text[]),
  ('netherite-scrap-plus-gold-ingots', 'Netherite scrap is combined with which ingot to make a netherite ingot?', 'Gold Ingot', 'Copper Ingot', 'Diamond', 'Iron Ingot', 0, 'Four netherite scrap and four gold ingots craft one netherite ingot.', 235, true, 'choice', null::jsonb, null::text[]),
  ('netherrack-smelts-nether-brick', 'Smelting netherrack in a furnace gives you which item?', 'Blackstone', 'Nether Brick', 'Brick', 'Magma Cream', 1, 'Netherrack smelts into a nether brick, which you can craft into Nether brick blocks.', 236, true, 'choice', null::jsonb, null::text[]),
  ('sandstone-smelts-smooth', 'Smelting a block of sandstone gives you which block?', 'Cut Sandstone', 'Sand', 'Glass', 'Smooth Sandstone', 3, 'Sandstone smelts into smooth sandstone, a clean block with no pattern.', 237, true, 'choice', null::jsonb, null::text[]),
  ('cobbled-deepslate-stone-tools', 'Besides cobblestone, which block can you use to craft stone tools?', 'Smooth Stone', 'Andesite', 'Cobbled Deepslate', 'Stone', 2, 'Cobbled deepslate works just like cobblestone in stone tool recipes.', 238, true, 'choice', null::jsonb, null::text[]),
  ('minecart-five-iron', 'Five iron ingots in a U shape craft which item?', 'Bucket', 'Cauldron', 'Minecart', 'Iron Door', 2, 'Five iron ingots shaped like a cup make a minecart for riding on rails.', 239, true, 'choice', null::jsonb, null::text[]),
  ('bookshelf-planks-and-books', 'Six planks and three books craft which block?', 'Enchanting Table', 'Chiseled Bookshelf', 'Lectern', 'Bookshelf', 3, 'Six planks and three books make a bookshelf, which boosts an enchanting table.', 240, true, 'choice', null::jsonb, null::text[]),
  ('two-planks-pressure-plate', 'Two planks placed side by side craft which block?', 'Slab', 'Trapdoor', 'Button', 'Pressure Plate', 3, 'Two planks next to each other make a wooden pressure plate that sends a signal when stepped on.', 241, true, 'choice', null::jsonb, null::text[]),
  ('glow-berries-on-cave-vines', 'Glow berries grow on which hanging plant?', 'Cave Vines', 'Vines', 'Twisting Vines', 'Weeping Vines', 0, 'Glow berries grow on cave vines that hang from cave ceilings, and vines with berries glow.', 242, true, 'choice', null::jsonb, null::text[]),
  ('bone-meal-huge-mushroom', 'What can bone meal turn a small mushroom into?', 'Huge Mushroom', 'Mooshroom', 'Mycelium', 'Crimson Fungus', 0, 'Bone meal can grow a mushroom into a huge mushroom if there is enough space above it.', 243, true, 'choice', null::jsonb, null::text[]),
  ('sweet-berries-picked-without-breaking', 'Which plant can you pick from again and again without breaking it?', 'Wheat', 'Sweet Berry Bush', 'Carrots', 'Beetroots', 1, 'Using a ripe sweet berry bush drops berries and leaves the bush in place to grow more.', 244, true, 'choice', null::jsonb, null::text[]),
  ('zombie-drops-carrot-potato', 'Which hostile mob can rarely drop a carrot or a potato?', 'Skeleton', 'Phantom', 'Creeper', 'Zombie', 3, 'Zombies have a small chance to drop a carrot, a potato or an iron ingot, a handy way to start a farm.', 245, true, 'choice', null::jsonb, null::text[]),
  ('pumpkin-crafts-four-seeds', 'How many seeds do you get by crafting one pumpkin?', '2', '4', '9', '1', 1, 'Putting one pumpkin in a crafting grid gives you 4 pumpkin seeds.', 246, true, 'choice', null::jsonb, null::text[]),
  ('bamboo-planted-on-grass', 'Which of these can you plant straight onto a grass block, no hoe needed?', 'Beetroot Seeds', 'Carrot', 'Bamboo', 'Wheat Seeds', 2, 'Bamboo grows on grass, dirt or sand, but seeds and carrots need farmland made with a hoe.', 247, true, 'choice', null::jsonb, null::text[]),
  ('sweet-berries-grow-in-taiga', 'In which biome do sweet berry bushes grow naturally?', 'Jungle', 'Taiga', 'Desert', 'Savanna', 1, 'Sweet berry bushes grow wild in taiga and snowy taiga biomes, among the spruce trees.', 248, true, 'choice', null::jsonb, null::text[]),
  ('rabbits-eat-carrot-crops', 'Which animal sneaks into farms to nibble on growing carrots?', 'Pig', 'Rabbit', 'Sheep', 'Fox', 1, 'Rabbits can eat carrots growing on farmland, so put a fence around your carrot farm.', 249, true, 'choice', null::jsonb, null::text[]),
  ('tamed-wolves-breed-with-meat', 'Two tamed wolves will breed after eating which food?', 'Raw Beef', 'Wheat', 'Carrot', 'Bone', 0, 'Tamed wolves breed when fed meat like raw beef; bones are only for taming them.', 250, true, 'choice', null::jsonb, null::text[]),
  ('horse-tamed-by-riding', 'How do you tame a wild horse?', 'Put a lead on it', 'Feed it bones', 'Give it a saddle', 'Keep riding it', 3, 'Climb on a wild horse again and again; after a few bucks it calms down and hearts appear.', 251, true, 'choice', null::jsonb, null::text[]),
  ('horse-and-donkey-make-mule', 'Breeding a horse with a donkey gives you which baby?', 'Llama', 'Camel', 'Mule', 'Goat', 2, 'A horse and a donkey have a mule, which can carry a chest but can''t have babies of its own.', 252, true, 'choice', null::jsonb, null::text[]),
  ('llamas-breed-with-hay', 'Tamed llamas breed when you give them what?', 'Carrot', 'Apple', 'Hay Bale', 'Wheat', 2, 'Llamas breed with hay bales; wheat only heals them and helps babies grow.', 253, true, 'choice', null::jsonb, null::text[]),
  ('bees-breed-with-flowers', 'What do you feed bees to breed them?', 'Honeycomb', 'Flower', 'Sugar', 'Sweet Berries', 1, 'Bees breed when you feed them any flower, the same plants they collect nectar from.', 254, true, 'choice', null::jsonb, null::text[]),
  ('turtles-lay-eggs-on-sand', 'On which block does a turtle lay its eggs?', 'Grass Block', 'Clay', 'Sand', 'Gravel', 2, 'Turtles swim back to their home beach and lay their eggs on sand, where they can hatch.', 255, true, 'choice', null::jsonb, null::text[]),
  ('frogs-lay-frogspawn', 'What do frogs lay on top of water?', 'Lily Pad', 'Turtle Egg', 'Sniffer Egg', 'Frogspawn', 3, 'Frogs lay frogspawn on water, and it hatches into tadpoles a few minutes later.', 256, true, 'choice', null::jsonb, null::text[]),
  ('water-bucket-scoops-axolotl', 'What do you use to scoop up an axolotl and carry it?', 'Glass Bottle', 'Water Bucket', 'Bowl', 'Lead', 1, 'Use a water bucket on an axolotl to carry it around in the bucket, just like a fish.', 257, true, 'choice', null::jsonb, null::text[]),
  ('polar-bears-cannot-breed', 'Which of these animals can''t be bred?', 'Fox', 'Polar Bear', 'Llama', 'Panda', 1, 'Polar bears can''t breed, so polar bear cubs only appear when they spawn naturally.', 258, true, 'choice', null::jsonb, null::text[]),
  ('parrots-dance-to-jukebox', 'Which pet starts dancing when a jukebox plays nearby?', 'Parrot', 'Cat', 'Fox', 'Wolf', 0, 'Parrots dance when a jukebox plays music close to them.', 259, true, 'choice', null::jsonb, null::text[]),
  ('beehive-from-planks-honeycomb', 'Which block is crafted from planks and honeycomb?', 'Barrel', 'Bee Nest', 'Beehive', 'Chest', 2, 'Six planks and three honeycomb craft a beehive, a home for your bees.', 260, true, 'choice', null::jsonb, null::text[]),
  ('honey-block-from-bottles', 'Four honey bottles in a crafting grid make what?', 'Hay Bale', 'Honey Block', 'Slime Block', 'Honeycomb Block', 1, 'Four honey bottles craft a sticky honey block, and the empty bottles stay in the grid.', 261, true, 'choice', null::jsonb, null::text[]),
  ('hopper-collects-farm-drops', 'Which block sucks up dropped items and moves them into a chest?', 'Dropper', 'Dispenser', 'Hopper', 'Observer', 2, 'Hoppers collect items that fall on them and pass them into a chest, perfect for farms.', 262, true, 'choice', null::jsonb, null::text[]),
  ('beetroot-crafts-red-dye', 'What dye can you craft from a beetroot?', 'Pink Dye', 'Red Dye', 'Purple Dye', 'Orange Dye', 1, 'One beetroot crafts into red dye, just like a poppy or a red tulip.', 263, true, 'choice', null::jsonb, null::text[]),
  ('one-bone-three-bone-meal', 'How much bone meal does one bone craft into?', '3', '4', '1', '2', 0, 'One bone crafts into 3 bone meal for speeding up your crops.', 264, true, 'choice', null::jsonb, null::text[]),
  ('rabbit-hide-crafts-leather', 'What can you craft from four rabbit hides?', 'White Wool', 'Paper', 'Leather', 'String', 2, 'Four rabbit hides craft into one leather, a way to get leather without cows.', 265, true, 'choice', null::jsonb, null::text[]),
  ('candle-on-cake', 'What can you place on top of a whole cake?', 'Flower Pot', 'Torch', 'Candle', 'Lantern', 2, 'Use a candle on an uneaten cake to make a cake with a candle, then light it up.', 266, true, 'choice', null::jsonb, null::text[]),
  ('hoglin-drops-porkchop', 'Which Nether mob drops raw porkchop?', 'Strider', 'Ghast', 'Piglin', 'Hoglin', 3, 'Hoglins drop raw porkchop and sometimes leather, a good food source in the Nether.', 267, true, 'choice', null::jsonb, null::text[]),
  ('pigs-breed-with-potatoes', 'Besides carrots, which crop can you feed pigs to breed them?', 'Melon Slice', 'Wheat', 'Sweet Berries', 'Potato', 3, 'Pigs breed with carrots, potatoes or beetroots, but not wheat.', 268, true, 'choice', null::jsonb, null::text[]),
  ('goats-breed-with-wheat', 'Which crop do you feed goats to breed them?', 'Bamboo', 'Seagrass', 'Wheat', 'Carrot', 2, 'Goats breed with wheat, just like cows and sheep.', 269, true, 'choice', null::jsonb, null::text[]),
  ('four-honeycomb-block', 'Four honeycombs in a square craft which block?', 'Honeycomb Block', 'Bee Nest', 'Beehive', 'Honey Block', 0, 'Four honeycombs make a honeycomb block; a honey block needs honey bottles instead.', 270, true, 'choice', null::jsonb, null::text[]),
  ('eggs-stack-to-sixteen', 'How many eggs fit in one stack?', '32', '16', '64', '8', 1, 'Eggs only stack to 16, so empty your chicken farm often.', 271, true, 'choice', null::jsonb, null::text[]),
  ('axolotl-helps-fight-underwater', 'Which small water mob helps you fight drowned and guardians?', 'Glow Squid', 'Axolotl', 'Turtle', 'Dolphin', 1, 'Axolotls attack drowned, guardians and other water mobs, and can give you Regeneration after the fight.', 272, true, 'choice', null::jsonb, null::text[]),
  ('dolphin-leads-to-shipwreck', 'Which sea mob leads you to a shipwreck after you feed it raw fish?', 'Dolphin', 'Squid', 'Axolotl', 'Turtle', 0, 'Feed a dolphin raw cod or salmon and it swims toward the nearest shipwreck or ocean ruin.', 273, true, 'choice', null::jsonb, null::text[]),
  ('mooshroom-shears-into-cow', 'Which animal turns into a regular cow when you shear it?', 'Llama', 'Goat', 'Sheep', 'Mooshroom', 3, 'Shearing a mooshroom drops five mushrooms and turns it into a normal cow for good.', 274, true, 'choice', null::jsonb, null::text[]),
  ('fox-carries-items-in-mouth', 'Which forest animal picks up items and carries them in its mouth?', 'Fox', 'Rabbit', 'Cat', 'Wolf', 0, 'A fox walks to items lying on the ground and picks them up, holding them in its mouth.', 275, true, 'choice', null::jsonb, null::text[]),
  ('turtle-returns-home-beach', 'Which mob swims back to the beach where it was born to lay eggs?', 'Turtle', 'Axolotl', 'Frog', 'Dolphin', 0, 'After breeding, a turtle always heads back to its home beach to lay its eggs in the sand.', 276, true, 'choice', null::jsonb, null::text[]),
  ('strider-shivers-out-of-lava', 'Which Nether mob shivers and turns purple when it leaves the lava?', 'Hoglin', 'Strider', 'Piglin', 'Magma Cube', 1, 'Striders love warm lava; on land they turn a dull purple, shiver and move slowly.', 277, true, 'choice', null::jsonb, null::text[]),
  ('armadillo-rolls-into-ball', 'Which mob rolls up into a ball when it gets scared?', 'Armadillo', 'Turtle', 'Rabbit', 'Camel', 0, 'Armadillos hide in their shell when hurt or when undead mobs or running players come close.', 278, true, 'choice', null::jsonb, null::text[]),
  ('camel-carries-two-riders', 'Which desert mob can carry two players on its back at once?', 'Horse', 'Donkey', 'Camel', 'Llama', 2, 'Up to two players can ride one saddled camel, and camels can be found in desert villages.', 279, true, 'choice', null::jsonb, null::text[]),
  ('husk-ignores-sunlight', 'Which desert zombie doesn''t burn in sunlight?', 'Husk', 'Drowned', 'Stray', 'Zombie', 0, 'Husks spawn in deserts and, unlike normal zombies, can keep hunting you all day.', 280, true, 'choice', null::jsonb, null::text[]),
  ('vindicator-swings-iron-axe', 'Which illager charges at you swinging an iron axe?', 'Vindicator', 'Witch', 'Pillager', 'Evoker', 0, 'Vindicators live in woodland mansions and join raids, attacking up close with an iron axe.', 281, true, 'choice', null::jsonb, null::text[]),
  ('ravager-rams-in-raids', 'Which huge beast rams players with its head during village raids?', 'Hoglin', 'Iron Golem', 'Polar Bear', 'Ravager', 3, 'Ravagers appear in raids, ram their targets with their heads and can smash through leaves.', 282, true, 'choice', null::jsonb, null::text[]),
  ('silverfish-hide-in-stone', 'Which tiny mob hides inside stone blocks and pops out when you break them?', 'Cave Spider', 'Vex', 'Silverfish', 'Endermite', 2, 'Silverfish hide in infested blocks in strongholds and mountains and crawl out when the block breaks.', 283, true, 'choice', null::jsonb, null::text[]),
  ('piglins-calm-with-gold-armor', 'Which Nether mob leaves you alone if you wear a piece of gold armor?', 'Magma Cube', 'Hoglin', 'Piglin', 'Blaze', 2, 'Piglins attack players on sight unless they wear at least one piece of golden armor.', 284, true, 'choice', null::jsonb, null::text[]),
  ('ghast-tear-regeneration', 'Which mob drops tears used to brew a Potion of Regeneration?', 'Blaze', 'Witch', 'Phantom', 'Ghast', 3, 'Ghasts can drop ghast tears, which turn an awkward potion into a Potion of Regeneration.', 285, true, 'choice', null::jsonb, null::text[]),
  ('breeze-rod-crafts-mace', 'Which trial chamber mob drops the rod needed to craft a mace?', 'Bogged', 'Breeze', 'Wither Skeleton', 'Blaze', 1, 'Breezes drop breeze rods, and a breeze rod plus a heavy core crafts a mace.', 286, true, 'choice', null::jsonb, null::text[]),
  ('guardian-spikes-hurt-attackers', 'Which ocean mob''s spikes hurt you when you hit it up close?', 'Drowned', 'Squid', 'Dolphin', 'Guardian', 3, 'When a guardian''s spikes stick out, hitting it with a melee attack damages you back, like Thorns.', 287, true, 'choice', null::jsonb, null::text[]),
  ('axe-disables-shield', 'Which weapon can knock a shield out of use for a few seconds?', 'Axe', 'Trident', 'Bow', 'Sword', 0, 'Hitting a raised shield with an axe disables it for a few seconds, so the defender can''t block.', 288, true, 'choice', null::jsonb, null::text[]),
  ('trident-throw-and-melee', 'Which weapon can be thrown at mobs and also used up close?', 'Bow', 'Mace', 'Trident', 'Crossbow', 2, 'A trident works as a melee weapon and can be thrown, and drowned are the main way to get one.', 289, true, 'choice', null::jsonb, null::text[]),
  ('iron-chestplate-most-armor', 'Which piece of iron armor gives the most protection?', 'Leggings', 'Helmet', 'Boots', 'Chestplate', 3, 'An iron chestplate gives 6 armor points, more than the iron helmet, leggings or boots.', 290, true, 'choice', null::jsonb, null::text[]),
  ('turtle-shell-water-breathing', 'Which helmet lets you hold your breath longer underwater without enchantments?', 'Leather Cap', 'Turtle Shell', 'Iron Helmet', 'Diamond Helmet', 1, 'A turtle shell gives Water Breathing for 10 seconds each time you dive, so you can stay down longer.', 291, true, 'choice', null::jsonb, null::text[]),
  ('slow-falling-no-fall-damage', 'Which potion lets you float down gently with no fall damage?', 'Potion of Invisibility', 'Potion of Slow Falling', 'Potion of Swiftness', 'Potion of Leaping', 1, 'With Slow Falling you drift down like a feather and take no fall damage at all.', 292, true, 'choice', null::jsonb, null::text[]),
  ('wolf-armor-from-armadillo-scutes', 'Which mob''s scutes do you need to craft armor for your wolf?', 'Goat', 'Sniffer', 'Turtle', 'Armadillo', 3, 'Six armadillo scutes craft wolf armor, which protects your tamed wolf in fights.', 293, true, 'choice', null::jsonb, null::text[]),
  ('power-boosts-arrow-damage', 'Which bow enchantment makes your arrows hit harder?', 'Power', 'Infinity', 'Flame', 'Punch', 0, 'Power raises the damage of every arrow you shoot from that bow.', 294, true, 'choice', null::jsonb, null::text[]),
  ('regeneration-potion-heals-over-time', 'Which potion heals you slowly over time instead of all at once?', 'Potion of Night Vision', 'Potion of Healing', 'Potion of Regeneration', 'Potion of Swiftness', 2, 'A Potion of Regeneration restores health bit by bit, while a Potion of Healing works instantly.', 295, true, 'choice', null::jsonb, null::text[]),
  ('netherite-armor-lava-proof', 'Which armor won''t burn up if you drop it into lava?', 'Netherite Armor', 'Golden Armor', 'Iron Armor', 'Diamond Armor', 0, 'Netherite gear is fireproof as an item, so it survives lava that would destroy other armor.', 296, true, 'choice', null::jsonb, null::text[]),
  ('skeletons-flee-wolves', 'Which hostile mob runs away from wolves?', 'Creeper', 'Zombie', 'Witch', 'Skeleton', 3, 'Skeletons are scared of wolves and run from them, while wolves happily chase them.', 297, true, 'choice', null::jsonb, null::text[]),
  ('potion-of-invisibility-hides-you', 'Drinking which potion makes your body disappear from view?', 'Potion of Slow Falling', 'Potion of Swiftness', 'Potion of Invisibility', 'Potion of Night Vision', 2, 'A Potion of Invisibility hides your body, though any armor you wear can still be seen.', 298, true, 'choice', null::jsonb, null::text[]),
  ('dolphin-speed-boost', 'Sprint-swimming next to which ocean mob gives you a big speed boost?', 'Guardian', 'Turtle', 'Glow Squid', 'Dolphin', 3, 'Swim fast next to dolphins and they boost your speed so you zoom through the water.', 299, true, 'choice', null::jsonb, null::text[]),
  ('llama-carries-chest', 'Besides donkeys and mules, which mob can carry a chest on its back?', 'Camel', 'Llama', 'Horse', 'Pig', 1, 'A tamed llama can wear a chest, so a llama caravan can haul lots of items.', 300, true, 'choice', null::jsonb, null::text[]),
  ('skeleton-becomes-stray', 'A skeleton stuck in powder snow for a while turns into which mob?', 'Bogged', 'Husk', 'Wither Skeleton', 'Stray', 3, 'A skeleton that stays in powder snow starts shaking and then turns into a stray.', 301, true, 'choice', null::jsonb, null::text[]),
  ('magma-cream-brews-fire-resistance', 'Which item turns an awkward potion into Fire Resistance?', 'Magma Cream', 'Sugar', 'Blaze Powder', 'Ghast Tear', 0, 'Magma cream, dropped by magma cubes, is brewed into a Potion of Fire Resistance.', 302, true, 'choice', null::jsonb, null::text[]),
  ('fire-charge-lights-portal', 'Besides flint and steel, what can light a Nether portal?', 'Glowstone Dust', 'Fire Charge', 'Torch', 'Blaze Rod', 1, 'A fire charge places fire just like flint and steel, so it can light an obsidian frame.', 303, true, 'choice', null::jsonb, null::text[]),
  ('nether-fossils-in-soul-sand-valley', 'In which Nether biome can you find giant bone fossils?', 'Basalt Deltas', 'Warped Forest', 'Nether Wastes', 'Soul Sand Valley', 3, 'Nether fossils made of bone blocks generate only in soul sand valleys.', 304, true, 'choice', null::jsonb, null::text[]),
  ('ancient-debris-needs-diamond-pickaxe', 'Which pickaxe is the weakest one that can mine ancient debris?', 'Iron Pickaxe', 'Stone Pickaxe', 'Diamond Pickaxe', 'Wooden Pickaxe', 2, 'Ancient debris needs a diamond or netherite pickaxe; weaker tools break it but drop nothing.', 305, true, 'choice', null::jsonb, null::text[]),
  ('twisting-vines-grow-upward', 'Which vines grow upward from the floor of the warped forest?', 'Cave Vines', 'Vines', 'Twisting Vines', 'Weeping Vines', 2, 'Twisting vines grow up from the ground, while weeping vines hang down from above.', 306, true, 'choice', null::jsonb, null::text[]),
  ('blackstone-replaces-cobblestone', 'Which Nether block can replace cobblestone in a furnace recipe?', 'Blackstone', 'Netherrack', 'Basalt', 'Soul Soil', 0, 'Blackstone works like cobblestone, so you can craft furnaces and stone tools in the Nether.', 307, true, 'choice', null::jsonb, null::text[]),
  ('nether-wart-makes-awkward-potion', 'Which Nether plant turns water bottles into awkward potions?', 'Crimson Fungus', 'Nether Wart', 'Crimson Roots', 'Warped Fungus', 1, 'Nether wart is the first step of most potions: it turns water bottles into awkward potions.', 308, true, 'choice', null::jsonb, null::text[]),
  ('ender-chest-shares-items', 'Which chest shows the same items wherever you place it?', 'Barrel', 'Trapped Chest', 'Shulker Box', 'Ender Chest', 3, 'All your ender chests share one inventory, even in other dimensions, and other players can''t see it.', 309, true, 'choice', null::jsonb, null::text[]),
  ('firework-rocket-boosts-elytra', 'What can you use to speed up while flying with elytra?', 'Fire Charge', 'Ender Pearl', 'Firework Rocket', 'Snowball', 2, 'Using a firework rocket while gliding pushes you forward fast in the direction you face.', 310, true, 'choice', null::jsonb, null::text[]),
  ('iron-bars-cage-end-crystals', 'What protects some end crystals from your arrows?', 'Chain', 'Glass', 'Obsidian', 'Iron Bars', 3, 'Two end crystals sit inside iron bar cages, so you have to climb up and break in.', 311, true, 'choice', null::jsonb, null::text[]),
  ('end-gateway-spawns-after-dragon', 'Which small portal appears near the edge of the main End island after each dragon fight?', 'Ruined Portal', 'Nether Portal', 'End Gateway', 'End Portal', 2, 'Every dragon defeat creates an end gateway that can fling you out to the outer islands.', 312, true, 'choice', null::jsonb, null::text[]),
  ('end-ship-floats-near-city', 'Which flying structure can float next to an End city?', 'End Ship', 'Ocean Monument', 'Shipwreck', 'Bastion Remnant', 0, 'Some End cities have a floating End ship nearby, guarded by shulkers and full of loot.', 313, true, 'choice', null::jsonb, null::text[]),
  ('exit-portal-made-of-bedrock', 'Which unbreakable block forms the frame of the End''s exit portal?', 'End Stone', 'Bedrock', 'Obsidian', 'Purpur Block', 1, 'The exit portal is a bowl of bedrock with a bedrock pillar in the middle.', 314, true, 'choice', null::jsonb, null::text[]),
  ('dragon-egg-teleports-when-hit', 'What does the dragon egg do when you hit it?', 'Teleports away', 'Breaks into shards', 'Hatches a dragon', 'Explodes', 0, 'Hitting or using the dragon egg makes it teleport to a nearby spot instead of breaking.', 315, true, 'choice', null::jsonb, null::text[]),
  ('redstone-ore-needs-iron-pickaxe', 'Which pickaxe do you need at least to get dust from redstone ore?', 'Wooden Pickaxe', 'Diamond Pickaxe', 'Iron Pickaxe', 'Stone Pickaxe', 2, 'Redstone ore drops dust only when you mine it with an iron pickaxe or better.', 316, true, 'choice', null::jsonb, null::text[]),
  ('redstone-torch-inverts-signal', 'What does a redstone torch do when the block it is attached to gets powered?', 'It glows brighter', 'It falls off', 'It explodes', 'It turns off', 3, 'A redstone torch flips the signal: power the block it''s on and the torch goes dark.', 317, true, 'choice', null::jsonb, null::text[]),
  ('detector-rail-senses-minecarts', 'Which rail sends a redstone signal when a minecart rolls over it?', 'Detector Rail', 'Activator Rail', 'Powered Rail', 'Rail', 0, 'A detector rail gives off a signal while a cart is on it, which is great for stations.', 318, true, 'choice', null::jsonb, null::text[]),
  ('trapped-chest-signal-when-open', 'Which chest gives off a redstone signal while it''s open?', 'Chest', 'Ender Chest', 'Barrel', 'Trapped Chest', 3, 'A trapped chest powers redstone while someone has it open, perfect for surprise traps.', 319, true, 'choice', null::jsonb, null::text[]),
  ('string-links-tripwire-hooks', 'What do you stretch between two tripwire hooks to make a trap line?', 'String', 'Lead', 'Chain', 'Redstone Dust', 0, 'String placed between two facing hooks sends a signal when something walks through it.', 320, true, 'choice', null::jsonb, null::text[]),
  ('lightning-rod-pulse-on-strike', 'Which block gives a short redstone pulse when lightning strikes it?', 'Target', 'Daylight Detector', 'Lightning Rod', 'Observer', 2, 'A lightning rod attracts nearby lightning and gives a full-strength pulse when struck.', 321, true, 'choice', null::jsonb, null::text[]),
  ('sculk-sensor-hears-vibrations', 'Which block sends a signal when it senses footsteps or other sounds nearby?', 'Observer', 'Sculk Sensor', 'Note Block', 'Daylight Detector', 1, 'Sculk sensors pick up vibrations like footsteps or landing arrows and turn them into a signal.', 322, true, 'choice', null::jsonb, null::text[]),
  ('dropper-just-tosses-items', 'Which block just tosses items out instead of using them?', 'Dropper', 'Hopper', 'Crafter', 'Dispenser', 0, 'A dropper throws items out as they are, while a dispenser uses them, like firing arrows.', 323, true, 'choice', null::jsonb, null::text[]),
  ('crafter-crafts-on-pulse', 'Which block crafts an item by itself each time it gets a redstone pulse?', 'Dispenser', 'Smithing Table', 'Crafting Table', 'Crafter', 3, 'The crafter, added in 1.21, crafts one item from its grid every time it gets a pulse.', 324, true, 'choice', null::jsonb, null::text[]),
  ('copper-bulb-toggles-light', 'Which copper block switches its light on or off with every redstone pulse?', 'Redstone Lamp', 'Sea Lantern', 'Lantern', 'Copper Bulb', 3, 'A copper bulb flips its light with each pulse and stays that way, unlike a redstone lamp.', 325, true, 'choice', null::jsonb, null::text[]),
  ('witch-can-drop-redstone', 'Which mob can drop redstone dust when defeated?', 'Creeper', 'Skeleton', 'Witch', 'Zombie', 2, 'Witches can drop redstone dust, glowstone dust, sugar, sticks and more.', 326, true, 'choice', null::jsonb, null::text[]),
  ('blaze-powder-brews-strength', 'Adding blaze powder to an awkward potion brews which potion?', 'Potion of Swiftness', 'Potion of Fire Resistance', 'Potion of Healing', 'Potion of Strength', 3, 'Blaze powder in an awkward potion makes a Potion of Strength for harder hits.', 327, true, 'choice', null::jsonb, null::text[]),
  ('magma-cube-drops-cream', 'Which bouncy Nether mob can drop magma cream?', 'Magma Cube', 'Blaze', 'Hoglin', 'Piglin', 0, 'Magma cubes can drop magma cream, used to brew Fire Resistance.', 328, true, 'choice', null::jsonb, null::text[]),
  ('piglins-barter-ender-pearls', 'Which of these can piglins give you when you barter gold with them?', 'Netherite Ingot', 'Emerald', 'Ender Pearl', 'Diamond', 2, 'Piglins can trade you ender pearls for gold, a handy way to collect them before the End.', 329, true, 'choice', null::jsonb, null::text[]),
  ('chorus-fruit-smelts-popped', 'Chorus fruit cooked in a furnace becomes which item?', 'End Rod', 'Popped Chorus Fruit', 'Dried Kelp', 'Chorus Flower', 1, 'Smelted chorus fruit becomes popped chorus fruit, used to craft purpur blocks and end rods.', 330, true, 'choice', null::jsonb, null::text[]),
  ('golden-carrot-gold-nuggets', 'Which food is a carrot surrounded by eight gold nuggets?', 'Baked Potato', 'Golden Carrot', 'Golden Apple', 'Glistering Melon Slice', 1, 'Eight gold nuggets around a carrot craft a golden carrot, one of the most filling foods.', 331, true, 'choice', null::jsonb, null::text[]),
  ('pufferfish-poison-nausea', 'Which fish makes you sick with Poison and Nausea if you eat it?', 'Raw Salmon', 'Pufferfish', 'Raw Cod', 'Tropical Fish', 1, 'Eating a pufferfish gives Poison, Nausea and Hunger, so it is better used for brewing.', 332, true, 'choice', null::jsonb, null::text[]),
  ('poisoned-hearts-turn-green', 'What color do your hearts turn while you are poisoned?', 'Green', 'Blue', 'Yellow', 'Black', 0, 'Poison paints your hearts green, so you can spot it at a glance and drink milk or honey.', 333, true, 'choice', null::jsonb, null::text[]),
  ('absorption-hearts-yellow', 'What color are the bonus hearts you get from Absorption?', 'Purple', 'Yellow', 'Black', 'Green', 1, 'Absorption adds extra yellow hearts on top of your red ones, and damage takes them away first.', 334, true, 'choice', null::jsonb, null::text[]),
  ('hunger-effect-drains-food', 'What does the Hunger status effect do to you?', 'Slows your mining', 'Drains your food faster', 'Stops you from jumping', 'Makes you glow', 1, 'The Hunger effect makes your food and saturation run out faster and tints the hunger bar green.', 335, true, 'choice', null::jsonb, null::text[]),
  ('cake-seven-slices', 'How many slices can you eat from one full cake?', '8', '7', '4', '6', 1, 'A placed cake has 7 slices, and each bite fills one drumstick of hunger.', 336, true, 'choice', null::jsonb, null::text[]),
  ('golden-apple-full-hunger', 'Which of these foods can you eat even with a full hunger bar?', 'Baked Potato', 'Golden Apple', 'Steak', 'Bread', 1, 'Golden apples can be eaten anytime, even with full hunger, so you can use them right before a fight.', 337, true, 'choice', null::jsonb, null::text[]),
  ('wither-effect-black-hearts', 'Which status effect turns your hearts black?', 'Poison', 'Slowness', 'Weakness', 'Wither', 3, 'The Wither effect blackens your hearts and drains health, and unlike Poison it can defeat you.', 338, true, 'choice', null::jsonb, null::text[]),
  ('recovery-compass-last-death', 'Which compass points to the spot where you last died?', 'Recovery Compass', 'Clock', 'Compass', 'Map', 0, 'A recovery compass points to your latest death spot, as long as you are in the same dimension.', 339, true, 'choice', null::jsonb, null::text[]),
  ('broken-bed-world-spawn', 'If your bed gets destroyed, where do you respawn?', 'In the Nether', 'Where you died', 'At a village bell', 'World spawn', 3, 'Without a working bed or respawn anchor, you go back to the world spawn after dying.', 340, true, 'choice', null::jsonb, null::text[]),
  ('skeleton-rides-spider-jockey', 'Which mob sometimes spawns riding on a spider?', 'Enderman', 'Skeleton', 'Witch', 'Creeper', 1, 'A spider jockey is a skeleton riding a spider: the spider climbs while the skeleton shoots.', 341, true, 'choice', null::jsonb, null::text[]),
  ('baby-zombie-chicken-jockey', 'A baby version of which mob can ride around on a chicken?', 'Creeper', 'Zombie', 'Skeleton', 'Witch', 1, 'A chicken jockey is a baby zombie riding a chicken, a rare but speedy night visitor.', 342, true, 'choice', null::jsonb, null::text[]),
  ('soul-lantern-from-soul-torch', 'Eight iron nuggets around a soul torch make which block?', 'Jack o''Lantern', 'Soul Campfire', 'Soul Lantern', 'Lantern', 2, 'A soul lantern is crafted like a lantern but with a soul torch, and it gives light level 10.', 343, true, 'choice', null::jsonb, null::text[]),
  ('monster-spawner-in-dungeons', 'Which caged block in dungeons keeps creating new mobs?', 'Conduit', 'Monster Spawner', 'Lodestone', 'Beacon', 1, 'A monster spawner keeps making mobs while a player is nearby, so many players break it with a pickaxe.', 344, true, 'choice', null::jsonb, null::text[]),
  ('lever-opens-iron-door', 'Which of these can open an iron door?', 'Lever', 'Sign', 'Carpet', 'Ladder', 0, 'Iron doors ignore clicks and open only with redstone, like a lever, button or pressure plate.', 345, true, 'choice', null::jsonb, null::text[]),
  ('spyglass-zooms-in', 'Looking through which item lets you zoom in on faraway things?', 'Compass', 'Spyglass', 'Clock', 'Glass Pane', 1, 'Looking through a spyglass zooms far in, great for spotting structures and mobs from afar.', 346, true, 'choice', null::jsonb, null::text[]),
  ('sneak-on-magma-block', 'How can you walk on a magma block without getting burned?', 'Jump on it', 'Hold a torch', 'Sprint across it', 'Sneak across it', 3, 'Sneaking on magma blocks stops their burning damage, and Frost Walker boots work too.', 347, true, 'choice', null::jsonb, null::text[]),
  ('powder-snow-freezes-you', 'Which snowy block makes you sink in and freeze?', 'Packed Ice', 'Ice', 'Powder Snow', 'Snow Block', 2, 'Powder snow swallows you like quicksand, and staying inside makes you freeze and take damage.', 348, true, 'choice', null::jsonb, null::text[]),
  ('carrot-on-a-stick-steers-pig', 'What do you hold to steer a saddled pig you are riding?', 'Saddle', 'Warped Fungus on a Stick', 'Carrot on a Stick', 'Lead', 2, 'Hold a carrot on a stick while riding a saddled pig and it walks toward the carrot.', 349, true, 'choice', null::jsonb, null::text[]),
  ('powered-rail-speeds-minecart', 'Which rail speeds up a minecart when it gets redstone power?', 'Powered Rail', 'Activator Rail', 'Detector Rail', 'Rail', 0, 'A powered rail boosts minecarts when powered and brakes them to a stop when it is off.', 350, true, 'choice', null::jsonb, null::text[]),
  ('sneak-holds-on-ladder', 'What do you do to stay still on a ladder without sliding down?', 'Swim', 'Sneak', 'Look up', 'Jump', 1, 'Holding sneak on a ladder makes you grab on and stay in place, handy for building.', 351, true, 'choice', null::jsonb, null::text[]),
  ('boat-holds-two-riders', 'How many riders, players or mobs, fit in one regular boat?', '3', '4', '1', '2', 3, 'A boat carries two riders, so you can bring a friend or even a mob along.', 352, true, 'choice', null::jsonb, null::text[]),
  ('lightning-rod-attracts-strikes', 'Which copper block pulls nearby lightning strikes onto itself?', 'Iron Bars', 'End Rod', 'Lightning Rod', 'Chain', 2, 'A lightning rod under open sky draws lightning to itself, helping protect wooden builds.', 353, true, 'choice', null::jsonb, null::text[]),
  ('potion-of-leaping-jump', 'Which potion lets you jump higher than usual?', 'Potion of Slow Falling', 'Potion of Strength', 'Potion of Swiftness', 'Potion of Leaping', 3, 'A Potion of Leaping gives you Jump Boost, so you can jump higher for a while.', 354, true, 'choice', null::jsonb, null::text[]),
  ('potion-of-swiftness-speed', 'Drinking which potion makes you run much faster for a while?', 'Potion of Leaping', 'Potion of Night Vision', 'Potion of Healing', 'Potion of Swiftness', 3, 'A Potion of Swiftness gives you Speed, so you move faster until it wears off.', 355, true, 'choice', null::jsonb, null::text[]),
  ('helmet-stops-zombie-burning', 'Which piece of gear keeps a zombie from burning in sunlight?', 'Boots', 'Shield', 'Helmet', 'Leggings', 2, 'A zombie wearing a helmet won''t catch fire in the sun, so it can chase you during the day.', 356, true, 'choice', null::jsonb, null::text[]),
  ('snow-golem-pumpkin-head', 'What do you place on top of two snow blocks to build a snow golem?', 'Glowstone', 'Carved Pumpkin', 'Melon', 'Hay Bale', 1, 'Put a carved pumpkin on two stacked snow blocks and a snow golem comes to life.', 357, true, 'choice', null::jsonb, null::text[]),
  ('water-breathing-potion', 'Which potion lets you breathe underwater for a while?', 'Potion of Water Breathing', 'Potion of Night Vision', 'Potion of Healing', 'Potion of Swiftness', 0, 'A Potion of Water Breathing keeps your air bar full underwater until the effect ends.', 358, true, 'choice', null::jsonb, null::text[]),
  ('weaponsmith-sells-enchanted-swords', 'Who should you trade with to get an enchanted sword?', 'Armorer', 'Weaponsmith', 'Toolsmith', 'Cleric', 1, 'Weaponsmiths sell enchanted iron and diamond swords.', 359, true, 'choice', null::jsonb, null::text[]),
  ('armorer-sells-shields', 'A villager offers you a shield. What is its job?', 'Armorer', 'Fletcher', 'Weaponsmith', 'Toolsmith', 0, 'Armorers start selling shields once they reach the journeyman level.', 360, true, 'choice', null::jsonb, null::text[]),
  ('butcher-sells-rabbit-stew', 'Which villager sells bowls of rabbit stew?', 'Butcher', 'Cleric', 'Farmer', 'Fisherman', 0, 'Butchers sell rabbit stew right from the novice level.', 361, true, 'choice', null::jsonb, null::text[]),
  ('cleric-sells-redstone-dust', 'Which villager sells redstone dust for emeralds?', 'Cleric', 'Mason', 'Librarian', 'Toolsmith', 0, 'Clerics sell redstone dust from the novice level, and lapis and glowstone later.', 362, true, 'choice', null::jsonb, null::text[]),
  ('traded-villager-keeps-job', 'You trade with a villager once. What happens to its job?', 'It changes every day', 'It resets at night', 'It keeps it forever', 'It becomes a nitwit', 2, 'After its first trade with a player, a villager never loses its profession.', 363, true, 'choice', null::jsonb, null::text[]),
  ('untraded-villager-can-switch-job', 'A villager you never traded with loses its job block. What can it do?', 'Leave the village', 'Become a nitwit', 'Turn into a witch', 'Take a new job', 3, 'If it has never traded with a player, it can claim another job block and change profession.', 364, true, 'choice', null::jsonb, null::text[]),
  ('bell-sends-villagers-to-beds', 'When you ring a village bell, where do villagers run?', 'To the fields', 'To the bell', 'Out of the village', 'To their beds', 3, 'Ringing a bell makes nearby villagers hurry to the nearest bed.', 365, true, 'choice', null::jsonb, null::text[]),
  ('fletcher-buys-sticks', 'Which item does a novice fletcher buy for emeralds?', 'Leather', 'Paper', 'Bones', 'Sticks', 3, 'Novice fletchers pay an emerald for a bundle of sticks.', 366, true, 'choice', null::jsonb, null::text[]),
  ('cleric-buys-rotten-flesh', 'Which villager will pay emeralds for rotten flesh?', 'Butcher', 'Farmer', 'Leatherworker', 'Cleric', 3, 'Novice clerics buy rotten flesh, so zombie drops can become emeralds.', 367, true, 'choice', null::jsonb, null::text[]),
  ('wandering-trader-invisible-at-night', 'What does a wandering trader drink when night falls?', 'Milk Bucket', 'Potion of Invisibility', 'Potion of Swiftness', 'Water Bottle', 1, 'At dusk the wandering trader drinks a Potion of Invisibility and stays hidden all night.', 368, true, 'choice', null::jsonb, null::text[]),
  ('novice-is-first-villager-level', 'What level is a villager when it first gets a job?', 'Apprentice', 'Expert', 'Journeyman', 'Novice', 3, 'Every villager starts trading at the Novice level with a stone badge.', 369, true, 'choice', null::jsonb, null::text[]),
