  ('multishot-fires-three-arrows', 'How many arrows does a Multishot crossbow fire at once?', '2', '5', '3', '4', 2, 'Multishot fires three arrows in a spread but uses up only one.', 374, true, 'choice', null::jsonb, null::text[]),
  ('piercing-passes-through-mobs', 'Which crossbow enchantment lets arrows pass through several mobs?', 'Quick Charge', 'Multishot', 'Piercing', 'Unbreaking', 2, 'Piercing lets crossbow arrows go through mobs and hit the ones behind.', 375, true, 'choice', null::jsonb, null::text[]),
  ('quick-charge-loads-faster', 'Which crossbow enchantment makes it load faster?', 'Piercing', 'Quick Charge', 'Multishot', 'Efficiency', 1, 'Quick Charge cuts the time it takes to load a crossbow.', 376, true, 'choice', null::jsonb, null::text[]),
  ('luck-of-the-sea-more-treasure', 'Which fishing rod enchantment helps you catch more treasure?', 'Luck of the Sea', 'Fortune', 'Lure', 'Looting', 0, 'Luck of the Sea raises the chance of fishing up treasure instead of junk.', 377, true, 'choice', null::jsonb, null::text[]),
  ('punch-knocks-mobs-back', 'Which bow enchantment makes arrows knock mobs farther back?', 'Flame', 'Power', 'Knockback', 'Punch', 3, 'Punch adds extra knockback to arrows shot from a bow.', 378, true, 'choice', null::jsonb, null::text[]),
  ('vanishing-curse-removes-item', 'What happens to an item with Curse of Vanishing when you die?', 'It returns to your bed', 'It turns into XP orbs', 'It stays with you', 'It disappears', 3, 'Curse of Vanishing makes the item disappear instead of dropping when you die.', 379, true, 'choice', null::jsonb, null::text[]),
  ('binding-curse-locks-armor', 'Which curse stops you from taking off a piece of armor?', 'Thorns', 'Unbreaking', 'Curse of Binding', 'Curse of Vanishing', 2, 'Curse of Binding keeps cursed armor stuck in your armor slot.', 380, true, 'choice', null::jsonb, null::text[]),
  ('fire-protection-vs-lava', 'Which armor enchantment cuts damage from fire and lava?', 'Thorns', 'Projectile Protection', 'Fire Protection', 'Blast Protection', 2, 'Fire Protection lowers fire and lava damage and makes you burn for less time.', 381, true, 'choice', null::jsonb, null::text[]),
  ('blast-protection-vs-explosions', 'Which armor enchantment is made to reduce explosion damage?', 'Projectile Protection', 'Feather Falling', 'Blast Protection', 'Fire Protection', 2, 'Blast Protection lowers the damage you take from creepers and other explosions.', 382, true, 'choice', null::jsonb, null::text[]),
  ('projectile-protection-vs-arrows', 'Which armor enchantment is best against skeleton arrows?', 'Fire Protection', 'Projectile Protection', 'Blast Protection', 'Thorns', 1, 'Projectile Protection specially reduces damage from arrows, tridents and other projectiles.', 383, true, 'choice', null::jsonb, null::text[]),
  ('sharpness-max-level-five', 'What is the highest Sharpness level you can get in survival?', '10', '4', '5', '3', 2, 'Sharpness goes up to level 5, the strongest you can get without commands.', 384, true, 'choice', null::jsonb, null::text[]),
  ('mending-never-from-table', 'Which enchantment can never come from an enchanting table?', 'Mending', 'Efficiency', 'Protection', 'Unbreaking', 0, 'Mending is a treasure enchantment, so you find it in loot, fishing or trades instead.', 385, true, 'choice', null::jsonb, null::text[]),
  ('bookshelves-need-one-block-gap', 'What must be between an enchanting table and its bookshelves?', 'A torch', 'Nothing at all', 'One empty block', 'A carpet', 2, 'Bookshelves only help if there is one empty block between them and the table.', 386, true, 'choice', null::jsonb, null::text[]),
  ('zombie-villager-on-hard', 'On Hard difficulty, what does a villager killed by a zombie always become?', 'Pillager', 'Witch', 'Husk', 'Zombie Villager', 3, 'On Hard, zombies always turn the villagers they kill into zombie villagers.', 387, true, 'choice', null::jsonb, null::text[]),
  ('shepherd-buys-wool', 'Which villager buys wool from you for emeralds?', 'Farmer', 'Leatherworker', 'Butcher', 'Shepherd', 3, 'A shepherd pays emeralds for wool, so a sheep farm can make you rich.', 388, true, 'choice', null::jsonb, null::text[])
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
where pack.slug = 'minecraft-medium'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  kind = excluded.kind,
  media = excluded.media,
  option_icons = excluded.option_icons;

insert into public.question_translations (question_id, locale, prompt, option_a, option_b, option_c, option_d, explanation)
