  ('bookshelves-need-one-block-gap', 'uk', 'Що має бути між столом зачарування та книжковими полицями?', 'Смолоскип', 'Нічого', 'Один порожній блок', 'Килим', 'Полиці допомагають, лише якщо між ними й столом є один порожній блок.'),
  ('bookshelves-need-one-block-gap', 'en', 'What must be between an enchanting table and its bookshelves?', 'A torch', 'Nothing at all', 'One empty block', 'A carpet', 'Bookshelves only help if there is one empty block between them and the table.'),
  ('bookshelves-need-one-block-gap', 'ru', 'Что должно быть между чародейским столом и книжными полками?', 'Факел', 'Ничего', 'Один пустой блок', 'Ковёр', 'Полки помогают, только если между ними и столом есть один пустой блок.'),
  ('zombie-villager-on-hard', 'uk', 'Ким на складності «Складна» завжди стає селянин, якого вбив зомбі?', 'Розбійник', 'Відьма', 'Висушень', 'Зомбоселянин', 'На складності «Складна» зомбі завжди перетворюють убитих селян на зомбоселян.'),
  ('zombie-villager-on-hard', 'en', 'On Hard difficulty, what does a villager killed by a zombie always become?', 'Pillager', 'Witch', 'Husk', 'Zombie Villager', 'On Hard, zombies always turn the villagers they kill into zombie villagers.'),
  ('zombie-villager-on-hard', 'ru', 'Кем на сложности «Сложная» всегда становится крестьянин, которого убил зомби?', 'Разбойник', 'Ведьма', 'Кадавр', 'Крестьянин-зомби', 'На сложности «Сложная» зомби всегда превращают убитых крестьян в крестьян-зомби.'),
  ('shepherd-buys-wool', 'uk', 'Який селянин купує в тебе вовну за смарагди?', 'Фермер', 'Чинбар', 'М’ясник', 'Вівчар', 'Вівчар платить смарагди за вовну, тож ферма овець може тебе збагатити.'),
  ('shepherd-buys-wool', 'en', 'Which villager buys wool from you for emeralds?', 'Farmer', 'Leatherworker', 'Butcher', 'Shepherd', 'A shepherd pays emeralds for wool, so a sheep farm can make you rich.'),
  ('shepherd-buys-wool', 'ru', 'Какой крестьянин покупает у тебя шерсть за изумруды?', 'Фермер', 'Кожевник', 'Мясник', 'Пастух', 'Пастух платит изумруды за шерсть, так что овечья ферма может тебя обогатить.')
) as v(content_id, locale, prompt, option_a, option_b, option_c, option_d, explanation)
  on v.content_id = question.content_id
on conflict (question_id, locale) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  explanation = excluded.explanation;

insert into public.question_packs (category_id, locale, age_band, difficulty, title, slug, is_active)
select id, null, '8-12', 'hard', 'MineMind hard', 'minecraft-hard', true
from public.quiz_categories
where slug = 'minecraft'
on conflict (slug) do update set is_active = true, title = excluded.title;

insert into public.questions (pack_id, content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
select pack.id, v.content_id, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.correct_option, v.explanation, v.sort_order, v.is_active, v.kind, v.media, v.option_icons
from public.question_packs pack
cross join (values
  ('amethyst-geode-underground', 'Which block forms the outer shell of an amethyst geode?', 'Smooth Basalt', 'Deepslate', 'Calcite', 'Obsidian', 0, 'Geodes have three layers: smooth basalt outside, calcite in the middle and amethyst inside.', 1, true, 'choice', null::jsonb, null::text[]),
  ('ocean-ruins-underwater', 'Brushing suspicious sand in warm ocean ruins can give which rare item?', 'Nautilus Shell', 'Trident', 'Sniffer Egg', 'Turtle Egg', 2, 'Suspicious sand in warm ocean ruins can hold a sniffer egg, which hatches into a sniffer.', 2, true, 'choice', null::jsonb, null::text[]),
  ('ancient-city-deep-dark', 'Which block forms the giant portal-like frame in the middle of an ancient city?', 'Reinforced Deepslate', 'Bedrock', 'Obsidian', 'Crying Obsidian', 0, 'The strange frame in ancient cities is built from reinforced deepslate, which generates nowhere else.', 3, true, 'choice', null::jsonb, null::text[]),
  ('badlands-above-ground-mineshafts', 'In which biome do mineshafts often stick out above the ground?', 'Badlands', 'Desert', 'Taiga', 'Jungle', 0, 'In badlands, mineshafts can generate at surface level, so their tunnels poke out of the hills.', 4, true, 'choice', null::jsonb, null::text[]),
  ('bastion-remnant-nether', 'Which axe-wielding mob guards bastion remnants and never respawns?', 'Wither Skeleton', 'Piglin Brute', 'Zombified Piglin', 'Vindicator', 1, 'Piglin brutes appear only when a bastion generates and attack players even in gold armor.', 5, true, 'choice', null::jsonb, null::text[]),
  ('buried-treasure-found-from-map', 'Which item is guaranteed in every buried treasure chest?', 'Heart of the Sea', 'Nautilus Shell', 'Totem of Undying', 'Trident', 0, 'Each buried treasure chest has one heart of the sea, the key part of a conduit.', 6, true, 'choice', null::jsonb, null::text[]),
  ('desert-well-desert', 'Which brushable block can be found inside a desert well?', 'Suspicious Gravel', 'Sandstone', 'Soul Sand', 'Suspicious Sand', 3, 'Desert wells hide suspicious sand under the water, and brushing it can give pottery sherds.', 7, true, 'choice', null::jsonb, null::text[]),
  ('end-city-has-shulkers', 'Which structure is the only place where shulkers spawn naturally?', 'Ancient City', 'Stronghold', 'End City', 'Bastion Remnant', 2, 'Shulkers hide on end city towers and shoot bullets that make players float up.', 8, true, 'choice', null::jsonb, null::text[]),
  ('end-city-outer-end', 'Which item hangs in an item frame on an end ship?', 'Totem of Undying', 'Elytra', 'Dragon Egg', 'Trident', 1, 'End ships carry an item frame with elytra, the wings players use to glide.', 9, true, 'choice', null::jsonb, null::text[]),
  ('frozen-ocean-has-icebergs', 'Huge icebergs float in which biome?', 'Ice Spikes', 'Cold Ocean', 'Frozen Ocean', 'Deep Ocean', 2, 'Frozen oceans have icebergs of packed and blue ice, and polar bears can spawn there.', 10, true, 'choice', null::jsonb, null::text[]),
  ('mushroom-fields-safe-from-many-mobs', 'In which biome do hostile mobs like zombies and creepers not spawn naturally?', 'Mushroom Fields', 'Savanna', 'Taiga', 'Stony Peaks', 0, 'Mushroom fields stop hostile mobs from spawning naturally, though spawners still work.', 11, true, 'choice', null::jsonb, null::text[]),
  ('ruined-portal-two-dimensions', 'Ruined portals can generate in which dimensions?', 'Nether and End', 'Overworld and End', 'Overworld and Nether', 'Only the Overworld', 2, 'Ruined portals appear in the Overworld and the Nether, but never in the End.', 12, true, 'choice', null::jsonb, null::text[]),
  ('stronghold-holds-end-portal', 'Which underground structure contains the End portal room?', 'Ancient City', 'Stronghold', 'Mineshaft', 'Trial Chambers', 1, 'Every stronghold has a portal room; fill its frame with eyes of ender to reach the End.', 13, true, 'choice', null::jsonb, null::text[]),
  ('trial-chamber-underground', 'Which mob in trial chambers attacks by shooting wind charges?', 'Blaze', 'Ghast', 'Breeze', 'Shulker', 2, 'Breezes jump around trial chambers and fire wind charges that knock players back.', 14, true, 'choice', null::jsonb, null::text[]),
  ('woodland-mansion-dark-forest', 'In which biome do woodland mansions generate?', 'Birch Forest', 'Taiga', 'Dark Forest', 'Flower Forest', 2, 'Mansions generate in dark forests, and cartographers sell explorer maps that lead to them.', 15, true, 'choice', null::jsonb, null::text[]),
  ('honey-block-slows-slide', 'Which block slows you down when you slide down its side?', 'Soul Sand', 'Packed Ice', 'Slime Block', 'Honey Block', 3, 'Honey blocks grip anything touching their sides, so you slide down slowly instead of falling.', 16, true, 'choice', null::jsonb, null::text[]),
  ('scaffolding-climbs-fast', 'Which climbable block is crafted from bamboo and string?', 'Vines', 'Scaffolding', 'Ladder', 'Twisting Vines', 1, 'Six bamboo and one string make six scaffolding, while ladders use sticks and vines only grow naturally.', 17, true, 'choice', null::jsonb, null::text[]),
  ('stairs-make-corners', 'Which block turns into a corner piece on its own when two meet at an angle?', 'Pressure Plate', 'Slab', 'Door', 'Stairs', 3, 'Stairs check their neighbors and bend into inner or outer corners, which makes roofs look neat.', 18, true, 'choice', null::jsonb, null::text[]),
  ('blast-furnace-smelts-ore-fast', 'Which block turns raw gold into ingots twice as fast as usual?', 'Cartography Table', 'Smoker', 'Stonecutter', 'Blast Furnace', 3, 'This block only works on ores and metal gear, and in exchange it runs at double speed.', 19, true, 'choice', null::jsonb, null::text[]),
  ('compass-needs-redstone', 'Which item sits in the center of the compass recipe, surrounded by iron?', 'Sugar', 'Glowstone Dust', 'Blaze Powder', 'Redstone Dust', 3, 'Four iron ingots around one redstone dust make a compass that points to the world spawn.', 20, true, 'choice', null::jsonb, null::text[]),
  ('hopper-moves-items-between-containers', 'Which block pulls items out of a chest placed above it?', 'Observer', 'Hopper', 'Barrel', 'Dropper', 1, 'A hopper sucks items from the container above and pushes them wherever its spout points.', 21, true, 'choice', null::jsonb, null::text[]),
  ('smithing-table-upgrades-netherite', 'Where do you upgrade diamond gear to netherite?', 'Anvil', 'Blast Furnace', 'Enchanting Table', 'Smithing Table', 3, 'It combines diamond gear, a netherite ingot and a netherite upgrade template.', 22, true, 'choice', null::jsonb, null::text[]),
  ('smoker-cooks-food-faster', 'Which block cooks food twice as fast as a furnace?', 'Campfire', 'Smoker', 'Stonecutter', 'Blast Furnace', 1, 'A smoker only handles food, and in exchange it cooks at double speed.', 23, true, 'choice', null::jsonb, null::text[]),
  ('campfire-calms-bees', 'What can you place under a beehive so bees stay calm when you take honey?', 'Torch', 'Bell', 'Campfire', 'Lantern', 2, 'Smoke rising from a campfire below the hive calms the bees, so they don''t attack when you harvest.', 24, true, 'choice', null::jsonb, null::text[]),
  ('composter-makes-bone-meal', 'Which block turns extra seeds and plants into bone meal?', 'Grindstone', 'Smoker', 'Cauldron', 'Composter', 3, 'Each plant you put in has a chance to raise the level, and a full composter gives one bone meal.', 25, true, 'choice', null::jsonb, null::text[]),
  ('silk-touch-moves-bee-nest', 'Which enchantment lets you pick up a bee nest with the bees still inside?', 'Fortune', 'Efficiency', 'Unbreaking', 'Silk Touch', 3, 'Silk Touch makes the nest drop as an item that keeps its bees; without it a bee nest drops nothing.', 26, true, 'choice', null::jsonb, null::text[]),
  ('cat-scares-creepers', 'Which pet makes creepers run away from it?', 'Wolf', 'Cat', 'Axolotl', 'Horse', 1, 'Creepers are afraid of cats and ocelots, so a cat near your base keeps them away.', 27, true, 'choice', null::jsonb, null::text[]),
  ('charged-creeper-lightning', 'What turns a normal creeper into a charged creeper?', 'Full moon', 'Lightning strike', 'Splash potion', 'Redstone signal', 1, 'Lightning striking near a creeper charges it, making its explosion much stronger.', 28, true, 'choice', null::jsonb, null::text[]),
  ('smite-hurts-undead', 'Which sword enchantment adds extra damage only to undead mobs?', 'Knockback', 'Looting', 'Smite', 'Sharpness', 2, 'Smite boosts damage against undead like zombies and skeletons, while Sharpness helps against all mobs.', 29, true, 'choice', null::jsonb, null::text[]),
  ('wither-skeleton-drops-skull', 'How many wither skeleton skulls do you need to summon the Wither?', '5', '4', '1', '3', 3, 'The Wither is built from 4 soul sand or soul soil blocks with 3 wither skeleton skulls on top.', 30, true, 'choice', null::jsonb, null::text[]),
  ('magma-block-pulls-down-bubbles', 'Which block under water creates a bubble column that pulls you down?', 'Prismarine', 'Sea Lantern', 'Magma Block', 'Soul Sand', 2, 'Magma blocks make whirlpool bubbles that drag you down, while soul sand bubbles push you up.', 31, true, 'choice', null::jsonb, null::text[]),
  ('observer-detects-updates', 'Which block sends a short pulse when the block in front of it changes?', 'Observer', 'Daylight Detector', 'Hopper', 'Note Block', 0, 'An observer watches the block its face points at and fires a quick pulse out the back when it changes.', 32, true, 'choice', null::jsonb, null::text[]),
  ('respawn-anchor-charged-glowstone', 'Which block do you use to charge a respawn anchor?', 'Block of Redstone', 'Glowstone', 'Shroomlight', 'Magma Block', 1, 'Each glowstone block adds one charge, up to four, and every respawn uses one charge.', 33, true, 'choice', null::jsonb, null::text[]),
  ('warped-forest-many-endermen', 'Which Nether biome is full of endermen but has no piglins, hoglins or ghasts?', 'Soul Sand Valley', 'Basalt Deltas', 'Crimson Forest', 'Warped Forest', 3, 'Warped forests spawn only endermen and striders, which makes them one of the calmer Nether biomes.', 34, true, 'choice', null::jsonb, null::text[]),
  ('campfire-cooks-without-fuel', 'Which block cooks food without needing any fuel?', 'Campfire', 'Furnace', 'Crafting Table', 'Smoker', 0, 'A lit campfire cooks up to four food items for free, while furnaces and smokers burn fuel.', 35, true, 'choice', null::jsonb, null::text[]),
  ('honey-bottle-clears-poison', 'Which item cures Poison without drinking milk?', 'Cookie', 'Apple', 'Honey Bottle', 'Spider Eye', 2, 'Drinking honey removes only Poison, so your good potion effects stay active.', 36, true, 'choice', null::jsonb, null::text[]),
  ('powder-snow-needs-leather-boots', 'Which boots let you walk on powder snow without sinking?', 'Diamond Boots', 'Chainmail Boots', 'Leather Boots', 'Iron Boots', 2, 'Only leather boots keep you on top of powder snow; other boots let you sink and freeze.', 37, true, 'choice', null::jsonb, null::text[]),
  ('pumpkin-stops-enderman-stare', 'What can you wear on your head to look at Endermen safely?', 'Carved Pumpkin', 'Turtle Shell', 'Chainmail Helmet', 'Leather Cap', 0, 'A carved pumpkin hides your gaze from Endermen, though it blocks part of your view.', 38, true, 'choice', null::jsonb, null::text[]),
  ('totem-of-undying-saves-once', 'Which rare item can save you from death one time?', 'Heart of the Sea', 'Nether Star', 'Golden Apple', 'Totem of Undying', 3, 'A held totem is used up to keep you alive at half a heart and grant healing effects.', 39, true, 'choice', null::jsonb, null::text[]),
  ('bookshelves-need-air-gap', 'How many bookshelves do you need for level 30 enchantments?', '15', '10', '20', '24', 0, 'Fifteen bookshelves placed one block away from the table unlock the maximum level 30 options.', 40, true, 'choice', null::jsonb, null::text[]),
  ('cartographer-sells-mansion-map', 'Which structure can a cartographer''s explorer map lead you to?', 'Desert Pyramid', 'Ancient City', 'Igloo', 'Woodland Mansion', 3, 'Cartographers sell Woodland Explorer Maps that mark the nearest woodland mansion.', 41, true, 'choice', null::jsonb, null::text[]),
  ('enchanting-table-needs-xp-levels', 'How many levels does the bottom enchanting table option actually use up?', '10', '1', '30', '3', 3, 'The bottom option needs a high level to unlock, but it only takes 3 levels and 3 lapis.', 42, true, 'choice', null::jsonb, null::text[]),
  ('aqua-affinity-speeds-underwater-mining', 'Which enchantment lets you mine underwater without slowing down?', 'Riptide', 'Respiration', 'Aqua Affinity', 'Depth Strider', 2, 'Aqua Affinity on a helmet removes the extra mining slowdown you get from being underwater.', 43, true, 'choice', null::jsonb, null::text[]),
  ('channeling-needs-thunderstorm', 'In which weather can a Channeling trident summon lightning?', 'Clear sky', 'Rain', 'Thunderstorm', 'Snowfall', 2, 'Channeling only calls lightning during a thunderstorm, and the target must be under open sky.', 44, true, 'choice', null::jsonb, null::text[]),
  ('fortune-increases-ore-drops', 'Which pickaxe enchantment can give you extra diamonds from diamond ore?', 'Mending', 'Silk Touch', 'Fortune', 'Efficiency', 2, 'Fortune adds a chance for extra drops from ores like diamond, coal and lapis.', 45, true, 'choice', null::jsonb, null::text[]),
  ('frost-walker-freezes-water', 'Which boot enchantment freezes the water under your feet?', 'Soul Speed', 'Depth Strider', 'Thorns', 'Frost Walker', 3, 'Frost Walker turns nearby water into frosted ice that melts soon after you pass.', 46, true, 'choice', null::jsonb, null::text[]),
  ('golden-apple-cures-zombie-villager', 'Which villager sells Bottles o'' Enchanting at master level?', 'Cleric', 'Cartographer', 'Librarian', 'Fletcher', 0, 'Master clerics trade bottles o'' enchanting for emeralds, an easy source of experience.', 47, true, 'choice', null::jsonb, null::text[]),
  ('grindstone-removes-enchantments', 'Which block removes most enchantments from an item and returns some XP?', 'Anvil', 'Enchanting Table', 'Grindstone', 'Smithing Table', 2, 'A grindstone strips every enchantment except curses and drops a little experience.', 48, true, 'choice', null::jsonb, null::text[]),
  ('infinity-still-needs-one-arrow', 'How many arrows must you carry for an Infinity bow to shoot?', '16', '64', '0', '1', 3, 'Infinity doesn''t use up normal arrows, but you still need one in your inventory to fire.', 49, true, 'choice', null::jsonb, null::text[]),
  ('looting-helps-mob-drops', 'Which sword enchantment makes mobs drop more items?', 'Fire Aspect', 'Looting', 'Smite', 'Sharpness', 1, 'Looting raises how many items mobs drop and the chance of rare drops.', 50, true, 'choice', null::jsonb, null::text[]),
  ('mending-repairs-with-xp', 'Which enchantment fixes an item when you collect XP orbs?', 'Unbreaking', 'Mending', 'Thorns', 'Infinity', 1, 'Mending spends the XP orbs you pick up on repairing the item instead of raising your level.', 51, true, 'choice', null::jsonb, null::text[]),
  ('thorns-damages-attacker', 'Which armor enchantment can hurt mobs that hit you?', 'Feather Falling', 'Thorns', 'Projectile Protection', 'Protection', 1, 'Thorns gives a chance to deal damage back to an attacker, but it wears armor down faster.', 52, true, 'choice', null::jsonb, null::text[]),
  ('unbreaking-reduces-durability-loss', 'Which enchantment makes tools wear out more slowly?', 'Efficiency', 'Mending', 'Unbreaking', 'Protection', 2, 'Unbreaking gives each use a chance to cost no durability, so gear lasts longer.', 53, true, 'choice', null::jsonb, null::text[]),
  ('weaponsmith-uses-grindstone', 'Which villager uses a grindstone as its job block?', 'Fletcher', 'Toolsmith', 'Armorer', 'Weaponsmith', 3, 'Weaponsmiths work at grindstones and sell swords and axes, including enchanted diamond ones.', 54, true, 'choice', null::jsonb, null::text[]),
  ('golden-apple-gives-absorption', 'Which food gives you extra Absorption hearts?', 'Dried Kelp', 'Pumpkin Pie', 'Beetroot Soup', 'Golden Apple', 3, 'A golden apple gives Absorption and Regeneration, great before a tough fight.', 55, true, 'choice', null::jsonb, null::text[]),
  ('totem-must-be-held-in-hand', 'Where must a Totem of Undying be to save you?', 'In an armor slot', 'In your inventory', 'In a chest', 'In your hand', 3, 'The totem only works in your main hand or off-hand, not in your bag.', 56, true, 'choice', null::jsonb, null::text[]),
  ('milk-removes-bad-omen', 'Which item clears Bad Omen before you reach a village?', 'Suspicious Stew', 'Honey Bottle', 'Golden Apple', 'Milk Bucket', 3, 'Milk removes Bad Omen, so you can enter a village without starting a raid.', 57, true, 'choice', null::jsonb, null::text[]),
  ('bed-explodes-in-nether-survival', 'What happens if you try to sleep in a bed in the Nether?', 'Night is skipped', 'It explodes', 'Nothing happens', 'Spawn point is set', 1, 'Beds explode in the Nether and the End, so use a respawn anchor there instead.', 58, true, 'choice', null::jsonb, null::text[]),
  ('zombie-breaks-door-on-hard', 'On Hard difficulty, which mob can break down wooden doors?', 'Enderman', 'Creeper', 'Zombie', 'Skeleton', 2, 'On Hard, zombies can smash wooden doors, so use iron doors or block the entrance.', 59, true, 'choice', null::jsonb, null::text[]),
  ('sleep-prevents-phantom-spawns', 'After how many nights without sleep can phantoms start to spawn?', '10', '1', '3', '5', 2, 'Phantoms can appear once you go three in-game days without sleeping or dying.', 60, true, 'choice', null::jsonb, null::text[]),
  ('respawn-anchor-sets-nether-spawn', 'Which block lets you reappear in the Nether after dying?', 'Beacon', 'Respawn Anchor', 'Furnace', 'Lodestone', 1, 'Each glowstone adds a charge, and every respawn at the anchor uses one up.', 61, true, 'choice', null::jsonb, null::text[]),
  ('ender-pearl-teleports-player', 'Which thrown item teleports you to where it lands?', 'Egg', 'Ender Pearl', 'Snowball', 'Trident', 1, 'An ender pearl moves you to its landing spot but costs a bit of health.', 62, true, 'choice', null::jsonb, null::text[]),
  ('magma-block-pulls-downward', 'What is the highest fall, in blocks, that does no damage?', '3', '2', '5', '8', 0, 'A 3-block fall is safe, but from 4 blocks and higher you start losing health.', 63, true, 'choice', null::jsonb, null::text[]),
  ('soul-sand-pushes-upward', 'Under water, which block makes a bubble column that lifts you up?', 'Magma Block', 'Gravel', 'Soul Sand', 'Obsidian', 2, 'Soul sand creates rising bubble columns, handy for fast water elevators.', 64, true, 'choice', null::jsonb, null::text[]),
  ('glass-pane-from-glass-blocks', 'How many glass panes do six glass blocks make?', '6', '8', '16', '12', 2, 'Six glass blocks become sixteen panes, which makes panes a cheap way to glaze big windows.', 65, true, 'choice', null::jsonb, null::text[]),
  ('blast-furnace-not-for-food', 'Which of these blocks can''t cook raw food?', 'Smoker', 'Furnace', 'Blast Furnace', 'Campfire', 2, 'A blast furnace only smelts ores, raw metal and metal gear, so food has to go elsewhere.', 66, true, 'choice', null::jsonb, null::text[]),
  ('smoker-not-for-ores', 'Which of these won''t a smoker cook?', 'Potato', 'Raw Cod', 'Raw Iron', 'Raw Beef', 2, 'A smoker works only on food, so raw iron needs a furnace or blast furnace.', 67, true, 'choice', null::jsonb, null::text[]),
  ('cartography-table-expands-maps-crafting', 'In a cartography table, what do you add to a map to zoom it out?', 'Compass', 'Glass Pane', 'Ink Sac', 'Paper', 3, 'One sheet of paper zooms the map out a level, showing a wider area in less detail.', 68, true, 'choice', null::jsonb, null::text[]),
  ('brewing-stand-makes-potions-crafting', 'Which item, with three cobblestone, crafts a brewing stand?', 'Blaze Rod', 'Iron Ingot', 'Blaze Powder', 'Stick', 0, 'The blaze rod becomes the stand''s pole, so you must defeat a blaze before you can brew.', 69, true, 'choice', null::jsonb, null::text[]),
  ('stonecutter-chooses-stone-shapes', 'How many stone slabs does a stonecutter make from one stone block?', '2', '1', '8', '3', 0, 'One block splits into two slabs, the same ratio as crafting but without needing three blocks at once.', 70, true, 'choice', null::jsonb, null::text[]),
  ('anvil-can-break-from-use', 'Which workstation gets damaged with use and can finally break?', 'Grindstone', 'Anvil', 'Cartography Table', 'Smithing Table', 1, 'Each use has a 12% chance to damage an anvil, and after its third damage stage it breaks.', 71, true, 'choice', null::jsonb, null::text[]),
  ('loom-simplifies-banner-patterns', 'Besides planks, which item do you need to craft a loom?', 'Wool', 'Iron Ingot', 'String', 'Leather', 2, 'Two string placed above two planks make a loom.', 72, true, 'choice', null::jsonb, null::text[]),
  ('obsidian-needed-for-enchanting-table', 'Besides diamonds and a book, which block crafts an enchanting table?', 'Basalt', 'Obsidian', 'Block of Coal', 'Deepslate', 1, 'Four obsidian, two diamonds and a book make it, so you need a diamond pickaxe first.', 73, true, 'choice', null::jsonb, null::text[]),
  ('redstone-needed-for-clock', 'Which item surrounds redstone dust in the clock recipe?', 'Iron Ingot', 'Emerald', 'Gold Ingot', 'Copper Ingot', 2, 'Four gold ingots around redstone make a clock, while iron in the same shape makes a compass.', 74, true, 'choice', null::jsonb, null::text[]),
  ('door-swings-open-for-houses', 'How many wooden doors does one craft from six planks give?', '2', '3', '6', '1', 1, 'Six planks in a 2×3 shape make three doors, so each door costs only two planks.', 75, true, 'choice', null::jsonb, null::text[]),
  ('fence-gate-opens-between-fences', 'Which block is crafted from four sticks and two planks?', 'Ladder', 'Fence Gate', 'Fence', 'Trapdoor', 1, 'A fence gate is four sticks around two planks; a fence is the reverse, four planks and two sticks.', 76, true, 'choice', null::jsonb, null::text[]),
  ('glass-pane-makes-thin-window', 'Which block can you see through even though it lets no light pass?', 'Tinted Glass', 'White Stained Glass', 'Glass Pane', 'Glass', 0, 'Tinted glass is crafted from glass and amethyst shards and keeps a room dark while you still see out.', 77, true, 'choice', null::jsonb, null::text[]),
  ('smooth-stone-comes-from-second-smelt', 'What do you get by smelting a stone block in a furnace?', 'Deepslate', 'Chiseled Stone Bricks', 'Stone Bricks', 'Smooth Stone', 3, 'Smelting stone gives smooth stone, which you need to craft a blast furnace.', 78, true, 'choice', null::jsonb, null::text[]),
  ('sponge-soaks-up-water', 'Which block soaks up the water around it when placed?', 'Hay Bale', 'Moss Block', 'Sponge', 'Wool', 2, 'A dry sponge absorbs nearby water and turns wet, handy for draining underwater builds.', 79, true, 'choice', null::jsonb, null::text[]),
  ('obsidian-needs-diamond-pickaxe', 'What is the weakest pickaxe that can mine obsidian?', 'Golden Pickaxe', 'Stone Pickaxe', 'Diamond Pickaxe', 'Iron Pickaxe', 2, 'Obsidian only drops when mined with a diamond or netherite pickaxe; iron is not strong enough.', 80, true, 'choice', null::jsonb, null::text[]),
  ('deepslate-mines-slower-than-stone', 'Which deep cave block takes about twice as long to mine as stone?', 'Tuff', 'Diorite', 'Deepslate', 'Andesite', 2, 'Deepslate is twice as hard as stone, so digging deep underground is slower.', 81, true, 'choice', null::jsonb, null::text[]),
  ('copper-oxidizes-green-over-time', 'Which item stops a copper block from slowly turning green?', 'Honeycomb', 'Slimeball', 'Ink Sac', 'Bone Meal', 0, 'Using honeycomb on copper waxes it, freezing its color so it never oxidizes further.', 82, true, 'choice', null::jsonb, null::text[]),
  ('scaffolding-extends-outward-with-support', 'Which planks can never catch fire?', 'Bamboo Planks', 'Birch Planks', 'Crimson Planks', 'Oak Planks', 2, 'Crimson and warped wood come from the Nether and don''t burn, which makes them great near lava.', 83, true, 'choice', null::jsonb, null::text[]),
  ('trapdoor-makes-ladder-hatch', 'Which trapdoor can''t be opened by hand, only with redstone?', 'Iron Trapdoor', 'Copper Trapdoor', 'Spruce Trapdoor', 'Oak Trapdoor', 0, 'Iron trapdoors ignore clicks and open only with a redstone signal, which makes them safer.', 84, true, 'choice', null::jsonb, null::text[]),
  ('piston-cannot-push-obsidian', 'Which of these blocks can a normal piston NOT push?', 'Wool', 'Obsidian', 'Sand', 'Dirt', 1, 'Pistons can''t move obsidian, just like bedrock, so it''s handy for anchoring redstone builds.', 85, true, 'choice', null::jsonb, null::text[]),
  ('slime-block-drags-neighboring-blocks', 'When moved by a piston, which block drags the blocks touching it along?', 'Magma Block', 'Packed Ice', 'Sea Lantern', 'Slime Block', 3, 'Slime blocks stick to their neighbors, so a piston can move a whole group at once, like in flying machines.', 86, true, 'choice', null::jsonb, null::text[]),
  ('tropical-fish-breeds-axolotls', 'What do you feed axolotls to make them breed?', 'Bucket of Cod', 'Bucket of Pufferfish', 'Bucket of Tropical Fish', 'Bucket of Salmon', 2, 'Axolotls only take live tropical fish in a bucket, and you get the empty water bucket back.', 87, true, 'choice', null::jsonb, null::text[]),
  ('slimeball-breeds-frogs', 'Which item do you use to breed frogs?', 'Spider Eye', 'Slimeball', 'Kelp', 'Magma Cream', 1, 'Frogs eat small slimes in the wild, so slimeballs make them breed and lay frogspawn in water.', 88, true, 'choice', null::jsonb, null::text[]),
  ('beetroot-crafts-into-soup', 'How many beetroots do you need to craft one beetroot soup?', '8', '6', '3', '4', 1, 'Beetroot soup takes 6 beetroots and a bowl, a lot of crops for one meal.', 89, true, 'choice', null::jsonb, null::text[]),
  ('striders-breed-with-warped-fungus', 'Which item do you use to breed striders?', 'Crimson Fungus', 'Red Mushroom', 'Nether Wart', 'Warped Fungus', 3, 'Striders love warped fungus: it breeds them, and on a stick it lets you steer one across lava.', 90, true, 'choice', null::jsonb, null::text[]),
  ('turtles-breed-with-seagrass', 'Which plant do you feed turtles to breed them?', 'Lily Pad', 'Sugar Cane', 'Kelp', 'Seagrass', 3, 'Turtles eat seagrass; a fed turtle swims to its home beach and lays eggs in the sand.', 91, true, 'choice', null::jsonb, null::text[]),
  ('foxes-breed-with-sweet-berries', 'Which food do you use to breed foxes?', 'Sweet Berries', 'Melon Slice', 'Beetroot', 'Apple', 0, 'Foxes love berries: both sweet berries and glow berries make them breed.', 92, true, 'choice', null::jsonb, null::text[]),
  ('potato-smelts-into-baked-potato', 'Which of these crops becomes a better food when cooked in a furnace?', 'Carrot', 'Potato', 'Pumpkin', 'Beetroot', 1, 'Smelting a potato gives a baked potato, which restores much more hunger than a raw one.', 93, true, 'choice', null::jsonb, null::text[]),
  ('flower-turns-stew-suspicious', 'Besides a bowl and two mushrooms, what is needed to craft suspicious stew?', 'Spider Eye', 'Flower', 'Sugar', 'Wheat', 1, 'The flower decides the stew''s hidden effect, for example a dandelion restores hunger.', 94, true, 'choice', null::jsonb, null::text[]),
  ('cake-uses-three-milk-buckets', 'How many milk buckets does one cake recipe need?', '1', '4', '2', '3', 3, 'A cake uses a whole top row of milk buckets, and the empty buckets go back into your inventory.', 95, true, 'choice', null::jsonb, null::text[]),
  ('nether-wart-grows-on-soul-sand', 'Which block must nether wart be planted on?', 'Farmland', 'Netherrack', 'Soul Soil', 'Soul Sand', 3, 'Nether wart grows only on soul sand, so brewers bring soul sand home to farm it.', 96, true, 'choice', null::jsonb, null::text[]),
  ('pumpkin-needs-empty-space-beside-stem', 'What light level do crops need at least to keep growing?', '9', '15', '4', '12', 0, 'Crops need light level 9 or more, so an underground farm needs torches or lamps nearby.', 97, true, 'choice', null::jsonb, null::text[]),
  ('cactus-breaks-when-side-touches-block', 'Which plant breaks if a solid block is placed right next to it?', 'Wheat', 'Bamboo', 'Sugar Cane', 'Cactus', 3, 'A cactus pops off as an item when any side touches a solid block, which is how cactus farms work.', 98, true, 'choice', null::jsonb, null::text[]),
  ('tamed-wolf-attacks-hostiles', 'Which hostile mob will a tamed wolf refuse to attack?', 'Witch', 'Skeleton', 'Creeper', 'Zombie', 2, 'Tamed wolves help fight most mobs but never attack creepers, so you must deal with those yourself.', 99, true, 'choice', null::jsonb, null::text[]),
  ('piglin-barters-with-gold', 'Which Nether mob trades you random items for gold ingots?', 'Piglin', 'Wither Skeleton', 'Zombified Piglin', 'Hoglin', 0, 'Piglins take a thrown gold ingot, inspect it and then toss back a random item.', 100, true, 'choice', null::jsonb, null::text[]),
  ('zombified-piglin-angers-group', 'Which neutral Nether mob makes its whole group attack if you hit just one?', 'Enderman', 'Magma Cube', 'Zombified Piglin', 'Strider', 2, 'Hitting one zombified piglin angers every one nearby, so a single swing can start a big fight.', 101, true, 'choice', null::jsonb, null::text[]),
  ('bees-swarm-after-nest-broken', 'Dancing near a playing jukebox, which mob duplicates when given an amethyst shard?', 'Bee', 'Allay', 'Vex', 'Parrot', 1, 'A dancing allay given an amethyst shard makes a copy of itself, then needs 5 minutes before it can do it again.', 102, true, 'choice', null::jsonb, null::text[]),
  ('iron-golem-hits-hard-if-provoked', 'How many iron blocks do you need to build an iron golem?', '6', '3', '5', '4', 3, 'Place 4 iron blocks in a T shape and put a carved pumpkin on top to create an iron golem.', 103, true, 'choice', null::jsonb, null::text[]),
  ('evoker-summons-vexes', 'Which illager casts spells and summons flying vexes?', 'Witch', 'Evoker', 'Pillager', 'Vindicator', 1, 'Evokers summon vexes and fang traps, and they drop a Totem of Undying when defeated.', 104, true, 'choice', null::jsonb, null::text[]),
  ('guardian-fires-laser-beam', 'Which ocean monument mob attacks with a charging laser beam?', 'Drowned', 'Guardian', 'Squid', 'Pufferfish', 1, 'Guardians lock on with a beam that charges up and then deals damage, even through water.', 105, true, 'choice', null::jsonb, null::text[]),
  ('endermite-can-spawn-from-pearl', 'Which tiny hostile mob can appear when a thrown ender pearl lands?', 'Silverfish', 'Cave Spider', 'Vex', 'Endermite', 3, 'Each thrown ender pearl has a 5% chance to spawn an endermite.', 106, true, 'choice', null::jsonb, null::text[]),
  ('bane-of-arthropods-vs-spiders', 'Which enchantment deals extra damage to spiders, bees and silverfish?', 'Bane of Arthropods', 'Fire Aspect', 'Sharpness', 'Smite', 0, 'Bane of Arthropods hurts bug-like mobs more and also slows them down.', 107, true, 'choice', null::jsonb, null::text[]),
  ('totem-works-from-hand-slot', 'Which weapon hits harder the farther you fall before striking?', 'Axe', 'Trident', 'Mace', 'Crossbow', 2, 'A mace adds bonus damage based on how far you fell, so players strike with it after a big jump.', 108, true, 'choice', null::jsonb, null::text[]),
  ('strength-potion-boosts-melee', 'Which potion makes your melee hits deal more damage?', 'Potion of Invisibility', 'Potion of Leaping', 'Potion of Slow Falling', 'Potion of Strength', 3, 'Strength adds bonus damage to every melee hit, which helps a lot in boss fights.', 109, true, 'choice', null::jsonb, null::text[]),
  ('soul-speed-helps-on-soul-sand', 'Which boot enchantment helps you move quickly over Nether sand and soil?', 'Soul Speed', 'Frost Walker', 'Feather Falling', 'Depth Strider', 0, 'Soul Speed works on soul sand and soul soil and comes only from bastion loot or piglin bartering.', 110, true, 'choice', null::jsonb, null::text[]),
  ('comparator-reads-container-fullness', 'Which component can output a signal based on how full a chest is?', 'Redstone Comparator', 'Hopper', 'Observer', 'Redstone Repeater', 0, 'A comparator behind a container gives a stronger signal the fuller that container is.', 111, true, 'choice', null::jsonb, null::text[]),
  ('twelve-eyes-activate-portal', 'How many Eyes of Ender does it take to fill every frame of an End portal?', '8', '12', '16', '10', 1, 'An End portal has 12 frame blocks around a 3×3 center, and each one needs an eye.', 112, true, 'choice', null::jsonb, null::text[]),
  ('chorus-fruit-teleports-randomly', 'Which food can randomly teleport you when you eat it?', 'Chorus Fruit', 'Golden Carrot', 'Glow Berries', 'Cookie', 0, 'Chorus fruit grows on End islands and teleports you a few blocks in a random direction.', 113, true, 'choice', null::jsonb, null::text[]),
  ('dragon-breath-caught-in-bottle', 'What can you collect in a glass bottle from the End boss''s purple attack cloud?', 'Honey Bottle', 'Ghast Tear', 'Dragon''s Breath', 'Bottle o'' Enchanting', 2, 'Dragon''s breath is used to brew lingering potions, which leave an effect cloud on the ground.', 114, true, 'choice', null::jsonb, null::text[]),
  ('crying-obsidian-crafts-anchor', 'Which block is the main ingredient in a respawn anchor recipe?', 'Crying Obsidian', 'Obsidian', 'Blackstone', 'Ancient Debris', 0, 'A respawn anchor takes 6 crying obsidian and 3 glowstone; regular obsidian will not work.', 115, true, 'choice', null::jsonb, null::text[]),
  ('warped-fungus-scares-hoglins', 'Which block makes hoglins run away from it?', 'Crimson Fungus', 'Shroomlight', 'Soul Torch', 'Warped Fungus', 3, 'Hoglins avoid warped fungus, while crimson fungus is the food used to breed them.', 116, true, 'choice', null::jsonb, null::text[]),
  ('blue-ice-makes-fast-boat-road', 'Which block makes the fastest boat roads?', 'Snow Block', 'Packed Ice', 'Blue Ice', 'Ice', 2, 'Blue ice is the most slippery block, so boats on it go much faster than on regular or packed ice.', 117, true, 'choice', null::jsonb, null::text[]),
  ('repeater-adds-redstone-delay', 'How many delay settings can you click through on a redstone repeater?', '3', '4', '6', '2', 1, 'Each click adds one redstone tick of delay, from 1 up to 4, and then it loops back to 1.', 118, true, 'choice', null::jsonb, null::text[]),
  ('target-block-rewards-accurate-hit', 'Which block gives a stronger signal the closer to its center you hit it?', 'Pressure Plate', 'Target', 'Button', 'Lightning Rod', 1, 'A target gives up to 15 power for a bullseye, so it is great for archery games.', 119, true, 'choice', null::jsonb, null::text[]),
  ('daylight-sensor-reads-sky-light', 'Which block powers circuits by sensing the sun and can switch to night mode?', 'Observer', 'Redstone Lamp', 'Sculk Sensor', 'Daylight Detector', 3, 'A daylight detector gives more power in brighter sky light, and using it flips it to work at night.', 120, true, 'choice', null::jsonb, null::text[]),
  ('tf-compass-points-to-bed', 'A normal compass points to the bed you last slept in.', 'True', 'False', null, null, 1, 'False: a normal compass always points to the world spawn point, not to your bed.', 121, true, 'true-false', null::jsonb, null::text[]),
  ('tf-iron-sword-smelts-to-nugget', 'Smelting an iron sword in a furnace gives you an iron nugget.', 'True', 'False', null, null, 0, 'True: old iron tools, weapons and armor each smelt into one iron nugget.', 122, true, 'true-false', null::jsonb, null::text[]),
  ('tf-charcoal-crafts-coal-block', 'Nine pieces of charcoal craft a block of coal.', 'True', 'False', null, null, 1, 'False: a block of coal is crafted only from regular coal, never from charcoal.', 123, true, 'true-false', null::jsonb, null::text[]),
  ('tf-wet-sponge-dries-in-nether', 'A wet sponge placed in the Nether dries out right away.', 'True', 'False', null, null, 0, 'True: in the Nether a wet sponge instantly dries with a puff of steam and can be used again.', 124, true, 'true-false', null::jsonb, null::text[]),
  ('tf-crying-obsidian-portal', 'Crying obsidian works for building a Nether portal frame.', 'True', 'False', null, null, 1, 'False: only regular obsidian makes a working Nether portal frame; crying obsidian doesn''t.', 125, true, 'true-false', null::jsonb, null::text[]),
  ('tf-stray-arrows-slowness', 'Arrows shot by strays give you Slowness.', 'True', 'False', null, null, 0, 'True: strays, the icy skeletons of snowy biomes, shoot arrows of Slowness.', 126, true, 'true-false', null::jsonb, null::text[]),
  ('tf-baby-zombies-slower', 'Baby zombies move slower than adult zombies.', 'True', 'False', null, null, 1, 'False: baby zombies are much faster than adults and have the same health, so watch out.', 127, true, 'true-false', null::jsonb, null::text[]),
  ('tf-sugar-cane-grows-three-tall', 'Planted sugar cane grows up to 3 blocks tall on its own.', 'True', 'False', null, null, 0, 'True: sugar cane grows to 3 blocks; break the top two and leave the bottom one to regrow.', 128, true, 'true-false', null::jsonb, null::text[]),
  ('tf-turtles-bred-with-kelp', 'You breed turtles by feeding them kelp.', 'True', 'False', null, null, 1, 'False: turtles are bred with seagrass, and then one of them lays eggs on sand.', 129, true, 'true-false', null::jsonb, null::text[]),
  ('tf-anvil-combines-books', 'An anvil can join two matching enchanted books into a stronger one.', 'True', 'False', null, null, 0, 'True: for example, two Sharpness I books combine into one Sharpness II book on an anvil.', 130, true, 'true-false', null::jsonb, null::text[]),
  ('tf-cleric-uses-lectern', 'A cleric villager uses a lectern as its job block.', 'True', 'False', null, null, 1, 'False: the cleric''s job block is a brewing stand; a lectern makes a librarian.', 131, true, 'true-false', null::jsonb, null::text[]),
  ('tf-jungle-temple-arrow-traps', 'Jungle temples have tripwire traps that shoot arrows.', 'True', 'False', null, null, 0, 'True: tripwires in a jungle temple trigger hidden dispensers full of arrows.', 132, true, 'true-false', null::jsonb, null::text[]),
  ('tf-every-igloo-has-basement', 'Every igloo has a secret basement under the floor.', 'True', 'False', null, null, 1, 'False: only about half of igloos have a basement, hidden under a trapdoor and a carpet.', 133, true, 'true-false', null::jsonb, null::text[]),
  ('tf-shulker-bullet-levitation', 'Getting hit by a shulker''s bullet makes you float up.', 'True', 'False', null, null, 0, 'True: shulker bullets give Levitation, and you can take fall damage when it wears off.', 134, true, 'true-false', null::jsonb, null::text[]),
  ('tf-shulker-box-spills-items', 'Breaking a shulker box spills all the items inside it.', 'True', 'False', null, null, 1, 'False: a shulker box keeps its items inside when broken, so you can carry it like a backpack.', 135, true, 'true-false', null::jsonb, null::text[]),
  ('pic-leather-from-hoglin', 'Which Nether mob can drop the item in the picture?', 'Hoglin', 'Magma Cube', 'Strider', 'Piglin', 0, 'Hoglins drop leather and porkchops, so they are the Nether''s source of both.', 136, true, 'picture', '{"sprite":"leather","type":"picture"}'::jsonb, null::text[]),
  ('pic-stick-from-witch', 'Which hostile mob sometimes drops the item shown?', 'Enderman', 'Zombie', 'Witch', 'Skeleton', 2, 'Witches can drop sticks, along with glass bottles, sugar, redstone and gunpowder.', 137, true, 'picture', '{"sprite":"stick","type":"picture"}'::jsonb, null::text[]),
  ('pic-coal-smelts-eight', 'How many items can one piece of the fuel shown smelt?', '12', '4', '8', '16', 2, 'One piece of coal burns for 80 seconds, enough to smelt 8 items.', 138, true, 'picture', '{"sprite":"coal","type":"picture"}'::jsonb, null::text[]),
  ('recipe-fishing-rod-missing-string', 'Fill the gap: what completes this fishing rod?', 'Wool', 'String', 'Slimeball', 'Paper', 1, 'A fishing rod is three sticks on a diagonal with two string hanging down the side.', 139, true, 'recipe', '{"grid":[null,null,"stick",null,"stick","string","stick",null,null],"missingSlot":8,"type":"recipe"}'::jsonb, array['wool', 'string', 'slimeball', 'paper']::text[]),
  ('recipe-glass-bottle-missing-glass', 'Which block is missing from this recipe for potion bottles?', 'Diamond', 'Glass', 'Sand', 'Iron Ingot', 1, 'Three glass blocks in a V shape craft three glass bottles for water and potions.', 140, true, 'recipe', '{"grid":[null,null,null,"glass",null,null,null,"glass",null],"missingSlot":5,"type":"recipe"}'::jsonb, array['diamond', 'glass', 'sand', 'iron-ingot']::text[]),
  ('recipe-compass-missing-ingot', 'What belongs in the empty square of this compass recipe?', 'Gold Ingot', 'Iron Ingot', 'Diamond', 'Emerald', 1, 'A compass is four iron ingots around redstone dust; with gold ingots you get a clock instead.', 141, true, 'recipe', '{"grid":[null,null,null,"iron-ingot","redstone","iron-ingot",null,"iron-ingot",null],"missingSlot":1,"type":"recipe"}'::jsonb, array['gold-ingot', 'iron-ingot', 'diamond', 'emerald']::text[]),
  ('recipe-clock-missing-redstone', 'The clock recipe has one empty slot. What goes there?', 'Emerald', 'Diamond', 'Gunpowder', 'Redstone Dust', 3, 'A clock is four gold ingots around one redstone dust, and it shows the time of day.', 142, true, 'recipe', '{"grid":[null,"gold-ingot",null,"gold-ingot",null,"gold-ingot",null,"gold-ingot",null],"missingSlot":4,"type":"recipe"}'::jsonb, array['emerald', 'diamond', 'gunpowder', 'redstone']::text[]),
  ('basalt-deltas-white-ash', 'Which Nether biome has white ash in the air and lots of magma cubes?', 'Soul Sand Valley', 'Crimson Forest', 'Warped Forest', 'Basalt Deltas', 3, 'Basalt deltas are rough fields of basalt and blackstone where ash drifts and magma cubes hop.', 143, true, 'choice', null::jsonb, null::text[]),
  ('badlands-extra-gold-ore', 'In which biome does extra gold ore generate high up, even near the surface?', 'Desert', 'Jagged Peaks', 'Savanna', 'Badlands', 3, 'Badlands get bonus gold ore all the way up to Y=255, far above the usual gold levels.', 144, true, 'choice', null::jsonb, null::text[]),
  ('frozen-peaks-packed-ice', 'Which snowy mountain-top biome has glaciers of packed ice?', 'Jagged Peaks', 'Snowy Slopes', 'Stony Peaks', 'Frozen Peaks', 3, 'Frozen peaks are covered in snow with glaciers of packed ice, and goats live there.', 145, true, 'choice', null::jsonb, null::text[]),
  ('wooded-badlands-oak-plateaus', 'Which badlands variant has oak trees and coarse dirt on its high plateaus?', 'Badlands', 'Eroded Badlands', 'Savanna', 'Wooded Badlands', 3, 'Wooded badlands have grass, coarse dirt and small oak trees on top of their terracotta plateaus.', 146, true, 'choice', null::jsonb, null::text[]),
  ('eroded-badlands-hoodoos', 'Which badlands variant has thin terracotta spires rising from red sand?', 'Badlands', 'Eroded Badlands', 'Desert', 'Wooded Badlands', 1, 'Eroded badlands are famous for hoodoos: thin terracotta spires sticking up from the red sand.', 147, true, 'choice', null::jsonb, null::text[]),
  ('pale-garden-creaking-hearts', 'Creaking hearts hide inside pale oak trees in which biome?', 'Pale Garden', 'Birch Forest', 'Cherry Grove', 'Dark Forest', 0, 'Pale gardens are gray forests of pale oaks, where creaking hearts bring out creakings at night.', 148, true, 'choice', null::jsonb, null::text[]),
  ('gold-rabbits-only-in-deserts', 'Gold-colored rabbits are found only in which biome?', 'Flower Forest', 'Desert', 'Snowy Plains', 'Taiga', 1, 'Gold rabbits spawn only in deserts, while snowy biomes get white rabbits.', 149, true, 'choice', null::jsonb, null::text[]),
  ('meadow-only-mountain-villages', 'Villages can generate in only one mountain biome. Which one?', 'Jagged Peaks', 'Grove', 'Meadow', 'Snowy Slopes', 2, 'Plains-style villages can appear in meadows, the only mountain biome where villages generate.', 150, true, 'choice', null::jsonb, null::text[]),
  ('deep-dark-no-mob-spawning', 'Which biome has no regular mob spawning at all, not even animals?', 'Dripstone Caves', 'Mushroom Fields', 'Lush Caves', 'Deep Dark', 3, 'Mobs don''t spawn on their own in the deep dark, but noisy players can still summon the Warden.', 151, true, 'choice', null::jsonb, null::text[]),
  ('bastion-four-types', 'How many different types of bastion remnant are there?', '2', '4', '6', '3', 1, 'Bastions come in four types: bridge, hoglin stables, housing units and treasure room.', 152, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-three-elders', 'How many elder guardians live in each ocean monument?', '1', '2', '3', '5', 2, 'Each monument has three elder guardians: one at the top and one in each wing.', 153, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-deep-ocean', 'Ocean monuments generate in which kind of water biome?', 'Warm Ocean', 'River', 'Deep Ocean', 'Beach', 2, 'Ocean monuments generate only in deep ocean biomes, far out from the shore.', 154, true, 'choice', null::jsonb, null::text[]),
  ('dungeon-spawner-spider', 'Besides zombies and skeletons, which mob can a dungeon spawner make?', 'Creeper', 'Cave Spider', 'Witch', 'Spider', 3, 'Dungeon spawners make zombies half the time, and skeletons or spiders the rest.', 155, true, 'choice', null::jsonb, null::text[]),
  ('deep-fossils-diamond-ore', 'Fossils deep in the deepslate layer can contain which ore?', 'Emerald Ore', 'Diamond Ore', 'Gold Ore', 'Redstone Ore', 1, 'Deep fossils swap some bone blocks for diamond ore, while higher fossils use coal ore.', 156, true, 'choice', null::jsonb, null::text[]),
  ('trial-chambers-copper-tuff', 'Trial chambers are built mostly from which two materials?', 'Deepslate and Calcite', 'Sandstone and Terracotta', 'Blackstone and Basalt', 'Copper and Tuff', 3, 'Trial chambers are built mostly from copper blocks and tuff bricks, deep underground.', 157, true, 'choice', null::jsonb, null::text[]),
  ('mansion-allays-in-jail', 'Which blue flying helper mob can be found locked in woodland mansion cells?', 'Phantom', 'Allay', 'Vex', 'Parrot', 1, 'Woodland mansions have jail rooms where allays are locked up, often guarded by a vindicator.', 158, true, 'choice', null::jsonb, null::text[]),
  ('swift-sneak-only-ancient-cities', 'The Swift Sneak enchantment can only be found in which structure?', 'Stronghold', 'Woodland Mansion', 'Ancient City', 'End City', 2, 'Swift Sneak books come only from ancient city chests and let you sneak faster in leggings.', 159, true, 'choice', null::jsonb, null::text[]),
  ('disc-fragments-make-disc-five', 'How many disc fragments from ancient cities craft music disc 5?', '6', '4', '8', '9', 3, 'Nine disc fragments, found only in ancient city chests, combine into music disc 5.', 160, true, 'choice', null::jsonb, null::text[]),
  ('pigstep-disc-only-in-bastions', 'The Pigstep music disc can only be found in which structure?', 'Ruined Portal', 'Bastion Remnant', 'Ancient City', 'Nether Fortress', 1, 'Pigstep is a rare disc that appears only in bastion remnant chests.', 161, true, 'choice', null::jsonb, null::text[]),
  ('silence-trim-in-ancient-cities', 'The very rare Silence armor trim is found in which structure''s chests?', 'Ancient City', 'Pillager Outpost', 'Trail Ruins', 'End City', 0, 'Silence armor trim templates appear only in ancient city chests, and they are very rare.', 162, true, 'choice', null::jsonb, null::text[]),
  ('rib-trim-in-nether-fortresses', 'Chests in which structure can hold the Rib armor trim template?', 'Desert Pyramid', 'Nether Fortress', 'End City', 'Bastion Remnant', 1, 'The Rib armor trim, with a bony pattern, is found in Nether fortress chests.', 163, true, 'choice', null::jsonb, null::text[]),
  ('tide-trim-from-elder-guardians', 'Which mob can drop the Tide armor trim template?', 'Drowned', 'Guardian', 'Wither Skeleton', 'Elder Guardian', 3, 'Elder guardians have a 20% chance to drop the Tide armor trim template when defeated.', 164, true, 'choice', null::jsonb, null::text[]),
  ('desert-well-arms-up-sherd', 'Brushing suspicious sand in a desert well can give which pottery sherd?', 'Archer', 'Skull', 'Arms Up', 'Miner', 2, 'Desert wells can give Arms Up or Brewer sherds; Archer, Miner and Skull come from desert pyramids.', 165, true, 'choice', null::jsonb, null::text[]),
  ('wayfinder-trim-in-trail-ruins', 'Brushing gravel in which structure can give the Wayfinder armor trim?', 'Ocean Ruins', 'Desert Pyramid', 'Desert Well', 'Trail Ruins', 3, 'Rare suspicious gravel in trail ruins can give Wayfinder, Raiser, Shaper or Host trims.', 166, true, 'choice', null::jsonb, null::text[]),
  ('flow-trim-from-ominous-vaults', 'In trial chambers, which block can give the Flow armor trim?', 'Vault', 'Ominous Vault', 'Decorated Pot', 'Trial Spawner', 1, 'Flow trims come only from ominous vaults; regular vaults give the Bolt trim instead.', 167, true, 'choice', null::jsonb, null::text[]),
  ('ocean-monument-has-no-chests', 'Which large structure has no loot chests at all?', 'Ocean Monument', 'Woodland Mansion', 'Ancient City', 'Stronghold', 0, 'Ocean monuments have no chests; their prizes are gold blocks, sponges and the guardians'' drops.', 168, true, 'choice', null::jsonb, null::text[]),
  ('dripstone-caves-extra-copper', 'Which cave biome generates extra copper ore?', 'Desert', 'Deep Dark', 'Lush Caves', 'Dripstone Caves', 3, 'Dripstone caves are full of pointed dripstone and generate more copper ore than usual.', 169, true, 'choice', null::jsonb, null::text[]),
  ('flower-forest-many-flowers', 'Which forest biome is covered in many different kinds of flowers?', 'Birch Forest', 'Forest', 'Dark Forest', 'Flower Forest', 3, 'A flower forest grows lots of flower types, great for collecting dyes and bees.', 170, true, 'choice', null::jsonb, null::text[]),
  ('eye-trim-in-strongholds', 'Where can you find the Eye armor trim template?', 'Stronghold', 'Bastion Remnant', 'End City', 'Ancient City', 0, 'The Eye trim template hides in stronghold chests, near the End portal.', 171, true, 'choice', null::jsonb, null::text[]),
  ('budding-amethyst-cannot-be-collected', 'Which geode block can''t be collected, even with Silk Touch?', 'Calcite', 'Block of Amethyst', 'Smooth Basalt', 'Budding Amethyst', 3, 'Budding amethyst grows amethyst buds, but it drops nothing when broken, even with Silk Touch.', 172, true, 'choice', null::jsonb, null::text[]),
  ('emerald-ore-only-in-mountains', 'Which ore generates only in mountain and windswept hills biomes?', 'Coal Ore', 'Emerald Ore', 'Lapis Lazuli Ore', 'Diamond Ore', 1, 'Emerald ore is found only in mountainous biomes and needs an iron pickaxe or better.', 173, true, 'choice', null::jsonb, null::text[]),
  ('nine-ice-craft-packed-ice', 'How many ice blocks craft one block of packed ice?', '9', '6', '4', '8', 0, 'Nine ice craft one packed ice, which is slippery but never melts near light.', 174, true, 'choice', null::jsonb, null::text[]),
  ('packed-ice-crafts-blue-ice', 'Which block do you craft from nine packed ice?', 'Blue Ice', 'Snow Block', 'Glass', 'Ice', 0, 'Nine packed ice craft blue ice, an even more slippery kind of ice.', 175, true, 'choice', null::jsonb, null::text[]),
  ('four-logs-craft-three-wood', 'Four matching logs craft how many wood blocks with bark on every side?', '2', '4', '3', '1', 2, 'Four logs in a 2×2 square craft 3 wood blocks, which have bark on all six sides.', 176, true, 'choice', null::jsonb, null::text[]),
  ('nether-gold-ore-angers-piglins', 'Mining which ore makes nearby piglins angry?', 'Nether Gold Ore', 'Nether Quartz Ore', 'Ancient Debris', 'Coal Ore', 0, 'Piglins guard gold, so breaking Nether gold ore near them makes them attack, even if you wear gold armor.', 177, true, 'choice', null::jsonb, null::text[]),
  ('hoe-turns-coarse-dirt-into-dirt', 'Using a hoe on which block turns it into plain dirt?', 'Grass Block', 'Mud', 'Coarse Dirt', 'Soul Soil', 2, 'A hoe turns coarse dirt into normal dirt, while grass blocks and normal dirt become farmland.', 178, true, 'choice', null::jsonb, null::text[]),
  ('calcite-middle-layer-of-geode', 'In an amethyst geode, which block forms the layer between smooth basalt and amethyst?', 'Calcite', 'Bone Block', 'Diorite', 'Tuff', 0, 'Geodes have an outer layer of smooth basalt, a middle layer of calcite and amethyst inside.', 179, true, 'choice', null::jsonb, null::text[]),
  ('mangrove-grows-from-propagule', 'Which tree grows from a propagule instead of a regular sapling?', 'Mangrove', 'Birch', 'Oak', 'Acacia', 0, 'A mangrove propagule is the mangrove tree''s version of a sapling.', 180, true, 'choice', null::jsonb, null::text[]),
  ('mud-over-dripstone-dries-to-clay', 'Mud placed above pointed dripstone slowly turns into which block?', 'Gravel', 'Dirt', 'Packed Mud', 'Clay', 3, 'Water drips out of the mud through the pointed dripstone, slowly drying the mud into clay.', 181, true, 'choice', null::jsonb, null::text[]),
  ('lava-falling-on-water-makes-stone', 'Which block forms when lava flows down onto water from above?', 'Obsidian', 'Stone', 'Basalt', 'Cobblestone', 1, 'Lava falling onto water makes stone, while lava touching water from the side makes cobblestone.', 182, true, 'choice', null::jsonb, null::text[]),
  ('lava-soul-soil-blue-ice-basalt', 'Lava flowing over soul soil next to blue ice turns into which block?', 'Netherrack', 'Basalt', 'Obsidian', 'Cobblestone', 1, 'This is a basalt generator: lava above soul soil that touches blue ice becomes basalt.', 183, true, 'choice', null::jsonb, null::text[]),
  ('tnt-fuse-four-seconds', 'About how many seconds after being lit does TNT explode?', '4', '2', '1', '10', 0, 'Lit TNT explodes after 80 game ticks, which is 4 seconds, so you have time to run.', 184, true, 'choice', null::jsonb, null::text[]),
  ('obsidian-survives-tnt-blast', 'Which block stays in one piece when TNT explodes right next to it?', 'Cobblestone', 'Stone', 'Obsidian', 'Bricks', 2, 'Obsidian has huge blast resistance, so normal explosions from TNT or creepers can''t break it.', 185, true, 'choice', null::jsonb, null::text[]),
  ('hay-bale-cuts-fall-damage', 'Landing on which block cuts your fall damage by 80%?', 'Snow Block', 'Hay Bale', 'Wool', 'Leaves', 1, 'A hay bale reduces fall damage by 80%, so you take only a fifth of the normal damage.', 186, true, 'choice', null::jsonb, null::text[]),
  ('slime-never-sticks-to-honey', 'A moving slime block drags its neighbors along, but never sticks to which block?', 'Dirt', 'Honey Block', 'Oak Planks', 'Stone', 1, 'Slime and honey blocks never stick to each other, so builders use that to split moving machines.', 187, true, 'choice', null::jsonb, null::text[]),
  ('furnace-dries-wet-sponge', 'Which workstation can dry a wet sponge so it soaks up water again?', 'Blast Furnace', 'Furnace', 'Smoker', 'Campfire', 1, 'Smelting a wet sponge in a furnace dries it out, so you can use it again.', 188, true, 'choice', null::jsonb, null::text[]),
  ('lightning-cleans-copper', 'What instantly turns a fully oxidized copper block shiny again?', 'Snowfall', 'Lightning strike', 'Rain', 'Water Bucket', 1, 'When lightning hits copper that is not waxed, it removes all the oxidation at once.', 189, true, 'choice', null::jsonb, null::text[]),
  ('six-planks-make-two-trapdoors', 'Six planks in two rows craft how many wooden trapdoors?', '3', '1', '4', '2', 3, 'Six planks laid in two rows of three craft 2 trapdoors.', 190, true, 'choice', null::jsonb, null::text[]),
  ('flower-pot-needs-three-bricks', 'How many bricks does it take to craft a flower pot?', '5', '3', '4', '2', 1, 'A flower pot is crafted from three bricks arranged in a V shape.', 191, true, 'choice', null::jsonb, null::text[]),
  ('fence-recipe-makes-three', 'Four planks and two sticks craft how many wooden fences?', '1', '3', '4', '2', 1, 'Four planks and two sticks make 3 fences, enough to start a small animal pen.', 192, true, 'choice', null::jsonb, null::text[]),
  ('six-planks-and-stick-make-three-signs', 'Six planks and one stick craft how many signs?', '1', '6', '3', '2', 2, 'The sign recipe gives 3 signs, and you can stack up to 16 signs in one slot.', 193, true, 'choice', null::jsonb, null::text[]),
  ('hay-bale-raises-campfire-smoke', 'Which block under a campfire makes its smoke rise much higher?', 'Netherrack', 'Soul Sand', 'Magma Block', 'Hay Bale', 3, 'A hay bale under a campfire makes a signal fire whose smoke rises 25 blocks instead of 10.', 194, true, 'choice', null::jsonb, null::text[]),
  ('glow-ink-sac-lights-sign-text', 'Which item makes the text on a sign glow?', 'Ink Sac', 'Glowstone Dust', 'Glow Berries', 'Glow Ink Sac', 3, 'Using a glow ink sac on a sign makes its text glow; a normal ink sac turns the glow off.', 195, true, 'choice', null::jsonb, null::text[]),
  ('soul-torch-scares-piglins', 'Which light source do piglins stay away from?', 'Lantern', 'Soul Torch', 'Torch', 'Redstone Torch', 1, 'Piglins are scared of soul fire items like soul torches, though piglin brutes don''t care.', 196, true, 'choice', null::jsonb, null::text[]),
  ('packed-mud-crafts-mud-bricks', 'Four packed mud blocks in a square craft which block?', 'Clay', 'Terracotta', 'Bricks', 'Mud Bricks', 3, 'Packed mud in a 2x2 square becomes mud bricks, a sturdy building block.', 197, true, 'choice', null::jsonb, null::text[]),
  ('pointed-dripstone-crafts-block', 'Four pointed dripstone placed in a square craft which block?', 'Tuff', 'Dripstone Block', 'Calcite', 'Basalt', 1, 'Four pointed dripstone in a square craft one dripstone block.', 198, true, 'choice', null::jsonb, null::text[]),
  ('pointed-dripstone-extra-fall-damage', 'Landing on which block makes your fall damage even worse?', 'Hay Bale', 'Snow Block', 'Pointed Dripstone', 'Stone', 2, 'Upward-pointing dripstone adds extra damage when you fall onto it, so watch your step in caves.', 199, true, 'choice', null::jsonb, null::text[]),
  ('dye-around-glass-stained', 'Eight glass blocks around one dye craft what?', 'Stained Glass', 'Glazed Terracotta', 'Tinted Glass', 'Glass Pane', 0, 'Surround a dye with eight glass and you get eight stained glass in that color.', 200, true, 'choice', null::jsonb, null::text[]),
  ('piston-breaks-pumpkin', 'Which of these blocks breaks into an item when a piston pushes it?', 'Dirt', 'Pumpkin', 'Stone', 'Wool', 1, 'Pistons can''t move pumpkins; they break them, which is how many pumpkin farms work.', 201, true, 'choice', null::jsonb, null::text[]),
  ('anvil-costs-31-iron-ingots', 'Counting the iron blocks, how many iron ingots does one anvil cost?', '36', '24', '27', '31', 3, 'An anvil uses 3 blocks of iron and 4 iron ingots, which adds up to 31 iron ingots.', 202, true, 'choice', null::jsonb, null::text[]),
  ('fletching-table-flint-over-planks', 'What do you put above four planks to craft a fletching table?', 'Feather', 'Stick', 'Flint', 'Arrow', 2, 'Two flint on top of four planks craft a fletching table, the job block of fletcher villagers.', 203, true, 'choice', null::jsonb, null::text[]),
  ('grindstone-sticks-slab-planks', 'Which workstation is crafted from sticks, a stone slab and planks?', 'Smithing Table', 'Grindstone', 'Loom', 'Stonecutter', 1, 'Sticks, a stone slab and planks craft a grindstone, which repairs items and removes enchantments.', 204, true, 'choice', null::jsonb, null::text[]),
  ('stonecutter-iron-over-stone', 'Besides three stone, what goes into a stonecutter recipe?', 'Iron Ingot', 'Flint', 'Gold Ingot', 'Copper Ingot', 0, 'One iron ingot above three stone crafts a stonecutter, which cuts stone into stairs, slabs and walls.', 205, true, 'choice', null::jsonb, null::text[]),
  ('rails-sixteen-per-craft', 'Six iron ingots and one stick give you how many rails?', '6', '8', '16', '12', 2, 'One rail recipe makes 16 rails, so a short track only needs a little iron.', 206, true, 'choice', null::jsonb, null::text[]),
  ('hopper-chest-and-iron', 'Which block, plus five iron ingots, crafts a hopper?', 'Chest', 'Dropper', 'Furnace', 'Barrel', 0, 'A hopper is five iron ingots in a funnel shape with a chest in the middle.', 207, true, 'choice', null::jsonb, null::text[]),
  ('tinted-glass-four-amethyst-shards', 'How many amethyst shards go around one glass block to make tinted glass?', '2', '4', '8', '1', 1, 'Four amethyst shards around one glass craft 2 tinted glass, which you can see through but blocks light.', 208, true, 'choice', null::jsonb, null::text[]),
  ('block-of-coal-smelts-80', 'A block of coal can smelt how many items?', '80', '72', '64', '9', 0, 'A block of coal smelts 80 items, a little more than the 72 you would get from nine loose coal.', 209, true, 'choice', null::jsonb, null::text[]),
  ('blaze-rod-smelts-12', 'As furnace fuel, one blaze rod smelts how many items?', '16', '8', '4', '12', 3, 'A blaze rod burns for 12 items, longer than coal, though most players save rods for brewing.', 210, true, 'choice', null::jsonb, null::text[]),
  ('two-sticks-per-smelted-item', 'How many sticks must burn to smelt just one item?', '1', '3', '4', '2', 3, 'A stick burns for only half a smelt, so it takes 2 sticks to cook a single item.', 211, true, 'choice', null::jsonb, null::text[]),
  ('furnace-ten-seconds-per-item', 'How many seconds does a regular furnace take to smelt one item?', '10', '30', '20', '5', 0, 'A furnace needs 10 seconds per item, while a smoker or blast furnace takes only 5.', 212, true, 'choice', null::jsonb, null::text[]),
  ('campfire-thirty-seconds-per-item', 'How long does a campfire take to cook one piece of food?', '30 seconds', '10 seconds', '60 seconds', '5 seconds', 0, 'Campfire cooking is slow, 30 seconds per item, but it needs no fuel and holds four items.', 213, true, 'choice', null::jsonb, null::text[]),
  ('blast-furnace-burns-fuel-twice-as-fast', 'Compared with a furnace, how fast does a blast furnace use up its fuel?', 'Twice as fast', 'Half as fast', 'Same speed', 'Three times as fast', 0, 'A blast furnace smelts twice as fast and burns fuel twice as fast, so each coal still smelts 8 items.', 214, true, 'choice', null::jsonb, null::text[]),
  ('hopper-on-furnace-side-fills-fuel', 'A hopper pointing into the side of a furnace fills which slot?', 'All slots', 'Output slot', 'Ingredient slot', 'Fuel slot', 3, 'Hoppers on top feed the item slot, hoppers on the side feed the fuel slot, and a hopper below takes the results.', 215, true, 'choice', null::jsonb, null::text[]),
  ('sea-pickle-smelts-lime-dye', 'Smelting a sea pickle gives you which dye?', 'Green Dye', 'Cyan Dye', 'Yellow Dye', 'Lime Dye', 3, 'Sea pickles smelt into lime dye, while cactus smelts into the darker green dye.', 216, true, 'choice', null::jsonb, null::text[]),
  ('dyed-terracotta-smelts-glazed', 'Smelting colored terracotta creates which patterned block?', 'Bricks', 'Sandstone', 'Concrete', 'Glazed Terracotta', 3, 'Dyed terracotta smelts into glazed terracotta, which has bright patterns that join up when placed.', 217, true, 'choice', null::jsonb, null::text[]),
  ('golden-pickaxe-mines-fastest', 'Without enchantments, which pickaxe mines stone the fastest?', 'Golden Pickaxe', 'Diamond Pickaxe', 'Netherite Pickaxe', 'Iron Pickaxe', 0, 'Gold is the fastest tool material, even quicker than netherite, but it wears out very quickly.', 218, true, 'choice', null::jsonb, null::text[]),
  ('full-iron-armor-24-ingots', 'How many iron ingots does a full set of iron armor take?', '20', '27', '32', '24', 3, 'A full armor set always costs 24 units of its material, whether leather, iron, gold or diamond.', 219, true, 'choice', null::jsonb, null::text[]),
  ('netherite-template-copy-seven-diamonds', 'How many diamonds do you need to copy a netherite upgrade template?', '7', '9', '5', '3', 0, 'A template, a netherrack block and 7 diamonds craft 2 templates, so you can keep upgrading.', 220, true, 'choice', null::jsonb, null::text[]),
  ('mace-needs-breeze-rod', 'Besides a heavy core, which item do you need to craft a mace?', 'Blaze Rod', 'Stick', 'Iron Ingot', 'Breeze Rod', 3, 'A heavy core from trial chambers plus a breeze rod crafts the mace, added in 1.21.', 221, true, 'choice', null::jsonb, null::text[]),
  ('chainmail-armor-cannot-be-crafted', 'Which kind of armor can''t be crafted at all?', 'Leather Armor', 'Iron Armor', 'Chainmail Armor', 'Golden Armor', 2, 'Chainmail armor has no crafting recipe; you can only get it from mobs, trading or loot chests.', 222, true, 'choice', null::jsonb, null::text[]),
  ('ender-chest-drops-obsidian', 'Mined with a pickaxe without Silk Touch, an ender chest drops what?', 'Ender Pearl', 'Chest', 'Obsidian', 'Eye of Ender', 2, 'An ender chest breaks into 8 obsidian unless you use Silk Touch, so the eye of ender is lost.', 223, true, 'choice', null::jsonb, null::text[]),
  ('smithing-template-for-netherite-upgrade', 'Upgrading diamond gear to netherite needs a netherite ingot and which other item?', 'Smithing Template', 'Netherite Scrap', 'Diamond', 'Blaze Powder', 0, 'Since 1.20, each netherite upgrade also uses up a netherite upgrade smithing template.', 224, true, 'choice', null::jsonb, null::text[]),
  ('netherite-upgrade-keeps-enchantments', 'When enchanted diamond gear is upgraded to netherite, what happens to its enchantments?', 'They stay', 'Only one stays', 'They get stronger', 'They vanish', 0, 'Upgrading at a smithing table keeps every enchantment, so your best diamond gear loses nothing.', 225, true, 'choice', null::jsonb, null::text[]),
  ('stone-bricks-smelt-cracked', 'Stone bricks smelted in a furnace turn into which block?', 'Mossy Stone Bricks', 'Cracked Stone Bricks', 'Chiseled Stone Bricks', 'Smooth Stone', 1, 'Stone bricks smelt into cracked stone bricks, which look old and broken.', 226, true, 'choice', null::jsonb, null::text[]),
  ('netherite-set-four-ingots', 'How many netherite ingots does it take to upgrade a full diamond armor set?', '16', '4', '1', '8', 1, 'Each of the 4 armor pieces needs one netherite ingot and a template at a smithing table.', 227, true, 'choice', null::jsonb, null::text[]),
  ('leggings-seven-ingots', 'Which armor piece needs exactly seven ingots to craft?', 'Chestplate', 'Boots', 'Leggings', 'Helmet', 2, 'Leggings use 7 ingots, a chestplate 8, a helmet 5 and boots just 4.', 228, true, 'choice', null::jsonb, null::text[]),
  ('beacon-needs-obsidian', 'Besides glass and a nether star, which block goes into a beacon recipe?', 'Glowstone', 'Obsidian', 'Crying Obsidian', 'Block of Diamond', 1, 'A beacon takes five glass, one nether star and three obsidian on the bottom row.', 229, true, 'choice', null::jsonb, null::text[]),
  ('conduit-heart-of-the-sea', 'Which rare item sits in the middle of a conduit recipe?', 'Heart of the Sea', 'Sea Lantern', 'Prismarine Crystals', 'Nether Star', 0, 'A conduit is a heart of the sea surrounded by eight nautilus shells.', 230, true, 'choice', null::jsonb, null::text[]),
  ('dispenser-needs-bow', 'Which weapon goes into the recipe for a dispenser?', 'Crossbow', 'Bow', 'Sword', 'Trident', 1, 'A dispenser is seven cobblestone, a bow and redstone dust, so it can shoot arrows.', 231, true, 'choice', null::jsonb, null::text[]),
  ('wheat-eight-growth-stages', 'How many growth stages does a wheat crop go through?', '8', '10', '6', '4', 0, 'Wheat grows through 8 stages, from tiny green sprouts to golden wheat ready to harvest.', 232, true, 'choice', null::jsonb, null::text[]),
  ('crimson-nylium-bone-meal', 'Using bone meal on which block makes crimson roots and fungi sprout?', 'Soul Soil', 'Netherrack', 'Magma Block', 'Crimson Nylium', 3, 'Bone meal on crimson nylium grows crimson roots and fungi around it, a handy Nether garden.', 233, true, 'choice', null::jsonb, null::text[]),
  ('chorus-flower-on-end-stone', 'Chorus flowers can be planted on which block?', 'Purpur Block', 'Sand', 'Obsidian', 'End Stone', 3, 'Chorus flowers are planted on end stone, in any dimension, and grow into tall chorus plants.', 234, true, 'choice', null::jsonb, null::text[]),
  ('sniffer-digs-ancient-seeds', 'Which big ancient mob digs up torchflower seeds and pitcher pods?', 'Armadillo', 'Rabbit', 'Camel', 'Sniffer', 3, 'Sniffers sniff the ground and dig up torchflower seeds or pitcher pods, ancient plants for your farm.', 235, true, 'choice', null::jsonb, null::text[]),
  ('water-hydrates-four-blocks', 'How many blocks away can water keep farmland wet?', '8', '4', '2', '6', 1, 'Water keeps farmland wet up to 4 blocks away, diagonals too, so one water block covers a 9×9 field.', 236, true, 'choice', null::jsonb, null::text[]),
  ('giant-jungle-four-saplings', 'How many jungle saplings do you need for a giant jungle tree?', '9', '6', '4', '2', 2, 'Plant 4 jungle saplings in a 2×2 square to grow a giant jungle tree.', 237, true, 'choice', null::jsonb, null::text[]),
  ('dark-oak-needs-four-saplings', 'Which sapling can''t grow into a tree when it is planted alone?', 'Dark Oak Sapling', 'Oak Sapling', 'Birch Sapling', 'Acacia Sapling', 0, 'Dark oak saplings only grow when four of them are planted together in a 2×2 square.', 238, true, 'choice', null::jsonb, null::text[]),
  ('nether-wart-grows-in-dark', 'Which crop grows just as fast in total darkness?', 'Wheat', 'Nether Wart', 'Carrot', 'Potato', 1, 'Nether wart ignores light, so it grows even in a dark room, unlike wheat, carrots and potatoes.', 239, true, 'choice', null::jsonb, null::text[]),
  ('cocoa-pod-three-stages', 'How many growth stages does a cocoa pod have?', '4', '2', '3', '8', 2, 'A cocoa pod has 3 growth stages and gets bigger at each one until it is ready to harvest.', 240, true, 'choice', null::jsonb, null::text[]),
  ('nether-wart-four-stages', 'Nether wart grows through how many stages?', '3', '2', '4', '8', 2, 'Nether wart has 4 growth stages and is ready to harvest at the last, tallest one.', 241, true, 'choice', null::jsonb, null::text[]),
  ('torchflower-seeds-on-farmland', 'Where do you plant torchflower seeds so they grow?', 'Soul Sand', 'Sand', 'Farmland', 'Moss Block', 2, 'Torchflower seeds go on farmland like other crops and grow into a bright torchflower.', 242, true, 'choice', null::jsonb, null::text[]),
  ('pumpkin-stem-keeps-growing', 'After you break a pumpkin, what does its stem do?', 'Dries up for good', 'Turns into a melon stem', 'Grows another pumpkin', 'Breaks and drops seeds', 2, 'A pumpkin stem stays planted and can grow new pumpkins again and again.', 243, true, 'choice', null::jsonb, null::text[]),
  ('breeding-cooldown-five-minutes', 'After breeding, how many minutes until cows can breed again?', '10', '20', '1', '5', 3, 'Parent cows need a 5-minute rest after breeding before they can have another calf.', 244, true, 'choice', null::jsonb, null::text[]),
  ('baby-cow-grows-in-twenty-minutes', 'How many minutes does a baby cow take to grow up on its own?', '20', '10', '60', '5', 0, 'A baby cow grows up in 20 minutes, and feeding it wheat makes it grow faster.', 245, true, 'choice', null::jsonb, null::text[]),
  ('blue-axolotl-only-from-breeding', 'Which animal can be born in a super rare blue color?', 'Fox', 'Rabbit', 'Axolotl', 'Frog', 2, 'Blue axolotls never spawn naturally; each bred baby has a 1 in 1200 chance to be blue.', 246, true, 'choice', null::jsonb, null::text[]),
  ('baby-turtle-drops-scute', 'What does a baby turtle drop when it grows up?', 'Turtle Scute', 'Prismarine Shard', 'Turtle Egg', 'Nautilus Shell', 0, 'A baby turtle drops a turtle scute as it grows up, and five scutes craft a turtle shell helmet.', 247, true, 'choice', null::jsonb, null::text[]),
  ('hoglins-breed-crimson-fungus', 'Which item makes two hoglins breed?', 'Red Mushroom', 'Warped Fungus', 'Crimson Fungus', 'Nether Wart', 2, 'Hoglins breed with crimson fungus, the red fungus that grows in crimson forests.', 248, true, 'choice', null::jsonb, null::text[]),
  ('camels-breed-with-cactus', 'Which plant do you feed camels to breed them?', 'Sugar Cane', 'Wheat', 'Cactus', 'Hay Bale', 2, 'Camels breed with cactus, which also heals them and helps baby camels grow up faster.', 249, true, 'choice', null::jsonb, null::text[]),
  ('armadillos-breed-spider-eye', 'What do armadillos need to eat so they breed?', 'Wheat', 'Sweet Berries', 'Spider Eye', 'Rotten Flesh', 2, 'Armadillos breed when fed spider eyes, which also make baby armadillos grow faster.', 250, true, 'choice', null::jsonb, null::text[]),
  ('nine-slices-make-melon', 'How many slices does it take to craft a whole melon block?', '8', '6', '9', '4', 2, 'Nine melon slices craft back into one whole melon block.', 251, true, 'choice', null::jsonb, null::text[]),
  ('rabbit-stew-ingredients', 'Which stew needs cooked rabbit, a carrot and a baked potato?', 'Mushroom Stew', 'Suspicious Stew', 'Beetroot Soup', 'Rabbit Stew', 3, 'Rabbit stew mixes cooked rabbit, a carrot, a baked potato, a mushroom and a bowl.', 252, true, 'choice', null::jsonb, null::text[]),
  ('honey-bottle-crafts-sugar', 'Besides sugar cane, which item can you craft into sugar?', 'Sweet Berries', 'Beetroot', 'Honey Bottle', 'Milk Bucket', 2, 'A honey bottle crafts into sugar and leaves the empty glass bottle behind.', 253, true, 'choice', null::jsonb, null::text[]),
  ('observer-detects-crop-growth', 'Which redstone block notices when the crop in front of it grows?', 'Redstone Comparator', 'Target', 'Daylight Detector', 'Observer', 3, 'An observer sends a redstone pulse when the block it watches changes, like a crop growing.', 254, true, 'choice', null::jsonb, null::text[]),
  ('cake-always-fills-composter', 'Which item raises a composter''s level every single time?', 'Kelp', 'Wheat Seeds', 'Melon Slice', 'Cake', 3, 'Cake and pumpkin pie always add a composter layer, while seeds only work 30% of the time.', 255, true, 'choice', null::jsonb, null::text[]),
  ('brown-mooshroom-flower-stew', 'Feed a flower to a brown mooshroom, then use a bowl. What do you get?', 'Beetroot Soup', 'Suspicious Stew', 'Mushroom Stew', 'Rabbit Stew', 1, 'A brown mooshroom fed a small flower gives suspicious stew with that flower''s effect.', 256, true, 'choice', null::jsonb, null::text[]),
  ('cod-most-common-catch', 'Which fish do you catch most often with a fishing rod?', 'Raw Salmon', 'Raw Cod', 'Pufferfish', 'Tropical Fish', 1, 'Raw cod is the most common catch, followed by salmon, pufferfish and rare tropical fish.', 257, true, 'choice', null::jsonb, null::text[]),
  ('sniffers-breed-torchflower-seeds', 'Which seeds make two sniffers ready to breed?', 'Sweet Berries', 'Wheat Seeds', 'Pitcher Pod', 'Torchflower Seeds', 3, 'Sniffers breed with torchflower seeds, which they first dig up themselves.', 258, true, 'choice', null::jsonb, null::text[]),
  ('rare-pink-sheep', 'Which of these wool colors can a sheep naturally spawn with, though very rarely?', 'Blue', 'Red', 'Green', 'Pink', 3, 'Pink sheep are very rare natural spawns; blue, green and red sheep only come from dye.', 259, true, 'choice', null::jsonb, null::text[]),
  ('cookie-recipe-makes-eight', 'Two wheat and one cocoa bean craft how many cookies?', '16', '8', '4', '1', 1, 'That small recipe gives a whole batch of 8 cookies.', 260, true, 'choice', null::jsonb, null::text[]),
  ('ocelot-trusts-but-never-tamed', 'Which jungle animal trusts you after eating raw fish but can never be tamed?', 'Panda', 'Cat', 'Ocelot', 'Parrot', 2, 'Feeding an ocelot raw cod or salmon makes it trust you and stop running away, but it never becomes a pet.', 261, true, 'choice', null::jsonb, null::text[]),
  ('iron-golem-offers-poppy', 'Which big mob sometimes holds out a flower to villagers?', 'Wandering Trader', 'Snow Golem', 'Allay', 'Iron Golem', 3, 'Iron golems can make a poppy appear in their hand and offer it to villagers.', 262, true, 'choice', null::jsonb, null::text[]),
  ('panda-personalities', 'Which mob can be born lazy, worried, playful or aggressive?', 'Llama', 'Panda', 'Goat', 'Fox', 1, 'Every panda has a personality, such as lazy, worried, playful or aggressive, that comes from its genes.', 263, true, 'choice', null::jsonb, null::text[]),
  ('mooshroom-lightning-color-swap', 'Which animal switches between red and brown when lightning strikes near it?', 'Fox', 'Mooshroom', 'Sheep', 'Pig', 1, 'A lightning strike within a few blocks turns a red mooshroom brown, and a brown one red.', 264, true, 'choice', null::jsonb, null::text[]),
  ('fox-babies-trust-breeder', 'Which shy animal''s babies trust you only if you bred them yourself?', 'Goat', 'Fox', 'Rabbit', 'Panda', 1, 'Breed two foxes with sweet berries and the baby fox will trust you instead of running away.', 265, true, 'choice', null::jsonb, null::text[]),
  ('goat-drops-horn-when-ramming', 'Which mob can drop a horn after ramming into a log or stone?', 'Goat', 'Cow', 'Sheep', 'Llama', 0, 'An adult goat that rams stone, ore or logs can drop a goat horn that you can blow like an instrument.', 266, true, 'choice', null::jsonb, null::text[]),
  ('allay-delivers-to-note-block', 'Which helper mob drops its items next to a note block you just played?', 'Bat', 'Bee', 'Allay', 'Parrot', 2, 'An allay that hears a nearby note block brings the items it collects to that block instead of to you.', 267, true, 'choice', null::jsonb, null::text[]),
  ('llama-caravan-ten', 'How many llamas can travel in one caravan when you lead one?', '5', '6', '8', '10', 3, 'Leading one llama makes up to nine nearby llamas follow in a line, forming a caravan of up to ten.', 268, true, 'choice', null::jsonb, null::text[]),
  ('frog-eats-magma-cube-froglight', 'What block drops when a frog eats a tiny magma cube?', 'Sea Lantern', 'Glowstone', 'Froglight', 'Shroomlight', 2, 'Frogs eat tiny magma cubes, which drop a froglight whose color depends on the kind of frog.', 269, true, 'choice', null::jsonb, null::text[]),
  ('hoglin-becomes-zoglin', 'What does a hoglin turn into if it is brought to the Overworld?', 'Ghast', 'Piglin Brute', 'Zoglin', 'Zombified Piglin', 2, 'A hoglin that enters the Overworld or the End shakes and becomes a zoglin after 15 seconds.', 270, true, 'choice', null::jsonb, null::text[]),
  ('wither-skeleton-wither-effect', 'Which Nether fortress mob''s hits give you the Wither effect?', 'Stray', 'Wither Skeleton', 'Skeleton', 'Blaze', 1, 'Wither skeletons live in Nether fortresses, and each hit inflicts Wither for 10 seconds.', 271, true, 'choice', null::jsonb, null::text[]),
  ('bogged-poison-arrows', 'Which mossy skeleton in swamps shoots poison arrows?', 'Skeleton', 'Bogged', 'Stray', 'Wither Skeleton', 1, 'The bogged spawns in swamps and trial chambers and shoots arrows that inflict Poison.', 272, true, 'choice', null::jsonb, null::text[]),
  ('elder-guardian-mining-fatigue', 'Which ocean monument boss slows your mining with Mining Fatigue?', 'Warden', 'Guardian', 'Drowned', 'Elder Guardian', 3, 'Elder guardians give nearby players Mining Fatigue III, so breaking monument blocks becomes very slow.', 273, true, 'choice', null::jsonb, null::text[]),
  ('creeper-shot-by-skeleton-music-disc', 'A skeleton''s arrow defeats a creeper. Which rare item drops?', 'Ender Pearl', 'Music Disc', 'Creeper Head', 'Emerald', 1, 'A creeper killed by a skeleton, stray or bogged drops a random music disc to play in a jukebox.', 274, true, 'choice', null::jsonb, null::text[]),
  ('ender-dragon-hundred-hearts', 'How many hearts of health does the Ender Dragon have?', '50', '100', '250', '150', 1, 'The Ender Dragon has 200 health points, which equals 100 hearts, so bring plenty of arrows.', 275, true, 'choice', null::jsonb, null::text[]),
  ('warden-gives-darkness', 'Near a Warden, which effect makes your screen pulse black?', 'Nausea', 'Weakness', 'Blindness', 'Darkness', 3, 'Every few seconds the Warden gives Darkness to players within 20 blocks, even before it gets angry.', 276, true, 'choice', null::jsonb, null::text[]),
  ('piglin-brute-ignores-gold', 'Which bastion mob attacks you even if you wear gold armor?', 'Piglin', 'Hoglin', 'Piglin Brute', 'Zombified Piglin', 2, 'Piglin brutes guard bastion remnants, ignore your gold armor and never barter.', 277, true, 'choice', null::jsonb, null::text[]),
  ('vex-flies-through-walls', 'Which small flying mob can pass straight through walls to reach you?', 'Bat', 'Allay', 'Vex', 'Phantom', 2, 'Vexes are summoned by evokers and fly through any block, even bedrock, so walls can''t stop them.', 278, true, 'choice', null::jsonb, null::text[]),
  ('critical-hit-fifty-percent', 'Hitting a mob while falling is a critical hit. How much extra damage does it deal?', '100%', '25%', '75%', '50%', 3, 'Jump and strike a mob on the way down to land a critical hit, which deals 50% more damage.', 279, true, 'choice', null::jsonb, null::text[]),
  ('snowballs-hurt-blazes', 'Which thrown item hurts blazes but not most other mobs?', 'Arrow', 'Snowball', 'Egg', 'Ender Pearl', 1, 'Each snowball deals 3 damage to a blaze, while other mobs take no damage from snowballs.', 280, true, 'choice', null::jsonb, null::text[]),
  ('shield-blocks-creeper-blast', 'Raising a shield can protect you from which of these?', 'Lava', 'Creeper Explosion', 'Fall Damage', 'Drowning', 1, 'Shields block creeper blasts, melee hits and arrows from the front, but not falls, lava or drowning.', 281, true, 'choice', null::jsonb, null::text[]),
  ('iron-ingot-heals-golem', 'What can you use on a cracked iron golem to heal it?', 'Iron Ingot', 'Poppy', 'Golden Apple', 'Iron Nugget', 0, 'Using an iron ingot on a damaged iron golem heals 25 health and removes one level of cracks.', 282, true, 'choice', null::jsonb, null::text[]),
  ('piercing-ignores-shields', 'Which crossbow enchantment shoots arrows that go right through shields?', 'Power', 'Piercing', 'Quick Charge', 'Multishot', 1, 'Piercing arrows fly through several mobs and can''t be blocked by a raised shield.', 283, true, 'choice', null::jsonb, null::text[]),
  ('warden-sonic-boom-through-walls', 'Which mob''s sonic boom blasts through walls and shields?', 'Ravager', 'Elder Guardian', 'Ghast', 'Warden', 3, 'The Warden''s sonic boom passes through blocks and ignores shields, so running away is the safest plan.', 284, true, 'choice', null::jsonb, null::text[]),
  ('flame-sets-targets-on-fire', 'Which bow enchantment sets the mobs you shoot on fire?', 'Punch', 'Infinity', 'Flame', 'Power', 2, 'Arrows from a bow with Flame burn as they fly and set any mob they hit on fire.', 285, true, 'choice', null::jsonb, null::text[]),
  ('husk-punch-causes-hunger', 'Which effect can a husk''s punch give you?', 'Weakness', 'Poison', 'Slowness', 'Hunger', 3, 'An empty-handed husk''s hits give you Hunger, so your food bar drains faster after the fight.', 286, true, 'choice', null::jsonb, null::text[]),
  ('enderman-dodges-arrows', 'Which mob teleports away so your arrows can''t hit it?', 'Phantom', 'Blaze', 'Ghast', 'Enderman', 3, 'Endermen teleport out of the way of arrows, so fight them up close with a sword.', 287, true, 'choice', null::jsonb, null::text[]),
  ('netherite-knockback-resistance', 'Which armor material also helps you resist being knocked back?', 'Netherite', 'Iron', 'Gold', 'Diamond', 0, 'Netherite armor gives knockback resistance, so hits push you around less.', 288, true, 'choice', null::jsonb, null::text[]),
  ('ghast-fireball-hit-back', 'How can you send a ghast''s fireball flying back at it?', 'Hit it', 'Pour water on it', 'Duck under it', 'Block it with a shield', 0, 'Hit the fireball with your hand or a sword to knock it back toward the ghast.', 289, true, 'choice', null::jsonb, null::text[]),
  ('axolotl-plays-dead', 'Which water mob may play dead when it gets hurt?', 'Axolotl', 'Squid', 'Frog', 'Turtle', 0, 'A hurt axolotl can play dead to heal up while enemies lose interest.', 290, true, 'choice', null::jsonb, null::text[]),
  ('portal-frame-ten-obsidian', 'What''s the fewest obsidian blocks you need for a Nether portal frame?', '12', '10', '8', '14', 1, 'The smallest frame is 4 wide and 5 tall, and the corners can be skipped, leaving 10 obsidian.', 291, true, 'choice', null::jsonb, null::text[]),
  ('netherite-ingot-four-scraps', 'How many netherite scraps go into one netherite ingot?', '4', '9', '2', '8', 0, 'A netherite ingot is crafted from 4 netherite scraps and 4 gold ingots.', 292, true, 'choice', null::jsonb, null::text[]),
  ('respawn-anchor-four-charges', 'How many charges can a respawn anchor hold at most?', '4', '8', '3', '5', 0, 'Each glowstone block adds one charge, up to 4, and every respawn uses one up.', 293, true, 'choice', null::jsonb, null::text[]),
  ('respawn-anchor-explodes-outside-nether', 'What happens if you try to set your spawn at a charged respawn anchor in the Overworld?', 'It sets your spawn', 'It turns to obsidian', 'It explodes', 'Nothing happens', 2, 'Respawn anchors only work in the Nether; anywhere else a charged one blows up like a bed.', 294, true, 'choice', null::jsonb, null::text[]),
  ('shroomlight-in-huge-fungi', 'Which glowing block grows in the caps of huge Nether fungi?', 'Sea Lantern', 'Glowstone', 'Magma Block', 'Shroomlight', 3, 'Shroomlights are light blocks found near the tops of huge crimson and warped fungi.', 295, true, 'choice', null::jsonb, null::text[]),
  ('strider-drops-string', 'What do striders drop when defeated?', 'Magma Cream', 'String', 'Leather', 'Feather', 1, 'Striders drop 2 to 5 string, plus their saddle if they were wearing one.', 296, true, 'choice', null::jsonb, null::text[]),
  ('four-crystals-respawn-dragon', 'How many end crystals do you need to respawn the Ender Dragon?', '6', '2', '8', '4', 3, 'Put one end crystal on each side of the exit portal, four in total, to bring the dragon back.', 297, true, 'choice', null::jsonb, null::text[]),
  ('ghast-tear-in-end-crystal-recipe', 'Which Nether mob drop is part of the end crystal recipe?', 'Ghast Tear', 'Blaze Powder', 'Magma Cream', 'Blaze Rod', 0, 'An end crystal is crafted from 7 glass, an eye of ender and a ghast tear.', 298, true, 'choice', null::jsonb, null::text[]),
  ('ender-chest-recipe-eye-center', 'What goes in the center of the ender chest recipe?', 'Diamond', 'Blaze Rod', 'Eye of Ender', 'Ender Pearl', 2, 'Surround an eye of ender with eight obsidian to craft an ender chest.', 299, true, 'choice', null::jsonb, null::text[]),
  ('shulker-box-needs-two-shells', 'How many shulker shells does a shulker box recipe need?', '4', '1', '2', '3', 2, 'Put a chest between two shulker shells to craft a shulker box.', 300, true, 'choice', null::jsonb, null::text[]),
  ('phantom-membrane-repairs-elytra', 'Which item repairs elytra in an anvil?', 'Phantom Membrane', 'Feather', 'String', 'Leather', 0, 'Each phantom membrane restores a quarter of the elytra''s durability in an anvil.', 301, true, 'choice', null::jsonb, null::text[]),
  ('end-rod-from-popped-chorus', 'Which thin white light is crafted with popped chorus fruit?', 'Torch', 'Candle', 'End Rod', 'Lantern', 2, 'A blaze rod and popped chorus fruit craft four end rods, the lights that decorate End cities.', 302, true, 'choice', null::jsonb, null::text[]),
  ('ten-obsidian-pillars-in-end', 'How many obsidian pillars stand around the End''s main island?', '8', '10', '6', '12', 1, 'Ten obsidian pillars ring the main island, and two of them have iron bar cages on top.', 303, true, 'choice', null::jsonb, null::text[]),
  ('thrown-eye-of-ender-can-break', 'What can happen to an eye of ender after you throw it?', 'It turns into a pearl', 'It explodes', 'It spawns an enderman', 'It can shatter', 3, 'Each thrown eye has a 20% chance to shatter, so bring spares when hunting for a stronghold.', 304, true, 'choice', null::jsonb, null::text[]),
  ('beds-explode-in-the-end', 'Besides the Nether, where does trying to sleep in a bed make it explode?', 'Mushroom Fields', 'The End', 'Deep Dark', 'Desert', 1, 'Beds only work in the Overworld; in the Nether and the End they blow up instead.', 305, true, 'choice', null::jsonb, null::text[]),
  ('dragon-head-on-end-ship', 'Which mob head decorates the front of an End ship?', 'Wither Skeleton Skull', 'Dragon Head', 'Piglin Head', 'Creeper Head', 1, 'The head on an End ship''s bow is the only way to get a dragon head in survival.', 306, true, 'choice', null::jsonb, null::text[]),
  ('redstone-max-signal-fifteen', 'What is the highest signal strength in redstone?', '15', '20', '16', '10', 0, 'Redstone signals range from 0 to 15, and dust loses one level for every block it travels.', 307, true, 'choice', null::jsonb, null::text[]),
  ('piston-pushes-twelve-blocks', 'How many blocks can a single piston push at once?', '16', '12', '64', '8', 1, 'A piston can move up to 12 blocks in a row; with one more it won''t extend at all.', 308, true, 'choice', null::jsonb, null::text[]),
  ('comparator-needs-nether-quartz', 'Which Nether item do you need to craft a redstone comparator?', 'Glowstone Dust', 'Blaze Powder', 'Magma Cream', 'Nether Quartz', 3, 'A comparator is made from nether quartz, three redstone torches and three stone.', 309, true, 'choice', null::jsonb, null::text[]),
  ('redstone-lamp-glowstone-center', 'Which block sits in the middle of the redstone lamp recipe?', 'Glowstone', 'Block of Redstone', 'Redstone Torch', 'Sea Lantern', 0, 'Four redstone dust around a glowstone block craft a redstone lamp.', 310, true, 'choice', null::jsonb, null::text[]),
  ('powered-rail-needs-gold', 'Which metal do you need to craft powered rails?', 'Netherite Ingot', 'Copper Ingot', 'Gold Ingot', 'Iron Ingot', 2, 'Powered rails use gold ingots, a stick and redstone dust, and one craft gives six.', 311, true, 'choice', null::jsonb, null::text[]),
  ('powered-hopper-gets-locked', 'What does a hopper do when it gets a redstone signal?', 'It drops all its items', 'It stops moving items', 'It pulls from far away', 'It moves items faster', 1, 'A powered hopper is locked: it stops pulling and pushing items until the signal turns off.', 312, true, 'choice', null::jsonb, null::text[]),
  ('piston-recipe-iron-ingot', 'Which item from this list is part of the piston recipe?', 'Diamond', 'Iron Ingot', 'Gold Ingot', 'Copper Ingot', 1, 'A piston is crafted from planks, cobblestone, redstone dust and one iron ingot.', 313, true, 'choice', null::jsonb, null::text[]),
  ('note-block-sound-from-block-below', 'What decides which instrument a note block plays?', 'The block under it', 'The biome it''s in', 'The time of day', 'How hard you hit it', 0, 'The block under a note block sets its sound: wood gives bass, sand a snare, gold a bell.', 314, true, 'choice', null::jsonb, null::text[]),
  ('zombified-piglin-gold-nuggets', 'Besides rotten flesh, what do zombified piglins commonly drop?', 'Golden Carrot', 'Raw Gold', 'Gold Nugget', 'Iron Nugget', 2, 'Zombified piglins often drop gold nuggets, and gold farms use them for lots of gold.', 315, true, 'choice', null::jsonb, null::text[]),
  ('ancient-debris-blast-proof', 'Which Nether ore is so tough that explosions can''t destroy it?', 'Ancient Debris', 'Nether Gold Ore', 'Nether Quartz Ore', 'Glowstone', 0, 'Ancient debris survives explosions, which is why players can blast netherrack to find it.', 316, true, 'choice', null::jsonb, null::text[]),
  ('twenty-end-gateways', 'How many End gateway portals can appear around the main End island?', '12', '10', '4', '20', 3, 'Each dragon fight opens one more gateway, up to 20 around the main island.', 317, true, 'choice', null::jsonb, null::text[]),
  ('dragons-breath-lingering', 'Brewing dragon''s breath into a splash potion turns it into what?', 'Mundane Potion', 'Thick Potion', 'Lingering Potion', 'Awkward Potion', 2, 'Dragon''s breath turns a splash potion into a lingering potion that leaves a cloud behind.', 318, true, 'choice', null::jsonb, null::text[]),
  ('repeater-locked-from-side', 'What happens to a repeater powered from the side by another repeater?', 'It gets locked', 'It turns off forever', 'It breaks', 'It doubles the signal', 0, 'A side-powered repeater gets locked and keeps its current output until it is unlocked.', 319, true, 'choice', null::jsonb, null::text[]),
  ('regen-needs-nine-drumsticks', 'What is the fewest drumsticks you need for your health to heal by itself?', '9', '10', '5', '7', 0, 'Natural healing needs at least 18 hunger points, which is 9 full drumsticks.', 320, true, 'choice', null::jsonb, null::text[]),
  ('sprint-stops-three-drumsticks', 'At how many drumsticks or fewer can you no longer sprint?', '1', '7', '3', '5', 2, 'When hunger drops to 6 points, or 3 drumsticks, you can''t start sprinting until you eat.', 321, true, 'choice', null::jsonb, null::text[]),
  ('enchanted-golden-apple-uncraftable', 'Which golden food can''t be crafted and is only found in chests?', 'Enchanted Golden Apple', 'Golden Apple', 'Golden Carrot', 'Glistering Melon Slice', 0, 'Enchanted golden apples can''t be crafted, so you only find them as rare chest loot.', 322, true, 'choice', null::jsonb, null::text[]),
  ('poison-leaves-half-heart', 'How low can Poison drop your health?', 'Half a heart', 'Five hearts', 'Two hearts', 'All the way to zero', 0, 'Poison stops at 1 health point, half a heart, so it can''t defeat you by itself.', 323, true, 'choice', null::jsonb, null::text[]),
  ('dropped-items-despawn-five-minutes', 'How many minutes do dropped items last on the ground before vanishing?', '5', '20', '1', '10', 0, 'Items on the ground vanish after 5 minutes in a loaded area, so grab your stuff quickly after dying.', 324, true, 'choice', null::jsonb, null::text[]),
  ('mushroom-stew-does-not-stack', 'Which of these foods can''t stack, so each one takes a whole slot?', 'Mushroom Stew', 'Cookie', 'Bread', 'Apple', 0, 'Mushroom stew doesn''t stack, so every bowl uses its own inventory slot.', 325, true, 'choice', null::jsonb, null::text[]),
  ('full-diamond-armor-twenty-points', 'How many armor points does a full set of diamond armor give?', '20', '15', '24', '10', 0, 'Diamond helmet, chestplate, leggings and boots add up to 20 armor points, filling the whole armor bar.', 326, true, 'choice', null::jsonb, null::text[]),
  ('saturation-hidden-food-value', 'Which hidden food value is used up before your hunger bar starts to drop?', 'Absorption', 'Experience', 'Saturation', 'Durability', 2, 'Saturation is invisible extra fullness; while it lasts, your hunger bar stays still.', 327, true, 'choice', null::jsonb, null::text[]),
  ('starving-ignores-armor', 'Which kind of damage does your armor never reduce?', 'Starving', 'Arrow hits', 'Explosions', 'Zombie hits', 0, 'Starving damage goes straight through armor and Protection, so only food can stop it.', 328, true, 'choice', null::jsonb, null::text[]),
  ('glass-blocks-mob-spawning', 'Hostile mobs can''t spawn on top of which see-through block?', 'Glass', 'Stone', 'Sand', 'Grass Block', 0, 'Glass is transparent, so monsters can''t spawn on it, which makes glass roofs extra safe.', 329, true, 'choice', null::jsonb, null::text[]),
  ('torch-light-level-14', 'What light level does a regular torch give off?', '15', '10', '12', '14', 3, 'A torch shines at light level 14, while a soul torch gives only 10.', 330, true, 'choice', null::jsonb, null::text[]),
  ('lantern-brightest-light', 'Which of these light blocks shines the brightest?', 'Soul Torch', 'Redstone Torch', 'Lantern', 'Torch', 2, 'A lantern gives light level 15, brighter than a torch (14), a soul torch (10) or a redstone torch (7).', 331, true, 'choice', null::jsonb, null::text[]),
  ('mobs-spawn-24-blocks-away', 'Hostile mobs never spawn closer to you than how many blocks?', '32', '24', '16', '8', 1, 'Mobs can''t spawn within 24 blocks of a player, so the monsters you meet walked over from farther away.', 332, true, 'choice', null::jsonb, null::text[]),
  ('daytime-lasts-ten-minutes', 'About how many real minutes does the daytime part of a Minecraft day last?', '5', '15', '20', '10', 3, 'Daytime lasts 10 real minutes, half of the full 20-minute day-and-night cycle.', 333, true, 'choice', null::jsonb, null::text[]),
  ('bottom-slab-blocks-spawning', 'Which half-height block, placed low, stops mobs from spawning on it?', 'Dirt', 'Sandstone', 'Stone', 'Slab', 3, 'Mobs can''t spawn on bottom slabs, so a slab floor keeps a base safe even in the dark.', 334, true, 'choice', null::jsonb, null::text[]),
  ('carpet-blocks-mob-spawning', 'Covering a dark floor with which soft block stops mobs spawning there?', 'Moss Block', 'Carpet', 'Hay Bale', 'Wool', 1, 'Mobs can''t spawn on carpet, so carpeted floors stay safe even without torches.', 335, true, 'choice', null::jsonb, null::text[]),
  ('dungeon-spawner-mostly-zombies', 'Which mob comes out of dungeon monster spawners most often?', 'Zombie', 'Creeper', 'Skeleton', 'Spider', 0, 'Half of all dungeon spawners make zombies; the rest make skeletons or spiders, never creepers.', 336, true, 'choice', null::jsonb, null::text[]),
  ('spider-hostile-light-eleven', 'Spiders turn hostile when the light around them drops to what level or lower?', '7', '0', '14', '11', 3, 'At light level 11 or lower spiders attack on sight, so a brightly lit base keeps them calm.', 337, true, 'choice', null::jsonb, null::text[]),
  ('lightning-pig-zombified-piglin', 'When lightning strikes a pig, what does the pig turn into?', 'Hoglin', 'Piglin', 'Zombified Piglin', 'Zoglin', 2, 'Lightning turns a pig into a zombified piglin, unless the game is on Peaceful.', 338, true, 'choice', null::jsonb, null::text[]),
  ('lightning-villager-witch', 'Which mob does a villager become when lightning strikes near it?', 'Pillager', 'Witch', 'Zombie Villager', 'Evoker', 1, 'A lightning strike within a few blocks turns a villager into a witch.', 339, true, 'choice', null::jsonb, null::text[]),
  ('breath-lasts-fifteen-seconds', 'How many seconds of air do you have underwater before you start drowning?', '30', '5', '60', '15', 3, 'Your air bubbles last 15 seconds, then you take drowning damage every second until you surface.', 340, true, 'choice', null::jsonb, null::text[]),
  ('water-flows-seven-blocks', 'On flat ground, how many blocks does water spread from its source?', '7', '5', '10', '3', 0, 'Water spreads 7 blocks across flat ground, and it can flow down as far as it likes.', 341, true, 'choice', null::jsonb, null::text[]),
  ('conduit-power-underwater', 'Which ocean block lets nearby players breathe and see well underwater?', 'Conduit', 'Prismarine', 'Sea Lantern', 'Beacon', 0, 'An activated conduit gives Conduit Power: water breathing, night vision and faster mining underwater.', 342, true, 'choice', null::jsonb, null::text[]),
  ('falling-sand-breaks-on-torch', 'What happens when falling sand lands on a torch?', 'It floats in midair', 'It turns into glass', 'It puts the torch out', 'It breaks into an item', 3, 'Falling sand or gravel that lands on a torch pops into an item, a handy trick for clearing columns fast.', 343, true, 'choice', null::jsonb, null::text[]),
  ('powder-snow-needs-bucket', 'Which tool is the only way to collect powder snow?', 'Shears', 'Bucket', 'Shovel', 'Pickaxe', 1, 'Powder snow drops nothing when mined, so you scoop it up with a bucket instead.', 344, true, 'choice', null::jsonb, null::text[]),
  ('ender-pearls-stack-to-16', 'How many ender pearls fit in one inventory stack?', '16', '64', '8', '32', 0, 'Ender pearls stack only to 16, so bring a few stacks for long trips.', 345, true, 'choice', null::jsonb, null::text[]),
  ('fall-damage-per-block', 'For each block you fall beyond 3, how much health do you lose?', 'Three hearts', 'Two hearts', 'Half a heart', 'One heart', 2, 'Fall damage is about 1 health point, half a heart, for every block past the first 3.', 346, true, 'choice', null::jsonb, null::text[]),
  ('cobweb-cancels-fall-damage', 'Falling into which block cancels all fall damage?', 'Honey Block', 'Cobweb', 'Sand', 'Hay Bale', 1, 'A cobweb catches you and cancels fall damage, while a hay bale only softens the landing.', 347, true, 'choice', null::jsonb, null::text[]),
  ('lava-flows-three-blocks', 'In the Overworld, how many blocks does lava flow sideways from its source?', '5', '1', '3', '7', 2, 'Overworld lava only flows 3 blocks out from its source, much less than water.', 348, true, 'choice', null::jsonb, null::text[]),
  ('steak-four-drumsticks', 'How many drumsticks of hunger does one steak refill?', '2', '3', '4', '6', 2, 'A steak restores 8 hunger points, which is 4 full drumsticks.', 349, true, 'choice', null::jsonb, null::text[]),
  ('thirteen-villager-professions', 'How many villager professions have their own job block?', '10', '12', '13', '15', 2, 'Thirteen professions each have a job block, while nitwits and unemployed villagers have none.', 350, true, 'choice', null::jsonb, null::text[]),
  ('leatherworker-sells-saddle', 'Which master-level villager sells saddles?', 'Cartographer', 'Shepherd', 'Leatherworker', 'Butcher', 2, 'Master leatherworkers sell saddles for emeralds.', 351, true, 'choice', null::jsonb, null::text[]),
  ('shepherd-sells-paintings', 'Paintings can be bought from which master villager?', 'Shepherd', 'Mason', 'Cartographer', 'Librarian', 0, 'Master shepherds sell paintings for emeralds.', 352, true, 'choice', null::jsonb, null::text[]),
  ('cleric-sells-ender-pearls', 'Which villager can trade you ender pearls?', 'Cleric', 'Mason', 'Cartographer', 'Librarian', 0, 'Expert clerics sell ender pearls for emeralds.', 353, true, 'choice', null::jsonb, null::text[]),
  ('farmer-sells-golden-carrots', 'A master villager sells golden carrots. What is its job?', 'Butcher', 'Farmer', 'Cleric', 'Fisherman', 1, 'Master farmers sell golden carrots and glistering melon slices.', 354, true, 'choice', null::jsonb, null::text[]),
  ('cartographer-sells-globe-pattern', 'Which villager sells the globe banner pattern?', 'Shepherd', 'Cartographer', 'Librarian', 'Mason', 1, 'Master cartographers sell the globe banner pattern.', 355, true, 'choice', null::jsonb, null::text[]),
  ('fisherman-sells-enchanted-rod', 'Which villager may offer an enchanted fishing rod?', 'Fletcher', 'Toolsmith', 'Librarian', 'Fisherman', 3, 'Journeyman fishermen can sell enchanted fishing rods.', 356, true, 'choice', null::jsonb, null::text[]),
  ('composter-seven-slabs', 'How many wooden slabs does it take to craft a composter?', '5', '6', '7', '4', 2, 'A composter is crafted from 7 wooden slabs of any wood.', 357, true, 'choice', null::jsonb, null::text[]),
  ('smithing-table-needs-iron', 'To craft a smithing table, what goes with the planks?', 'Iron Ingot', 'Gold Ingot', 'Leather', 'Diamond', 0, 'A smithing table is crafted from iron ingots and planks.', 358, true, 'choice', null::jsonb, null::text[]),
  ('cauldron-seven-iron-ingots', 'How many iron ingots craft a leatherworker’s cauldron?', '5', '7', '6', '8', 1, 'A cauldron is crafted from 7 iron ingots.', 359, true, 'choice', null::jsonb, null::text[]),
  ('blast-furnace-needs-smooth-stone', 'A blast furnace needs iron, a furnace and which block?', 'Smooth Stone', 'Cobblestone', 'Stone Bricks', 'Obsidian', 0, 'A blast furnace is crafted from iron ingots, a furnace and smooth stone.', 360, true, 'choice', null::jsonb, null::text[]),
  ('baby-villager-grows-in-20-minutes', 'How many minutes does a baby villager take to grow up?', '5', '20', '40', '10', 1, 'A baby villager becomes an adult 20 minutes after it is born.', 361, true, 'choice', null::jsonb, null::text[]),
  ('hero-effect-lasts-40-minutes', 'How long does the Hero of the Village effect last?', '10 minutes', '1 hour', '40 minutes', '20 minutes', 2, 'Hero of the Village lasts 40 minutes, so trade a lot after a raid.', 362, true, 'choice', null::jsonb, null::text[]),
  ('master-villager-diamond-badge', 'What material is the badge of a master villager?', 'Iron', 'Emerald', 'Diamond', 'Gold', 2, 'Badges go stone, iron, gold, emerald and finally diamond for masters.', 363, true, 'choice', null::jsonb, null::text[]),
  ('journeyman-follows-apprentice', 'Which trading level comes right after Apprentice?', 'Novice', 'Journeyman', 'Master', 'Expert', 1, 'Level 3, Journeyman, comes after Apprentice and before Expert.', 364, true, 'choice', null::jsonb, null::text[]),
  ('seven-villager-biome-outfits', 'How many different biome outfits can villagers wear?', '9', '7', '4', '5', 1, 'Villagers dress for desert, jungle, plains, savanna, snowy, swamp or taiga biomes.', 365, true, 'choice', null::jsonb, null::text[]),
  ('master-cleric-buys-nether-wart', 'Which Nether plant can you sell to a master cleric?', 'Nether Wart', 'Warped Fungus', 'Weeping Vines', 'Crimson Fungus', 0, 'Master clerics buy nether wart, the key ingredient for potions.', 366, true, 'choice', null::jsonb, null::text[]),
  ('master-butcher-buys-sweet-berries', 'Which villager buys sweet berries at the master level?', 'Farmer', 'Butcher', 'Fisherman', 'Shepherd', 1, 'Master butchers trade emeralds for sweet berries.', 367, true, 'choice', null::jsonb, null::text[]),
  ('fisherman-buys-string-and-coal', 'Which villager buys both string and coal from you?', 'Fisherman', 'Librarian', 'Farmer', 'Cartographer', 0, 'Novice fishermen buy string and coal for emeralds.', 368, true, 'choice', null::jsonb, null::text[]),
  ('wandering-trader-drinks-milk', 'What does a wandering trader drink when morning comes?', 'Water Bottle', 'Milk Bucket', 'Honey Bottle', 'Potion of Invisibility', 1, 'In the morning the wandering trader drinks milk to stop being invisible.', 369, true, 'choice', null::jsonb, null::text[]),
  ('leatherworker-buys-rabbit-hide', 'Which villager pays emeralds for rabbit hide?', 'Leatherworker', 'Butcher', 'Farmer', 'Shepherd', 0, 'Journeyman leatherworkers buy rabbit hide for emeralds.', 370, true, 'choice', null::jsonb, null::text[]),
  ('villager-has-ten-hearts', 'How many hearts of health does a villager have?', '10', '15', '5', '20', 0, 'A villager has 20 health points, which is 10 hearts.', 371, true, 'choice', null::jsonb, null::text[]),
  ('infinity-conflicts-with-mending', 'Which bow enchantment can’t be on the same bow as Mending?', 'Punch', 'Power', 'Flame', 'Infinity', 3, 'Infinity and Mending are mutually exclusive, so a bow can have only one of them.', 372, true, 'choice', null::jsonb, null::text[]),
  ('grindstone-keeps-curses', 'Which enchantments stay on an item after using a grindstone?', 'Mending', 'Protection', 'Curses', 'Unbreaking', 2, 'A grindstone strips most enchantments, but curses always stay on the item.', 373, true, 'choice', null::jsonb, null::text[]),
  ('cartographer-sells-item-frames', 'Which villager sells item frames once it levels up?', 'Librarian', 'Cartographer', 'Cleric', 'Leatherworker', 1, 'An experienced cartographer sells item frames, handy for showing off maps.', 374, true, 'choice', null::jsonb, null::text[]),
  ('mason-sells-quartz', 'Which villager sells blocks of quartz at the master level?', 'Armorer', 'Mason', 'Toolsmith', 'Cleric', 1, 'A master mason sells quartz blocks and pillars, so you don''t need to mine in the Nether.', 375, true, 'choice', null::jsonb, null::text[]),
  ('armorer-sells-chainmail', 'Which villager sells chainmail armor?', 'Mason', 'Leatherworker', 'Weaponsmith', 'Armorer', 3, 'Chainmail can''t be crafted, but an armorer will sell it to you for emeralds.', 376, true, 'choice', null::jsonb, null::text[]),
  ('expert-badge-emerald', 'An expert-level villager wears a badge made of what?', 'Diamond', 'Gold', 'Iron', 'Emerald', 3, 'Badges go stone, iron, gold, emerald and diamond, so an expert wears emerald.', 377, true, 'choice', null::jsonb, null::text[]),
  ('fisherman-sells-campfire', 'Which villager sells campfires?', 'Armorer', 'Butcher', 'Farmer', 'Fisherman', 3, 'A fisherman sells campfires, which are handy for cooking the fish you catch.', 378, true, 'choice', null::jsonb, null::text[]),
  ('fortune-and-silk-touch-clash', 'Which enchantment can never go on the same pickaxe as Silk Touch?', 'Efficiency', 'Mending', 'Unbreaking', 'Fortune', 3, 'Fortune and Silk Touch cancel each other out, so a tool can only have one of them.', 379, true, 'choice', null::jsonb, null::text[])
) as v(content_id, prompt, option_a, option_b, option_c, option_d, correct_option, explanation, sort_order, is_active, kind, media, option_icons)
where pack.slug = 'minecraft-hard'
on conflict (pack_id, content_id) do update set
  prompt = excluded.prompt,
  option_a = excluded.option_a,
  option_b = excluded.option_b,
  option_c = excluded.option_c,
  option_d = excluded.option_d,
  correct_option = excluded.correct_option,
  explanation = excluded.explanation,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active,
  kind = excluded.kind,
  media = excluded.media,
  option_icons = excluded.option_icons;

insert into public.question_translations (question_id, locale, prompt, option_a, option_b, option_c, option_d, explanation)
select question.id, v.locale, v.prompt, v.option_a, v.option_b, v.option_c, v.option_d, v.explanation
from public.questions question
join public.question_packs pack on pack.id = question.pack_id and pack.slug = 'minecraft-hard'
join (values
  ('amethyst-geode-underground', 'uk', 'Який блок утворює зовнішню оболонку аметистової жеоди?', 'Гладкий базальт', 'Глибосланець', 'Кальцит', 'Обсидіан', 'Жеода має три шари: гладкий базальт зовні, кальцит посередині й аметист усередині.'),
  ('amethyst-geode-underground', 'en', 'Which block forms the outer shell of an amethyst geode?', 'Smooth Basalt', 'Deepslate', 'Calcite', 'Obsidian', 'Geodes have three layers: smooth basalt outside, calcite in the middle and amethyst inside.'),
  ('amethyst-geode-underground', 'ru', 'Какой блок образует внешнюю оболочку аметистовой жеоды?', 'Гладкий базальт', 'Глубинный сланец', 'Кальцит', 'Обсидиан', 'У жеоды три слоя: гладкий базальт снаружи, кальцит в середине и аметист внутри.'),
  ('ocean-ruins-underwater', 'uk', 'Яку рідкісну річ дає пензель із підозрілого піску теплих підводних руїн?', 'Мушля навтилуса', 'Тризубець', 'Яйце нюхача', 'Яйце черепахи', 'Підозрілий пісок теплих підводних руїн може містити яйце нюхача, з якого вилупиться нюхач.'),
  ('ocean-ruins-underwater', 'en', 'Brushing suspicious sand in warm ocean ruins can give which rare item?', 'Nautilus Shell', 'Trident', 'Sniffer Egg', 'Turtle Egg', 'Suspicious sand in warm ocean ruins can hold a sniffer egg, which hatches into a sniffer.'),
  ('ocean-ruins-underwater', 'ru', 'Какую редкую вещь даёт кисть из подозрительного песка тёплых подводных руин?', 'Раковина наутилуса', 'Трезубец', 'Яйцо нюхача', 'Черепашье яйцо', 'В подозрительном песке тёплых подводных руин может найтись яйцо нюхача, из него вылупится нюхач.'),
  ('ancient-city-deep-dark', 'uk', 'Який блок утворює велику рамку, схожу на портал, у центрі стародавнього міста?', 'Посилений глибосланець', 'Корінна порода', 'Обсидіан', 'Плакучий обсидіан', 'Таємнича рамка стародавнього міста складена з посиленого глибосланцю, який більше ніде не з’являється.'),
  ('ancient-city-deep-dark', 'en', 'Which block forms the giant portal-like frame in the middle of an ancient city?', 'Reinforced Deepslate', 'Bedrock', 'Obsidian', 'Crying Obsidian', 'The strange frame in ancient cities is built from reinforced deepslate, which generates nowhere else.'),
  ('ancient-city-deep-dark', 'ru', 'Какой блок образует большую рамку, похожую на портал, в центре древнего города?', 'Укреплённый глубинный сланец', 'Бедрок', 'Обсидиан', 'Плачущий обсидиан', 'Загадочная рамка древнего города сложена из укреплённого глубинного сланца, больше он нигде не появляется.'),
  ('badlands-above-ground-mineshafts', 'uk', 'У якому біомі шахти часто виходять просто на поверхню?', 'Безплідні землі', 'Пустеля', 'Тайга', 'Джунглі', 'У безплідних землях шахти з’являються на рівні поверхні, і їхні тунелі стирчать із пагорбів.'),
  ('badlands-above-ground-mineshafts', 'en', 'In which biome do mineshafts often stick out above the ground?', 'Badlands', 'Desert', 'Taiga', 'Jungle', 'In badlands, mineshafts can generate at surface level, so their tunnels poke out of the hills.'),
  ('badlands-above-ground-mineshafts', 'ru', 'В каком биоме шахты часто выходят прямо на поверхность?', 'Бесплодные земли', 'Пустыня', 'Тайга', 'Джунгли', 'В бесплодных землях шахты появляются на уровне поверхности, и их тоннели торчат из холмов.'),
  ('bastion-remnant-nether', 'uk', 'Який моб із сокирою охороняє залишки бастіону й ніколи не відроджується?', 'Візер-скелет', 'Брутальний піґлін', 'Зомбований піґлін', 'Поборник', 'Брутальні піґліни з’являються лише разом із бастіоном і нападають навіть на гравців у золоті.'),
  ('bastion-remnant-nether', 'en', 'Which axe-wielding mob guards bastion remnants and never respawns?', 'Wither Skeleton', 'Piglin Brute', 'Zombified Piglin', 'Vindicator', 'Piglin brutes appear only when a bastion generates and attack players even in gold armor.'),
  ('bastion-remnant-nether', 'ru', 'Какой моб с топором охраняет развалины бастиона и никогда не возрождается?', 'Визер-скелет', 'Брутальный пиглин', 'Зомбифицированный пиглин', 'Поборник', 'Брутальные пиглины появляются только вместе с бастионом и нападают даже на игроков в золоте.'),
  ('buried-treasure-found-from-map', 'uk', 'Який предмет гарантовано є в кожній скрині закопаного скарбу?', 'Серце моря', 'Мушля навтилуса', 'Тотем безсмертя', 'Тризубець', 'У кожному закопаному скарбі лежить одне серце моря, тож такі скрині варто шукати за мапою.'),
  ('buried-treasure-found-from-map', 'en', 'Which item is guaranteed in every buried treasure chest?', 'Heart of the Sea', 'Nautilus Shell', 'Totem of Undying', 'Trident', 'Each buried treasure chest has one heart of the sea, the key part of a conduit.'),
  ('buried-treasure-found-from-map', 'ru', 'Какой предмет гарантированно лежит в каждом сундуке зарытого клада?', 'Сердце моря', 'Раковина наутилуса', 'Тотем бессмертия', 'Трезубец', 'В каждом зарытом кладе лежит одно сердце моря, поэтому клады стоит искать по карте.'),
  ('desert-well-desert', 'uk', 'Який блок можна почистити пензлем у пустельному колодязі?', 'Підозрілий гравій', 'Пісковик', 'Пісок душ', 'Підозрілий пісок', 'Під водою пустельного колодязя ховається підозрілий пісок, з якого пензлем дістають черепки.'),
  ('desert-well-desert', 'en', 'Which brushable block can be found inside a desert well?', 'Suspicious Gravel', 'Sandstone', 'Soul Sand', 'Suspicious Sand', 'Desert wells hide suspicious sand under the water, and brushing it can give pottery sherds.'),
